#[cfg(test)]
/// How many 10ms polls a test waits for a child process to signal that it
/// reached a checkpoint.
///
/// Every one of those checkpoints sits behind a process launch — a second
/// copy of this test binary, `lockf`, or `/usr/bin/swift`, which takes over
/// ten seconds to start on a loaded machine or a cold toolchain cache. The
/// assertions are about what the child does at the checkpoint, so the wait
/// must not double as a stopwatch on how fast the OS got it there.
pub(crate) const CHECKPOINT_POLLS: usize = 3_000;
pub(crate) fn test_app(data_file: PathBuf) -> OperonApp {
    OperonApp::from_state(data_file, Store::default(), ToolStatus::default(), None)
}

/// One record read as the restore reads it, per provider. The readers take a
/// classification summary the tests below do not assert on; these keep the
/// assertions about what crosses rather than about the plumbing that counts it.
pub(crate) fn transcript_value_turn_claude(
    value: &serde_json::Value,
) -> Option<(&'static str, String)> {
    transcript_value_turn(value, CliProvider::Claude)
}

pub(crate) fn transcript_value_turn_codex(
    value: &serde_json::Value,
) -> Option<(&'static str, String)> {
    transcript_value_turn(value, CliProvider::Codex)
}

pub(crate) fn transcript_value_turn_gemini(
    value: &serde_json::Value,
) -> Option<(&'static str, String)> {
    transcript_value_turn(value, CliProvider::Gemini)
}

/// The Codex item one source record becomes. The restore builds these from the
/// projected turns rather than per record now, so this composes the two halves
/// to keep the tests that pin the item shape about the shape.
pub(crate) fn codex_item_for_record(
    record: &str,
    provider: CliProvider,
    index: usize,
) -> Option<serde_json::Value> {
    transcript_conversation_turn(record, provider)
        .map(|(role, text)| codex_import_item(role, &text, index))
}

/// The turns a source transcript projects to. The Codex verifiers used to take
/// the source path and re-read it themselves; they now take the projection the
/// restore actually wrote, so the tests hand them the same thing.
pub(crate) fn turns_in(path: &Path, provider: CliProvider) -> Vec<(&'static str, String)> {
    read_transcript_conversation_turns(path, provider).unwrap()
}

pub(crate) fn wait_for_background_task(
    app: &mut OperonApp,
    key: &BackgroundKey,
    timeout: Duration,
) {
    let deadline = Instant::now() + timeout;
    while app.background_tasks.contains(key) && Instant::now() < deadline {
        app.process_background_results();
        thread::sleep(Duration::from_millis(10));
    }
    app.process_background_results();
    assert!(
        !app.background_tasks.contains(key),
        "background task {key:?} did not finish within {timeout:?}"
    );
}

#[test]
pub(crate) fn shared_history_snapshot_preserves_the_source_jsonl_byte_for_byte() {
    let root = std::env::temp_dir().join(format!("operon-history-{}", Uuid::new_v4()));
    let source = root.join("source.jsonl");
    let archive_root = root.join("shared-sessions");
    let bytes = b"{\"type\":\"user\",\"message\":\"first\"}\nnot valid json\n";
    fs::create_dir_all(&root).unwrap();
    fs::write(&source, bytes).unwrap();

    let snapshot = snapshot_native_transcript(&source, &archive_root, Uuid::new_v4()).unwrap();

    assert_eq!(fs::read(snapshot).unwrap(), bytes);
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn accepts_a_codex_session_file_after_the_app_server_has_flushed_it() {
    let root = std::env::temp_dir().join(format!("operon-codex-flush-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let transcript = root.join("session.jsonl");
    fs::write(&transcript, "{}\n").unwrap();

    assert_eq!(
        wait_for_codex_session_file(&transcript).unwrap(),
        transcript
    );
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn codex_history_verification_requires_every_imported_turn_to_match() {
    let root = std::env::temp_dir().join(format!("operon-history-verify-{}", Uuid::new_v4()));
    let source = root.join("source.jsonl");
    let destination = root.join("destination.jsonl");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        &source,
        concat!(
            r#"{"type":"attachment","attachment":{"type":"hook_success"}}"#,
            "\n",
            r#"{"type":"user","message":{"content":"short-user"}}"#,
            "\n",
            r#"{"type":"assistant","message":{"content":"short-assistant"}}"#,
            "\n",
        ),
    )
    .unwrap();
    fs::write(
        &destination,
        concat!(
            r#"{"type":"response_item","payload":{"type":"message","id":"operon-import-0","role":"user","content":[{"type":"input_text","text":"short-user"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","id":"operon-import-1","role":"assistant","content":[{"type":"output_text","text":"short-assistant"}]}}"#,
            "\n",
        ),
    )
    .unwrap();

    assert!(verify_codex_imported_transcript(
        &destination,
        &turns_in(&source, CliProvider::Claude)
    )
    .is_ok());
    fs::write(
        &destination,
        r#"{"type":"response_item","payload":{"type":"message","id":"operon-import-0","role":"user","content":[{"type":"input_text","text":"wrong"}]}}"#,
    )
    .unwrap();
    assert!(verify_codex_imported_transcript(
        &destination,
        &turns_in(&source, CliProvider::Claude)
    )
    .unwrap_err()
    .contains("異なる内容を保存しました"));
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn codex_import_items_keep_claude_conversation_turns_readable() {
    let user = r#"{"type":"user","message":{"content":"hello"}}"#;
    let assistant =
        r#"{"type":"assistant","message":{"content":[{"type":"text","text":"world"}]}}"#;

    let user_item = codex_item_for_record(user, CliProvider::Claude, 0).unwrap();
    let assistant_item = codex_item_for_record(assistant, CliProvider::Claude, 1).unwrap();

    assert_eq!(user_item["role"], "user");
    assert_eq!(user_item["content"][0]["type"], "input_text");
    assert_eq!(user_item["content"][0]["text"], "hello");
    assert_eq!(assistant_item["role"], "assistant");
    assert_eq!(assistant_item["content"][0]["type"], "output_text");
    assert_eq!(assistant_item["content"][0]["text"], "world");
}

#[test]
pub(crate) fn codex_import_skips_claude_operational_metadata() {
    let metadata = r#"{"type":"attachment","attachment":{"type":"hook_success"}}"#;

    assert!(codex_item_for_record(metadata, CliProvider::Claude, 0).is_none());
}

#[test]
pub(crate) fn codex_import_preserves_claude_tool_context_within_a_turn() {
    let user = r#"{"type":"user","message":{"content":[{"type":"tool_result","content":"tests passed"}]}}"#;
    let item = codex_item_for_record(user, CliProvider::Claude, 0).unwrap();

    assert_eq!(item["role"], "user");
    assert!(item["content"][0]["text"]
        .as_str()
        .unwrap()
        .contains("tests passed"));
}

#[test]
pub(crate) fn codex_import_reads_existing_codex_conversation_messages() {
    let assistant = r#"{"type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"already restored"}]}}"#;
    let item = codex_item_for_record(assistant, CliProvider::Codex, 0).unwrap();

    assert_eq!(item["role"], "assistant");
    assert_eq!(item["content"][0]["text"], "already restored");
}

#[test]
pub(crate) fn codex_import_keeps_every_short_claude_conversation_turn_in_order() {
    let source = [
        r#"{"type":"user","message":{"content":"one"}}"#,
        r#"{"type":"assistant","message":{"content":"two"}}"#,
        r#"{"type":"user","message":{"content":"three"}}"#,
        r#"{"type":"assistant","message":{"content":"four"}}"#,
    ];

    let restored = source
        .iter()
        .enumerate()
        .filter_map(|(index, record)| codex_item_for_record(record, CliProvider::Claude, index))
        .map(|item| {
            (
                item["role"].as_str().unwrap().to_owned(),
                item["content"][0]["text"].as_str().unwrap().to_owned(),
            )
        })
        .collect::<Vec<_>>();

    assert_eq!(
        restored,
        vec![
            ("user".into(), "one".into()),
            ("assistant".into(), "two".into()),
            ("user".into(), "three".into()),
            ("assistant".into(), "four".into()),
        ]
    );
}

#[test]
pub(crate) fn full_history_restore_persists_a_resumable_session_before_launching_it() {
    let root = std::env::temp_dir().join(format!("operon-history-record-{}", Uuid::new_v4()));
    let project_path = root.join("missing-project");
    let project = Project {
        id: Uuid::new_v4(),
        path: project_path.clone(),
        name: "history-record".into(),
        added_at: now(),
    };
    let source = CliSession {
        provider: CliProvider::Claude,
        native_id: "11111111-1111-1111-1111-111111111111".into(),
        id: "11111111-1111-1111-1111-111111111111".into(),
        title: Some("short conversation".into()),
        last_user_message: Some("one".into()),
        branch: None,
        updated_at: now(),
        path: root.join("source.jsonl"),
    };
    let managed_session_id = Uuid::new_v4();
    let native_session_id = "22222222-2222-2222-2222-222222222222".to_owned();
    let imported = ImportedNativeSession {
        managed_session_id,
        provider: CliProvider::Codex,
        native_session_id: Some(native_session_id.clone()),
        native_session_path: root.join("codex.jsonl"),
        archive_path: root.join("archive.jsonl"),
        imported_records: 2,
        classification: RestoreClassification::default(),
        // The nonexistent project path makes the asynchronous launcher
        // fail before it can invoke the real CLI. The durable record must
        // still preserve the normal native-resume command.
        agent_command: format!("codex resume {native_session_id}"),
    };
    let data_file = root.join("store.json");
    let mut app = test_app(data_file.clone());
    app.store.projects.push(project.clone());

    app.finish_full_history_import(&project, &source, "codex", "", imported);

    let persisted = load_store(&data_file).unwrap();
    let session = persisted
        .sessions
        .iter()
        .find(|session| session.id == managed_session_id)
        .expect("the restored terminal record must be durable before launch");
    assert_eq!(
        session.native_session_id.as_deref(),
        Some(native_session_id.as_str())
    );
    assert_eq!(
        session.agent_command,
        format!("codex resume {native_session_id}")
    );
    assert_eq!(persisted.cli_handoffs.len(), 1);
    assert_eq!(
        persisted.cli_handoffs[0].destination_session_id.as_deref(),
        Some(native_session_id.as_str())
    );

    wait_for_background_task(
        &mut app,
        &BackgroundKey::SessionStart(managed_session_id),
        Duration::from_secs(15),
    );
    let persisted = load_store(&data_file).unwrap();
    assert_eq!(
        persisted
            .sessions
            .iter()
            .find(|session| session.id == managed_session_id)
            .map(|session| &session.status),
        Some(&SessionStatus::Failed)
    );
    fs::remove_dir_all(root).unwrap();
}

#[test]
#[ignore = "requires an authenticated local Codex CLI and tmux"]
pub(crate) fn codex_app_server_restores_a_short_transcript_into_a_resumable_terminal() {
    if !tool_available("codex") || !tool_available("tmux") {
        return;
    }
    let root = std::env::temp_dir().join(format!("operon-codex-e2e-{}", Uuid::new_v4()));
    let project_path = root.join("project");
    let archive_root = root.join("archive");
    let source_path = root.join("source.jsonl");
    fs::create_dir_all(&project_path).unwrap();
    fs::write(
        &source_path,
        concat!(
            r#"{"type":"user","message":{"content":"operon-history-one"}}"#,
            "\n",
            r#"{"type":"assistant","message":{"content":"operon-history-two"}}"#,
            "\n",
            r#"{"type":"user","message":{"content":"operon-history-three"}}"#,
            "\n",
            r#"{"type":"assistant","message":{"content":"operon-history-four"}}"#,
            "\n",
        ),
    )
    .unwrap();
    let source = CliSession {
        provider: CliProvider::Claude,
        native_id: Uuid::new_v4().to_string(),
        id: Uuid::new_v4().to_string(),
        title: None,
        last_user_message: Some("operon-history-three".into()),
        branch: None,
        updated_at: now(),
        path: source_path,
    };
    let project = Project {
        id: Uuid::new_v4(),
        path: project_path.clone(),
        name: "codex-e2e".into(),
        added_at: now(),
    };

    let imported =
        import_full_cli_history(&project, &source, "codex", &archive_root, Uuid::new_v4()).unwrap();
    let restored = fs::read_to_string(&imported.native_session_path)
        .unwrap()
        .lines()
        .filter_map(|line| serde_json::from_str::<serde_json::Value>(line).ok())
        .filter_map(|value| transcript_value_turn(&value, CliProvider::Codex))
        .map(|(role, text)| (role.to_owned(), text))
        .collect::<Vec<_>>();
    let expected = vec![
        ("user".to_owned(), "operon-history-one".to_owned()),
        ("assistant".to_owned(), "operon-history-two".to_owned()),
        ("user".to_owned(), "operon-history-three".to_owned()),
        ("assistant".to_owned(), "operon-history-four".to_owned()),
    ];
    assert!(
        restored
            .windows(expected.len())
            .any(|window| window == expected),
        "the destination session must contain every source turn in order; restored={restored:?}"
    );

    assert!(
        restored_conversation_is_visible_in_a_native_terminal(
            &project_path,
            &imported.agent_command,
            "operon-history-four",
        ),
        "normal codex resume did not render the restored conversation"
    );
    fs::remove_dir_all(root).unwrap();
}

/// Antigravity's own transcript is the newest restore source, and Codex is
/// the destination that verifies its persisted thread, so this pairing
/// proves a saved `agy` conversation really reopens inside another CLI.
#[test]
#[ignore = "requires an authenticated local Codex CLI and tmux"]
pub(crate) fn a_saved_antigravity_conversation_restores_into_a_resumable_codex_terminal() {
    if !tool_available("codex") || !tool_available("tmux") {
        return;
    }
    let root = std::env::temp_dir().join(format!("operon-agy-source-e2e-{}", Uuid::new_v4()));
    let project_path = root.join("project");
    let archive_root = root.join("archive");
    let conversation_id = Uuid::new_v4().to_string();
    let transcript = antigravity_conversation_transcript_in(&root, &conversation_id);
    fs::create_dir_all(&project_path).unwrap();
    fs::create_dir_all(transcript.parent().unwrap()).unwrap();
    fs::write(
        &transcript,
        concat!(
            r#"{"step_index":0,"source":"USER_EXPLICIT","type":"USER_INPUT","content":"<USER_REQUEST>\noperon-agy-source-one\n</USER_REQUEST>\n<ADDITIONAL_METADATA>\nignored\n</ADDITIONAL_METADATA>"}"#,
            "\n",
            r#"{"step_index":1,"source":"MODEL","type":"PLANNER_RESPONSE","content":"operon-agy-source-two"}"#,
            "\n",
            r#"{"step_index":2,"source":"MODEL","type":"RUN_COMMAND","content":"operational trace"}"#,
            "\n",
            r#"{"step_index":3,"source":"USER_EXPLICIT","type":"USER_INPUT","content":"<USER_REQUEST>\noperon-agy-source-three\n</USER_REQUEST>"}"#,
            "\n",
            r#"{"step_index":4,"source":"MODEL","type":"PLANNER_RESPONSE","content":"operon-agy-source-four"}"#,
            "\n",
        ),
    )
    .unwrap();
    let source = CliSession {
        provider: CliProvider::Gemini,
        native_id: conversation_id.clone(),
        id: conversation_id,
        title: None,
        last_user_message: Some("operon-agy-source-three".into()),
        branch: None,
        updated_at: now(),
        path: transcript,
    };
    let project = Project {
        id: Uuid::new_v4(),
        path: project_path.clone(),
        name: "agy-source-e2e".into(),
        added_at: now(),
    };

    let imported =
        import_full_cli_history(&project, &source, "codex", &archive_root, Uuid::new_v4()).unwrap();

    assert_eq!(imported.imported_records, 4);
    assert!(
        restored_conversation_is_visible_in_a_native_terminal(
            &project_path,
            &imported.agent_command,
            "operon-agy-source-four",
        ),
        "normal codex resume did not render the restored Antigravity conversation"
    );
    fs::remove_dir_all(root).unwrap();
}

/// A real Codex rollout opens with the session's own setup messages. This
/// pairing checks the whole path a person actually takes when they move a
/// Codex conversation to Antigravity, including what must not come along.
#[test]
#[ignore = "requires a local Antigravity CLI and tmux; writes one conversation into the local agy store"]
pub(crate) fn a_saved_codex_conversation_restores_into_a_resumable_antigravity_terminal() {
    if !tool_available(ANTIGRAVITY_COMMAND) || !tool_available("tmux") {
        return;
    }
    let root = std::env::temp_dir().join(format!("operon-codex-source-e2e-{}", Uuid::new_v4()));
    let project_path = root.join("project");
    let archive_root = root.join("archive");
    let rollout = root.join("rollout.jsonl");
    fs::create_dir_all(&project_path).unwrap();
    fs::write(
        &rollout,
        concat!(
            r#"{"type":"session_meta","payload":{"id":"01a0145d-133c-7b71-b598-cb620a8c9dc8"}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"developer","content":[{"type":"input_text","text":"system prompt"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"<environment_context>\n  <cwd>/private/tmp</cwd>\n</environment_context>"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"operon-codex-source-one"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"function_call","name":"shell","arguments":"{}"}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"operon-codex-source-two"}]}}"#,
            "\n",
            r#"{"type":"event_msg","payload":{"type":"user_message","message":"operon-codex-source-one"}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"operon-codex-source-three"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"operon-codex-source-four"}]}}"#,
            "\n",
        ),
    )
    .unwrap();
    let source = CliSession {
        provider: CliProvider::Codex,
        native_id: "01a0145d-133c-7b71-b598-cb620a8c9dc8".into(),
        id: "01a0145d-133c-7b71-b598-cb620a8c9dc8".into(),
        title: None,
        last_user_message: Some("operon-codex-source-three".into()),
        branch: None,
        updated_at: now(),
        path: rollout,
    };
    let project = Project {
        id: Uuid::new_v4(),
        path: project_path.clone(),
        name: "codex-source-e2e".into(),
        added_at: now(),
    };

    let imported =
        import_full_cli_history(&project, &source, "gemini", &archive_root, Uuid::new_v4())
            .unwrap();

    assert_eq!(imported.imported_records, 5);
    let connection = rusqlite::Connection::open(&imported.native_session_path).unwrap();
    let steps = connection
        .prepare("SELECT step_payload FROM steps ORDER BY idx")
        .unwrap()
        .query_map([], |row| row.get::<_, Vec<u8>>(0))
        .unwrap()
        .map(|payload| antigravity_step_turn(&payload.unwrap()).unwrap())
        .collect::<Vec<_>>();
    drop(connection);
    assert_eq!(
        steps,
        vec![
            ("user", "operon-codex-source-one".to_owned()),
            // A `function_call` is a response item of its own, and
            // `codex_conversation_message` carries it deliberately: a restored
            // delegated task that lost its tool calls lost its reasoning. This
            // expectation said four turns for as long as that has been true,
            // and `#[ignore]` is why nobody saw it.
            ("assistant", "[Tool call: shell]\n{}".to_owned()),
            ("assistant", "operon-codex-source-two".to_owned()),
            ("user", "operon-codex-source-three".to_owned()),
            ("assistant", "operon-codex-source-four".to_owned()),
        ],
        "the source session's own setup must not become part of the restored conversation"
    );
    assert!(
        restored_conversation_is_visible_in_a_native_terminal(
            &project_path,
            &imported.agent_command,
            "operon-codex-source-four",
        ),
        "normal agy resume did not render the restored Codex conversation"
    );
    fs::remove_dir_all(root).unwrap();
}

/// Operon writes Claude Code's conversation file itself, so the only
/// real proof is Claude Code reopening that conversation and rendering the
/// source turns — with no model turn anywhere in the restore.
#[test]
#[ignore = "requires a local Claude Code CLI and tmux"]
pub(crate) fn a_saved_codex_conversation_restores_into_a_resumable_claude_terminal() {
    if !tool_available("claude") || !tool_available("tmux") {
        return;
    }
    let root = std::env::temp_dir().join(format!("operon-claude-dest-e2e-{}", Uuid::new_v4()));
    let project_path = root.join("project");
    let archive_root = root.join("archive");
    let rollout = root.join("rollout.jsonl");
    fs::create_dir_all(&project_path).unwrap();
    fs::write(
        &rollout,
        concat!(
            r#"{"type":"session_meta","payload":{"id":"01a0145d-133c-7b71-b598-cb620a8c9dc8","cwd":"/tmp"}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"<environment_context>\n  <cwd>/tmp</cwd>\n</environment_context>"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"operon-codex-to-claude-one"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"operon-codex-to-claude-two"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"operon-codex-to-claude-three"}]}}"#,
            "\n",
            r#"{"type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"operon-codex-to-claude-four"}]}}"#,
            "\n",
        ),
    )
    .unwrap();
    let source = CliSession {
        provider: CliProvider::Codex,
        native_id: "01a0145d-133c-7b71-b598-cb620a8c9dc8".into(),
        id: "01a0145d-133c-7b71-b598-cb620a8c9dc8".into(),
        title: None,
        last_user_message: Some("operon-codex-to-claude-three".into()),
        branch: None,
        updated_at: now(),
        path: rollout,
    };
    let project = Project {
        id: Uuid::new_v4(),
        path: project_path.clone(),
        name: "claude-dest-e2e".into(),
        added_at: now(),
    };

    let imported =
        import_full_cli_history(&project, &source, "claude", &archive_root, Uuid::new_v4())
            .unwrap();

    assert_eq!(imported.imported_records, 4);
    let restored = fs::read_to_string(&imported.native_session_path)
        .unwrap()
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .filter_map(|record| transcript_value_turn(&record, CliProvider::Claude))
        .collect::<Vec<_>>();
    assert_eq!(
        restored,
        vec![
            ("user", "operon-codex-to-claude-one".to_owned()),
            ("assistant", "operon-codex-to-claude-two".to_owned()),
            ("user", "operon-codex-to-claude-three".to_owned()),
            ("assistant", "operon-codex-to-claude-four".to_owned()),
        ],
        "the source session's own setup must not become part of the restored conversation"
    );
    let visible = restored_conversation_is_visible_in_a_native_terminal(
        &project_path,
        &imported.agent_command,
        "operon-codex-to-claude-four",
    );
    // The conversation lives in Claude Code's own store, not under `root`.
    remove_restored_claude_conversation(&imported.native_session_path);
    assert!(
        visible,
        "normal claude resume did not render the restored Codex conversation"
    );
    fs::remove_dir_all(root).unwrap();
}

/// The remaining ordered pair: Antigravity out, Claude Code in. Together
