/// The user-visible failure this guards against: a restored Codex thread
/// whose model can quote the history while `codex resume` opens on an empty
/// transcript, which reads as "the restore did nothing".
#[test]
pub(crate) fn codex_restore_appends_history_the_terminal_can_replay() {
    let root = std::env::temp_dir().join(format!("operon-codex-replay-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let source = root.join("source.jsonl");
    let rollout = root.join("rollout.jsonl");
    fs::write(
        &source,
        concat!(
            r#"{"type":"attachment","attachment":{"type":"hook_success"}}"#,
            "\n",
            r#"{"type":"user","message":{"content":"one"}}"#,
            "\n",
            r#"{"type":"assistant","message":{"content":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    fs::write(
        &rollout,
        "{\"type\":\"session_meta\",\"payload\":{\"id\":\"thread\"}}\n",
    )
    .unwrap();

    assert_eq!(
        add_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)),
        Ok(2)
    );
    assert!(
        verify_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)).is_ok(),
        "the appended records must match the source turns"
    );
    let replayed = fs::read_to_string(&rollout)
        .unwrap()
        .lines()
        .filter_map(|line| serde_json::from_str::<serde_json::Value>(line).ok())
        .filter(|value| {
            value["type"] == "event_msg" && value["payload"]["type"] == "item_completed"
        })
        .map(|value| {
            let item = &value["payload"]["item"];
            (
                item["type"].as_str().unwrap().to_owned(),
                item["content"][0]["text"].as_str().unwrap().to_owned(),
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        replayed,
        vec![
            ("UserMessage".to_owned(), "one".to_owned()),
            ("AgentMessage".to_owned(), "two".to_owned()),
        ]
    );
    assert!(fs::read_to_string(&rollout)
        .unwrap()
        .contains("session_meta"));

    fs::write(
        &rollout,
        "{\"type\":\"session_meta\",\"payload\":{\"id\":\"thread\"}}\n",
    )
    .unwrap();
    assert!(
        verify_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude))
            .unwrap_err()
            .contains("再生できる復元ターンは 0 件"),
        "a thread without replay records must not pass verification"
    );
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn codex_restore_refuses_to_append_after_a_partial_record() {
    let root = std::env::temp_dir().join(format!("operon-codex-partial-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let source = root.join("source.jsonl");
    let rollout = root.join("rollout.jsonl");
    fs::write(
        &source,
        "{\"type\":\"user\",\"message\":{\"content\":\"one\"}}\n",
    )
    .unwrap();
    fs::write(&rollout, "{\"type\":\"session_meta\"").unwrap();

    assert!(
        add_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude))
            .unwrap_err()
            .contains("不完全なレコード")
    );
    assert_eq!(
        fs::read_to_string(&rollout).unwrap(),
        "{\"type\":\"session_meta\""
    );
    fs::remove_dir_all(root).unwrap();
}

/// Every record of one rollout file, in order, for the three tests below.
/// Written once because what they each assert is a different property of the
/// same list, and a per-test reader is a per-test chance to read a different
/// file than the one the assertion talks about.
fn codex_rollout_records(rollout: &Path) -> Vec<serde_json::Value> {
    fs::read_to_string(rollout)
        .unwrap()
        .lines()
        .filter_map(|line| serde_json::from_str::<serde_json::Value>(line).ok())
        .collect()
}

/// The user-visible failure this guards against: a restored Codex session whose
/// terminal dies the moment the person opens it, on a restore Operon reported
/// as complete.
///
/// Codex 0.155.0 numbers every record it writes into a rollout and reads the
/// final one to continue that sequence. Measured against the installed Codex
/// through the same `thread/resume` its TUI calls: with the appended replay
/// records unnumbered it refuses the thread — `final paginated rollout record
/// … is missing an ordinal (code -32603)` — and with the numbers filled in the
/// same file resumes.
#[test]
pub(crate) fn codex_restore_numbers_replay_records_the_way_the_rollout_numbers_its_own() {
    let root = std::env::temp_dir().join(format!("operon-codex-ordinal-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let source = root.join("source.jsonl");
    let rollout = root.join("rollout.jsonl");
    fs::write(
        &source,
        concat!(
            r#"{"type":"user","message":{"content":"one"}}"#,
            "\n",
            r#"{"type":"assistant","message":{"content":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    // The envelope Codex writes: `ordinal` on every record, from zero, beside
    // the `type` and `payload` the reader already knew about.
    fs::write(
        &rollout,
        concat!(
            r#"{"ordinal":0,"timestamp":"2026-09-18T07:56:14.565Z","type":"session_meta","payload":{"id":"thread"}}"#,
            "\n",
            r#"{"ordinal":1,"timestamp":"2026-09-18T07:56:14.600Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"one"}]}}"#,
            "\n",
            r#"{"ordinal":2,"timestamp":"2026-09-18T07:56:14.700Z","type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"two"}]}}"#,
            "\n",
        ),
    )
    .unwrap();

    assert_eq!(
        add_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)),
        Ok(2)
    );
    let records = codex_rollout_records(&rollout);
    let ordinals = records
        .iter()
        .map(|record| record.get("ordinal").and_then(|value| value.as_u64()))
        .collect::<Vec<_>>();
    // Three records per turn — `task_started`, `item_completed`,
    // `task_complete` — which is the shape Codex projects into a turn.
    assert_eq!(
        ordinals,
        (0..9).map(Some).collect::<Vec<_>>(),
        "the appended replay records must continue the rollout's own numbering"
    );
    assert!(
        verify_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)).is_ok(),
        "a correctly numbered rollout must pass verification"
    );

    // The next number comes from the highest in the file and not from the last
    // record, so that an appended record outranks every number already there.
    // A resumed session's rollout does not start at zero — the ones on this
    // machine start wherever their parent thread left off — and a file whose
    // sequence is not monotonic must not produce a final record that another
    // record outranks.
    //
    // This arrangement is synthetic, and its expectation is inferred rather
    // than measured: all 390 numbered rollouts on the machine this was written
    // on are strictly monotonic and end at their maximum, so no Codex has been
    // asked what it makes of `[0, 9, 1, …]`. It stays because it is the only
    // arrangement that reddens the last-versus-highest mutation — not because
    // Codex is known to accept the gap at 2-8.
    fs::write(
        &rollout,
        concat!(
            r#"{"ordinal":0,"type":"session_meta","payload":{"id":"thread"}}"#,
            "\n",
            r#"{"ordinal":9,"type":"response_item","payload":{"type":"message","role":"user"}}"#,
            "\n",
            r#"{"ordinal":1,"type":"response_item","payload":{"type":"message","role":"assistant"}}"#,
            "\n",
        ),
    )
    .unwrap();
    assert_eq!(
        add_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)),
        Ok(2)
    );
    let ordinals = codex_rollout_records(&rollout)
        .iter()
        .map(|record| record.get("ordinal").and_then(|value| value.as_u64()))
        .collect::<Vec<_>>();
    assert_eq!(
        ordinals,
        [Some(0), Some(9), Some(1)]
            .into_iter()
            .chain((10..16).map(Some))
            .collect::<Vec<_>>(),
        "the appended records must outrank the highest number in the file"
    );
    fs::remove_dir_all(root).unwrap();
}

/// What a restore does to a rollout written before Codex numbered anything.
///
/// Change 059 left such a file unnumbered, measured: a 2026-09-05 session with no
/// ordinal anywhere resumed. That was for the `user_message`/`agent_message`
/// records it appended then. What a restore appends now is a turn —
/// `task_started`, `item_completed`, `task_complete` — and a turn is only shown
/// once Codex projects it, into `thread_turns` and `thread_items`, whose
/// `rollout_ordinal` is `NOT NULL`. Unnumbered, the thread resumes and opens
/// empty, which is the second cause 059's plan named and left to a successor.
/// So the appended records are numbered from zero; Codex's own records in the
/// file are not rewritten.
#[test]
pub(crate) fn codex_restore_numbers_its_turns_in_an_unnumbered_rollout_and_leaves_codex_records_alone(
) {
    let root = std::env::temp_dir().join(format!("operon-codex-legacy-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let source = root.join("source.jsonl");
    let rollout = root.join("rollout.jsonl");
    fs::write(
        &source,
        "{\"type\":\"user\",\"message\":{\"content\":\"one\"}}\n",
    )
    .unwrap();
    let codex_record = "{\"type\":\"session_meta\",\"payload\":{\"id\":\"thread\"}}";
    fs::write(&rollout, format!("{codex_record}\n")).unwrap();

    assert_eq!(
        add_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)),
        Ok(1)
    );
    let written = fs::read_to_string(&rollout).unwrap();
    assert_eq!(
        written.lines().next(),
        Some(codex_record),
        "Codex's own record must reach the file byte for byte"
    );
    let ordinals = codex_rollout_records(&rollout)
        .iter()
        .map(|record| record.get("ordinal").and_then(|value| value.as_u64()))
        .collect::<Vec<_>>();
    assert_eq!(
        ordinals,
        vec![None, Some(0), Some(1), Some(2)],
        "the turn Operon appends must be numbered, and nothing Codex wrote renumbered"
    );
    assert!(
        verify_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)).is_ok(),
        "an unnumbered rollout with numbered turns appended must pass verification"
    );
    fs::remove_dir_all(root).unwrap();
}

/// Verification is what stands between a broken write and a session id the
/// person is invited to open, so it has to refuse the exact file the writer
/// produced before this change: Codex's numbered records followed by unnumbered
/// replay records. Without this the only report is a dead pane, eight days
/// later, with nothing on screen naming the restore.
#[test]
pub(crate) fn a_rollout_whose_last_record_lost_its_number_fails_verification() {
    let root = std::env::temp_dir().join(format!("operon-codex-mixture-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let rollout = root.join("rollout.jsonl");
    fs::write(
        &rollout,
        concat!(
            r#"{"ordinal":0,"type":"session_meta","payload":{"id":"thread"}}"#,
            "\n",
            r#"{"type":"event_msg","payload":{"type":"user_message","message":"one"}}"#,
            "\n",
            r#"{"type":"event_msg","payload":{"type":"agent_message","message":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    let expected = vec![("user", "one".to_owned()), ("assistant", "two".to_owned())];

    let complaint = verify_codex_replayable_history(&rollout, &expected).unwrap_err();
    assert!(
        complaint.contains("ordinal のないレコード"),
        "the refusal must name what Codex could not read: {complaint}"
    );

    // The other way the appended records can fail to continue the sequence:
    // numbered, but not past what the file already holds. Unreachable through
    // the writer, which takes the highest — and asserted anyway, because a
    // branch nothing has watched fail is a guess about what it catches.
    fs::write(
        &rollout,
        concat!(
            r#"{"ordinal":0,"type":"session_meta","payload":{"id":"thread"}}"#,
            "\n",
            r#"{"ordinal":9,"type":"response_item","payload":{"type":"message","role":"user"}}"#,
            "\n",
            r#"{"ordinal":1,"type":"event_msg","payload":{"type":"user_message","message":"one"}}"#,
            "\n",
            r#"{"ordinal":2,"type":"event_msg","payload":{"type":"agent_message","message":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    let complaint = verify_codex_replayable_history(&rollout, &expected).unwrap_err();
    assert!(
        complaint.contains("連続していません"),
        "the refusal must name where the numbering broke: {complaint}"
    );

    // And a trailing line neither side can read. `add_codex_replayable_history`
    // refuses to append after a partial record, so the writer cannot produce
    // this — but the read has to treat an unreadable last line as a final
    // record with no number, rather than letting the record before it stand as
    // the file's last. Review found the other way round: the number carried
    // over and the file passed.
    fs::write(
        &rollout,
        concat!(
            r#"{"ordinal":0,"type":"session_meta","payload":{"id":"thread"}}"#,
            "\n",
            r#"{"ordinal":1,"type":"event_msg","payload":{"type":"user_message","message":"one"}}"#,
            "\n",
            r#"{"ordinal":2,"type":"event_msg","payload":{"type":"agent_message","message":"two"}}"#,
            "\n",
            "{\"type\":\"event_msg\"\n",
        ),
    )
    .unwrap();
    let complaint = verify_codex_replayable_history(&rollout, &expected).unwrap_err();
    assert!(
        complaint.contains("ordinal のないレコード"),
        "an unreadable last line must be refused, not skipped: {complaint}"
    );
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn codex_replay_records_use_codex_rollout_timestamps() {
    assert_eq!(utc_timestamp_millis(0), "1970-01-01T00:00:00.000Z");
    assert_eq!(
        utc_timestamp_millis(1_787_031_718),
        "2026-08-18T05:41:58.000Z"
    );
    let event = codex_replay_event("assistant", "done", None).unwrap();
    let parsed = serde_json::from_str::<serde_json::Value>(&event).unwrap();
    assert_eq!(parsed["payload"]["type"], "item_completed");
    assert_eq!(parsed["payload"]["item"]["type"], "AgentMessage");
    assert_eq!(parsed["payload"]["item"]["phase"], "final_answer");
    assert!(parsed["timestamp"].as_str().unwrap().ends_with('Z'));
    assert!(parsed.get("ordinal").is_none());

    let with_ord = codex_replay_event("user", "hello", Some(42)).unwrap();
    let parsed_ord = serde_json::from_str::<serde_json::Value>(&with_ord).unwrap();
    assert_eq!(parsed_ord["ordinal"], 43);
    assert_eq!(parsed_ord["payload"]["type"], "item_completed");
    assert_eq!(parsed_ord["payload"]["item"]["type"], "UserMessage");
}

#[test]
pub(crate) fn codex_replay_records_preserve_and_continue_paginated_ordinals() {
    let root = std::env::temp_dir().join(format!("operon-codex-ordinals-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let source = root.join("source.jsonl");
    let rollout = root.join("rollout.jsonl");
    fs::write(
        &source,
        concat!(
            r#"{"type":"user","message":{"content":"one"}}"#,
            "\n",
            r#"{"type":"assistant","message":{"content":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    fs::write(
        &rollout,
        concat!(
            r#"{"type":"session_meta","history_mode":"paginated","ordinal":0}"#,
            "\n",
            r#"{"type":"turn_context","ordinal":1}"#,
            "\n",
            r#"{"type":"response_item","ordinal":2}"#,
            "\n",
        ),
    )
    .unwrap();

    assert_eq!(
        add_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)),
        Ok(2)
    );
    assert!(
        verify_codex_replayable_history(&rollout, &turns_in(&source, CliProvider::Claude)).is_ok(),
        "the appended records must pass verification with continuing ordinals"
    );
    let lines = fs::read_to_string(&rollout)
        .unwrap()
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect::<Vec<_>>();
    assert_eq!(lines.len(), 9);
    assert_eq!(lines[3]["ordinal"], 3);
    assert_eq!(lines[3]["type"], "event_msg");
    assert_eq!(lines[3]["payload"]["type"], "task_started");
    assert_eq!(lines[4]["ordinal"], 4);
    assert_eq!(lines[4]["type"], "event_msg");
    assert_eq!(lines[4]["payload"]["type"], "item_completed");
    assert_eq!(lines[4]["payload"]["item"]["type"], "UserMessage");
    assert_eq!(lines[5]["ordinal"], 5);
    assert_eq!(lines[5]["type"], "event_msg");
    assert_eq!(lines[5]["payload"]["type"], "task_complete");
    assert_eq!(lines[6]["ordinal"], 6);
    assert_eq!(lines[6]["type"], "event_msg");
    assert_eq!(lines[6]["payload"]["type"], "task_started");
    assert_eq!(lines[7]["ordinal"], 7);
    assert_eq!(lines[7]["type"], "event_msg");
    assert_eq!(lines[7]["payload"]["type"], "item_completed");
    assert_eq!(lines[7]["payload"]["item"]["type"], "AgentMessage");
    assert_eq!(lines[8]["ordinal"], 8);
    assert_eq!(lines[8]["type"], "event_msg");
    assert_eq!(lines[8]["payload"]["type"], "task_complete");

    // Missing ordinal when earlier records had ordinals fails verification
    let bad_rollout = root.join("bad-rollout.jsonl");
    fs::write(
        &bad_rollout,
        concat!(
            r#"{"type":"session_meta","ordinal":0}"#,
            "\n",
            r#"{"type":"event_msg","payload":{"type":"user_message","message":"one"}}"#,
            "\n",
            r#"{"type":"event_msg","payload":{"type":"agent_message","message":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    assert!(
        verify_codex_replayable_history(&bad_rollout, &turns_in(&source, CliProvider::Claude))
            .unwrap_err()
            .contains("ordinal のないレコード"),
        "a record missing an ordinal in an ordinal-indexed rollout must fail verification"
    );

    // Discontinuous ordinals fail verification
    let gap_rollout = root.join("gap-rollout.jsonl");
    fs::write(
        &gap_rollout,
        concat!(
            r#"{"type":"session_meta","ordinal":0}"#,
            "\n",
            r#"{"type":"event_msg","ordinal":5,"payload":{"type":"user_message","message":"one"}}"#,
            "\n",
            r#"{"type":"event_msg","ordinal":6,"payload":{"type":"agent_message","message":"two"}}"#,
            "\n",
        ),
    )
    .unwrap();
    assert!(
        verify_codex_replayable_history(&gap_rollout, &turns_in(&source, CliProvider::Claude))
            .unwrap_err()
            .contains("ordinal が連続していません"),
        "gapped ordinals must fail verification"
    );

    fs::remove_dir_all(root).unwrap();
}

