#[test]
pub(crate) fn antigravity_restore_writes_a_conversation_the_cli_reopens() {
    let root = std::env::temp_dir().join(format!("operon-agy-write-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let conversation_id = "11111111-1111-1111-1111-111111111111";
    let path = root.join(format!("{conversation_id}.db"));
    let turns = vec![
        ("user", "最初の依頼".to_owned()),
        ("assistant", "その返答".to_owned()),
        ("user", "続きの依頼".to_owned()),
    ];

    write_antigravity_conversation(&path, conversation_id, &turns, 1_700_000_000).unwrap();
    verify_antigravity_conversation(&path, &turns).unwrap();

    let connection = rusqlite::Connection::open(&path).unwrap();
    let rows = connection
        .prepare("SELECT idx, step_type, status, metadata, step_payload FROM steps ORDER BY idx")
        .unwrap()
        .query_map([], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, i64>(1)?,
                row.get::<_, i64>(2)?,
                row.get::<_, Vec<u8>>(3)?,
                row.get::<_, Vec<u8>>(4)?,
            ))
        })
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap();
    assert_eq!(rows.len(), turns.len());
    for (index, (idx, step_type, status, metadata, payload)) in rows.iter().enumerate() {
        assert_eq!(*idx, index as i64);
        assert_eq!(*status, ANTIGRAVITY_STEP_STATUS_DONE as i64);
        let expected_type = if turns[index].0 == "user" {
            ANTIGRAVITY_STEP_TYPE_USER_INPUT
        } else {
            ANTIGRAVITY_STEP_TYPE_PLANNER_RESPONSE
        };
        assert_eq!(*step_type as u64, expected_type);
        // The destination CLI reads the step's origin from its metadata,
        // so a restored user turn must not decode as a model response.
        let metadata_fields = proto_fields(metadata).unwrap();
        let expected_source = if turns[index].0 == "user" {
            ANTIGRAVITY_STEP_SOURCE_USER
        } else {
            ANTIGRAVITY_STEP_SOURCE_MODEL
        };
        assert_eq!(
            proto_varint_value(&metadata_fields, 3).unwrap(),
            expected_source
        );
        let step_id = proto_fields(proto_bytes_value(&metadata_fields, 20).unwrap()).unwrap();
        assert_eq!(
            proto_bytes_value(&step_id, 4).unwrap(),
            conversation_id.as_bytes()
        );
        assert_eq!(
            antigravity_step_turn(payload).unwrap(),
            (turns[index].0, turns[index].1.clone())
        );
    }
    let (trajectory_type, source): (i64, i64) = connection
        .query_row(
            "SELECT trajectory_type, source FROM trajectory_meta",
            [],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(trajectory_type as u64, ANTIGRAVITY_TRAJECTORY_TYPE_CLI);
    assert_eq!(source as u64, ANTIGRAVITY_TRAJECTORY_SOURCE_CLI);
    drop(connection);

    // The store is Antigravity's, so an existing conversation is never
    // replaced by a restore.
    assert!(
        write_antigravity_conversation(&path, conversation_id, &turns, 1_700_000_000)
            .unwrap_err()
            .contains("に会話があります")
    );
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn antigravity_restore_refuses_a_conversation_it_cannot_read_back() {
    let root = std::env::temp_dir().join(format!("operon-agy-verify-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let path = root.join("conversation.db");
    let turns = vec![
        ("user", "最初の依頼".to_owned()),
        ("assistant", "その返答".to_owned()),
    ];
    write_antigravity_conversation(&path, "22222222-2222-2222-2222-222222222222", &turns, 1)
        .unwrap();

    let connection = rusqlite::Connection::open(&path).unwrap();
    connection
        .execute(
            "UPDATE steps SET step_payload = ?1 WHERE idx = 1",
            [b"\x00"],
        )
        .unwrap();
    drop(connection);
    assert!(verify_antigravity_conversation(&path, &turns)
        .unwrap_err()
        .contains("読み戻せませんでした"));

    let shortened = vec![turns[0].clone()];
    assert!(verify_antigravity_conversation(&path, &shortened)
        .unwrap_err()
        .contains("多くのターンを含んでいます"));
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn claude_restore_writes_a_conversation_the_cli_reopens() {
    let root = std::env::temp_dir().join(format!("operon-claude-write-{}", Uuid::new_v4()));
    let workspace = root.join("project");
    fs::create_dir_all(&workspace).unwrap();
    let session_id = "33333333-3333-3333-3333-333333333333";
    let path = root.join(format!("{session_id}.jsonl"));
    let turns = vec![
        ("user", "最初の依頼".to_owned()),
        ("assistant", "その返答".to_owned()),
        ("user", "続きの依頼".to_owned()),
    ];

    write_claude_conversation(&path, session_id, &workspace, &turns, 1_700_000_000).unwrap();
    verify_claude_conversation(&path, session_id, &turns).unwrap();

    let records = fs::read_to_string(&path)
        .unwrap()
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect::<Vec<_>>();
    assert_eq!(records.len(), turns.len());
    let mut parent = serde_json::Value::Null;
    for (index, record) in records.iter().enumerate() {
        assert_eq!(record["sessionId"], session_id);
        assert_eq!(record["cwd"], workspace.display().to_string());
        assert_eq!(record["isSidechain"], false);
        // Claude Code walks the conversation by this chain, so a broken
        // link would reopen as a shorter conversation than was restored.
        assert_eq!(record["parentUuid"], parent, "record {index}");
        parent = record["uuid"].clone();
        assert_eq!(record["type"], turns[index].0);
        // The CLI's own reader must see exactly the source turn back.
        assert_eq!(
            transcript_value_turn_claude(record),
            Some((turns[index].0, turns[index].1.clone()))
        );
    }
    // Every record is dated at or before the moment of the restore.
    for record in &records {
        assert!(
            parse_rfc3339_utc_seconds(record["timestamp"].as_str().unwrap()).unwrap()
                <= 1_700_000_000
        );
    }

    // The store is Claude Code's, so an existing conversation is never
    // replaced by a restore.
    assert!(
        write_claude_conversation(&path, session_id, &workspace, &turns, 1_700_000_000)
            .unwrap_err()
            .contains("に会話があります")
    );
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn claude_restore_refuses_a_conversation_it_cannot_read_back() {
    let root = std::env::temp_dir().join(format!("operon-claude-verify-{}", Uuid::new_v4()));
    let workspace = root.join("project");
    fs::create_dir_all(&workspace).unwrap();
    let session_id = "44444444-4444-4444-4444-444444444444";
    let path = root.join("conversation.jsonl");
    let turns = vec![
        ("user", "最初の依頼".to_owned()),
        ("assistant", "その返答".to_owned()),
    ];
    write_claude_conversation(&path, session_id, &workspace, &turns, 1).unwrap();
    verify_claude_conversation(&path, session_id, &turns).unwrap();

    let committed = fs::read_to_string(&path).unwrap();
    let mut records = committed
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect::<Vec<_>>();
    let rewrite = |records: &[serde_json::Value]| {
        let mut out = String::new();
        for record in records {
            out.push_str(&serde_json::to_string(record).unwrap());
            out.push('\n');
        }
        fs::write(&path, out).unwrap();
    };

    records[1]["message"]["content"][0]["text"] = serde_json::json!("別の返答");
    rewrite(&records);
    assert!(verify_claude_conversation(&path, session_id, &turns)
        .unwrap_err()
        .contains("内容が元と異なります"));

    records = committed
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect();
    records[1]["parentUuid"] = serde_json::json!("00000000-0000-0000-0000-000000000000");
    rewrite(&records);
    assert!(verify_claude_conversation(&path, session_id, &turns)
        .unwrap_err()
        .contains("順序どおりではありません"));

    records = committed
        .lines()
        .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
        .collect();
    records[1]["sessionId"] = serde_json::json!("55555555-5555-5555-5555-555555555555");
    rewrite(&records);
    assert!(verify_claude_conversation(&path, session_id, &turns)
        .unwrap_err()
        .contains("別の会話に書き込まれました"));

    fs::write(&path, committed).unwrap();
    let shortened = vec![turns[0].clone()];
    assert!(verify_claude_conversation(&path, session_id, &shortened)
        .unwrap_err()
        .contains("多くのターンを含んでいます"));
    let lengthened = vec![
        turns[0].clone(),
        turns[1].clone(),
        ("user", "届かなかった依頼".to_owned()),
    ];
    assert!(verify_claude_conversation(&path, session_id, &lengthened)
        .unwrap_err()
        .contains("3 件中 2 件のターンを復元しました"));
    fs::remove_dir_all(root).unwrap();
}

/// A restored turn that happens to quote another CLI's plumbing tags is
/// still what someone said, so it has to survive the round trip verbatim
/// rather than be re-stripped into a failed restore.
#[test]
pub(crate) fn claude_restore_keeps_a_turn_that_quotes_another_cli_s_plumbing() {
    let root = std::env::temp_dir().join(format!("operon-claude-quote-{}", Uuid::new_v4()));
    let workspace = root.join("project");
    fs::create_dir_all(&workspace).unwrap();
    let session_id = "66666666-6666-6666-6666-666666666666";
    let path = root.join("conversation.jsonl");
    let quoted = "<system-reminder>これは引用です</system-reminder>".to_owned();
    let turns = vec![("user", quoted.clone())];

    write_claude_conversation(&path, session_id, &workspace, &turns, 1).unwrap();
    verify_claude_conversation(&path, session_id, &turns).unwrap();

    let record = serde_json::from_str::<serde_json::Value>(
        fs::read_to_string(&path).unwrap().lines().next().unwrap(),
    )
    .unwrap();
    assert_eq!(record["message"]["content"], serde_json::json!(quoted));
    fs::remove_dir_all(root).unwrap();
}

/// Claude Code files a conversation under the working directory its own
/// process resolved, so a project reached through a symlink has to be
/// written where the destination CLI will look for it.
#[test]
pub(crate) fn claude_conversations_are_filed_under_the_resolved_project_path() {
    let root = std::env::temp_dir().join(format!("operon-claude-link-{}", Uuid::new_v4()));
    let real = root.join("real");
    let link = root.join("link");
    fs::create_dir_all(&real).unwrap();
    std::os::unix::fs::symlink(&real, &link).unwrap();

    assert_eq!(
        claude_conversation_workspace(&link),
        fs::canonicalize(&real).unwrap()
    );
    assert_eq!(
        encode_claude_project_path(&link),
        encode_claude_project_path(&real)
    );
    // An unresolvable path is still usable, which is what a scan of a
    // recorded project that has since moved relies on.
    let missing = root.join("gone");
    assert_eq!(claude_conversation_workspace(&missing), missing);
    fs::remove_dir_all(root).unwrap();
}

/// Both expectations were read out of Claude Code 2.1.234 itself by
/// starting it in these directories and looking at the directory it filed
/// the conversation under. A path outside the Basic Multilingual Plane is
/// the case that separates counting UTF-16 code units, which Claude Code
/// does, from counting characters.
#[test]
pub(crate) fn project_directories_are_named_the_way_claude_code_names_them() {
    assert_eq!(
        encode_claude_project_path(Path::new("/private/tmp/operon adv 日本語_probe.v2")),
        "-private-tmp-operon-adv-----probe-v2"
    );
    assert_eq!(
        encode_claude_project_path(Path::new("/private/tmp/operon🏓adv-emoji")),
        "-private-tmp-operon--adv-emoji"
    );
    assert_eq!(
        encode_claude_project_path(Path::new("/Users/a/dev/operon")),
        "-Users-a-dev-operon"
    );
}

