/// What a session row's copy button puts on somebody's clipboard. Each CLI
/// resumes with its own verb and its own flag, so this is the difference
/// between a paste that runs and a paste that has to be edited first.
#[test]
pub(crate) fn the_copy_button_hands_over_a_command_each_cli_can_run() {
    let session_id = "4c022664-9f6f-4ea1-9642-2f7cbc96376a";
    assert_eq!(
        native_resume_display(CliProvider::Codex, session_id),
        "codex resume 4c022664-9f6f-4ea1-9642-2f7cbc96376a"
    );
    assert_eq!(
        native_resume_display(CliProvider::Claude, session_id),
        "claude --resume 4c022664-9f6f-4ea1-9642-2f7cbc96376a"
    );
    assert_eq!(
        native_resume_display(CliProvider::Gemini, session_id),
        format!("{ANTIGRAVITY_COMMAND} --conversation {session_id}")
    );
    // Every one of them carries the ID whole. A command holding an
    // abbreviated ID is a command that resumes nothing.
    for provider in [CliProvider::Codex, CliProvider::Claude, CliProvider::Gemini] {
        let command = native_resume_display(provider, session_id);
        assert!(
            command.ends_with(session_id),
            "{provider:?} dropped part of the conversation ID: {command}"
        );
    }
}

