/// Availability must not depend on how fast a tool starts. Running
/// `--version` under a deadline made an installed but slow-booting CLI
/// look uninstalled, which blocked resume and restore.
#[test]
pub(crate) fn resolves_tools_on_path_without_running_them() {
    assert!(tool_available("/usr/bin/true"));
    assert!(tool_available("sh"));
    assert!(!tool_available("/definitely/missing/operon-tool"));
    assert!(!tool_available("operon-definitely-not-a-tool"));
    // A directory and a non-executable file both resolve to a name that
    // cannot be launched.
    assert!(!tool_available("/usr/bin"));
    assert!(!tool_available("/etc/hosts"));
}

/// Starting a session needs tmux *and* the agent, so a notice that lists
/// both regardless of which is missing cannot be acted on.
#[test]
pub(crate) fn missing_tool_notices_name_only_what_is_absent() {
    let without_agent = ToolStatus {
        tmux: true,
        ..ToolStatus::default()
    };
    assert_eq!(
        without_agent.missing_session_tools(CliProvider::Gemini),
        vec![ANTIGRAVITY_COMMAND]
    );
    let without_tmux = ToolStatus {
        antigravity: true,
        ..ToolStatus::default()
    };
    assert_eq!(
        without_tmux.missing_session_tools(CliProvider::Gemini),
        vec!["tmux"]
    );
    assert_eq!(
        ToolStatus::default().missing_session_tools(CliProvider::Codex),
        vec!["tmux", "codex"]
    );
    let ready = ToolStatus {
        tmux: true,
        codex: true,
        ..ToolStatus::default()
    };
    assert!(ready.missing_session_tools(CliProvider::Codex).is_empty());
}
#[test]
pub(crate) fn background_system_action_failures_become_actionable_notices() {
    let mut app = test_app(PathBuf::from("/tmp/operon-system-action.json"));
    app.request_system_action("open a test item", || Err(anyhow!("simulated failure")));
    for _ in 0..20 {
        thread::sleep(Duration::from_millis(10));
        app.process_background_results();
        if !app
            .background_tasks
            .iter()
            .any(|key| matches!(key, BackgroundKey::SystemAction(_)))
        {
            break;
        }
    }
    assert!(app
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("simulated failure")));
}
#[test]
pub(crate) fn terminates_external_commands_that_exceed_their_deadline() {
    let mut command = Command::new("/bin/sleep");
    command.arg("5");
    let started = Instant::now();
    let error = run_command_with_timeout(&mut command, Duration::from_millis(75)).unwrap_err();
    assert!(error.to_string().contains("タイムアウトしました"));
    // Change 039: the budget, not the placeholder.
    assert!(
        error.to_string().contains("75ms") && !error.to_string().contains('{'),
        "タイムアウトの文言に待った時間がありません: {error}"
    );
    assert!(started.elapsed() < Duration::from_secs(2));
}
#[test]
pub(crate) fn caps_child_output_during_capture_instead_of_after_buffering() {
    let mut command = Command::new("/usr/bin/yes");
    command.arg("operon-output-limit");
    let started = Instant::now();
    let limited =
        run_command_with_output_limit(&mut command, Duration::from_secs(5), 4 * 1024, 4 * 1024)
            .unwrap();
    assert!(limited.stdout_truncated);
    assert_eq!(limited.output.stdout.len(), 4 * 1024);
    assert!(started.elapsed() < Duration::from_secs(2));
}
