#[test]
pub(crate) fn preserves_an_unreadable_store_before_starting_empty() {
    let root = std::env::temp_dir().join(format!("operon-corrupt-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let path = root.join("store.json");
    fs::write(&path, "{ definitely not valid json").unwrap();

    let loaded = load_store_safely(&path);

    assert!(loaded.store.projects.is_empty());
    assert_eq!(loaded.data_file, path);
    assert!(loaded
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("保全しました")));
    assert!(!path.exists());
    let backups = fs::read_dir(&root)
        .unwrap()
        .filter_map(Result::ok)
        .filter(|entry| {
            entry
                .file_name()
                .to_string_lossy()
                .starts_with("store.corrupt-")
        })
        .collect::<Vec<_>>();
    assert_eq!(backups.len(), 1);
    assert_eq!(
        fs::read_to_string(backups[0].path()).unwrap(),
        "{ definitely not valid json"
    );
    fs::remove_dir_all(root).unwrap();
}

