#[test]
pub(crate) fn worktree_mutation_fences_manual_empty_and_queued_session_starts() {
    let root = std::env::temp_dir().join(format!("operon-launch-fence-{}", Uuid::new_v4()));
    let project_path = root.join("project");
    fs::create_dir_all(&project_path).unwrap();
    let project_id = Uuid::new_v4();
    let mut app = OperonApp::from_state(
        root.join("store.json"),
        Store {
            projects: vec![Project {
                id: project_id,
                path: project_path.clone(),
                name: "project".into(),
                added_at: now(),
            }],
            ..Store::default()
        },
        ToolStatus {
            tmux: true,
            ..ToolStatus::default()
        },
        None,
    );
    app.select_project(Some(project_id));
    app.goal_input = "Do not start during Git mutation".into();
    app.background_tasks
        .insert(BackgroundKey::WorktreeMutation(project_id));

    app.launch_session();
    app.launch_empty_session();
    assert!(app.store.sessions.is_empty());

    let parent_id = Uuid::new_v4();
    let mut parent = test_session(parent_id, SessionStatus::Exited);
    parent.project_id = project_id;
    let mut queued = test_session(Uuid::new_v4(), SessionStatus::Queued);
    queued.project_id = project_id;
    queued.agent = "custom".into();
    queued.depends_on = vec![parent_id];
    queued.worktree_path = Some(project_path);
    let queued_id = queued.id;
    app.store.sessions = vec![parent, queued];

    app.start_ready_queued_sessions();
    assert_eq!(
        app.store
            .sessions
            .iter()
            .find(|session| session.id == queued_id)
            .unwrap()
            .status,
        SessionStatus::Queued
    );
    assert!(!app
        .background_tasks
        .contains(&BackgroundKey::SessionStart(queued_id)));
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn accepts_a_non_git_project_root_as_a_session_directory() {
    let root = std::env::temp_dir().join(format!("operon-non-git-{}", Uuid::new_v4()));
    let unrelated = std::env::temp_dir().join(format!("operon-unrelated-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::create_dir_all(&unrelated).unwrap();
    assert!(is_allowed_session_path(&root, &root));
    assert!(!is_allowed_session_path(&root, &unrelated));
    fs::remove_dir_all(root).unwrap();
    fs::remove_dir_all(unrelated).unwrap();
}
#[test]
pub(crate) fn resolves_the_selected_worktree_for_agent_and_empty_sessions() {
    let root = std::env::temp_dir().join(format!("operon-path-{}", Uuid::new_v4()));
    let project = root.join("project");
    let selected = root.join("linked-worktree");
    fs::create_dir_all(&project).unwrap();
    fs::create_dir_all(&selected).unwrap();
    assert_eq!(
        resolve_session_path(&project, "").unwrap(),
        project.canonicalize().unwrap()
    );
    assert_eq!(
        resolve_session_path(&project, selected.to_str().unwrap()).unwrap(),
        selected.canonicalize().unwrap()
    );
    assert!(resolve_session_path(&project, root.join("missing").to_str().unwrap()).is_err());
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn rejects_a_working_directory_selected_for_another_project() {
    let root = std::env::temp_dir().join(format!("operon-path-scope-{}", Uuid::new_v4()));
    let project = root.join("project");
    let selected = root.join("linked-worktree");
    fs::create_dir_all(&project).unwrap();
    fs::create_dir_all(&selected).unwrap();
    assert!(resolve_selected_session_path(
        Uuid::new_v4(),
        &project,
        Some(Uuid::new_v4()),
        selected.to_str().unwrap()
    )
    .is_err());
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn switching_projects_clears_project_scoped_launch_state() {
    let first = Uuid::new_v4();
    let second = Uuid::new_v4();
    let mut app = test_app(PathBuf::from("/tmp/operon-project-switch.json"));
    app.selected_project = Some(first);
    app.session_path_input = "/tmp/first-worktree".into();
    app.session_path_project = Some(first);
    app.depends_on_input = Some(Uuid::new_v4());
    app.worktree_branch_input = "feature/first".into();
    app.goal_input = "Only for project A".into();
    app.session_name_input = "Project A task".into();
    app.selected_agent = "claude".into();
    app.custom_command = "private-agent".into();
    app.agent_model_input = "model-a".into();
    app.agent_mode_input = "danger-full-access".into();
    app.agent_effort_input = "high".into();
    app.agent_flag_inputs = vec!["search".into()];
    app.acknowledged_launch = Some(app.pending_launch());
    app.selected_session = Some(Uuid::new_v4());
    app.open_documents.push(OpenDocument {
        project: first,
        root: PathBuf::from("/tmp/first"),
        path: PathBuf::from("src/first.rs"),
        branch: None,
        project_rooted: true,
        disk: String::new(),
        buffer: String::new(),
        read_only: None,
        save_error: None,
        external_change: false,
        image_data: None,
    });
    app.active_document = Some(DocumentId {
        project: first,
        root: PathBuf::from("/tmp/first"),
        path: PathBuf::from("src/first.rs"),
    });
    app.git_selected_file = Some("src/first.rs".into());

    app.select_project(Some(second));

    assert_eq!(app.selected_project, Some(second));
    assert!(app.session_path_input.is_empty());
    assert_eq!(app.session_path_project, None);
    assert_eq!(app.depends_on_input, None);
    assert!(app.worktree_branch_input.is_empty());
    assert!(app.goal_input.is_empty());
    assert!(app.session_name_input.is_empty());
    assert_eq!(app.selected_agent, "claude");
    assert_eq!(app.custom_command, "private-agent");
    assert_eq!(app.agent_model_input, "model-a");
    assert_eq!(app.agent_mode_input, "danger-full-access");
    assert_eq!(app.agent_effort_input, "high");
    assert_eq!(app.agent_flag_inputs, vec!["search".to_string()]);
    assert_eq!(app.acknowledged_launch, None);
    assert_eq!(app.selected_session, None);
    // The other project's tab survives the switch; the editor just stops
    // pointing at it.
    assert_eq!(app.active_document, None);
    assert_eq!(app.open_documents.len(), 1);
    assert_eq!(app.git_selected_file, None);
}
#[test]
pub(crate) fn accepts_only_finder_folders_from_a_drop() {
    let root = std::env::temp_dir().join(format!("operon-drop-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let file = root.join("ticket.txt");
    fs::write(&file, "not a project folder").unwrap();
    let dropped = vec![
        egui::DroppedFile {
            path: Some(root.clone()),
            ..Default::default()
        },
        egui::DroppedFile {
            path: Some(file),
            ..Default::default()
        },
    ];
    let (folders, rejected) = dropped_project_folders(&dropped);
    assert_eq!(folders, vec![root.clone()]);
    assert_eq!(rejected, 1);
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn native_folder_picker_result_adds_a_project_and_cancel_is_non_mutating() {
    let root = std::env::temp_dir().join(format!("operon-picker-{}", Uuid::new_v4()));
    let project = root.join("project");
    fs::create_dir_all(&project).unwrap();
    let mut app = test_app(root.join("data/store.json"));

    app.apply_project_folder_choice(None);
    assert!(app.store.projects.is_empty());
    assert!(app
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("キャンセルしました")));

    app.apply_project_folder_choice(Some(project.canonicalize().unwrap()));
    assert_eq!(app.store.projects.len(), 1);
    assert_eq!(app.selected_project, Some(app.store.projects[0].id));
    assert_eq!(load_store(&app.data_file).unwrap().projects.len(), 1);
    fs::remove_dir_all(root).unwrap();
}
