#[test]
pub(crate) fn renders_ansi_terminal_colors_without_escape_codes() {
    let palette = AppTheme::Dark.palette();
    let lines = terminal_line_layouts("\x1b[31merror\x1b[0m plain\n\x1b[38;2;1;2;3mrgb", palette);

    assert_eq!(lines.len(), 2);
    assert_eq!(lines[0].text, "error plain");
    assert_eq!(lines[1].text, "rgb");
    assert_eq!(lines[0].sections.len(), 2);
    // SGR 31 is red, so it has to land on the table's red rather than on
    // whichever entry happens to sit at that offset.
    assert_eq!(lines[0].sections[0].format.color, palette.danger);
    assert_eq!(
        lines[0].sections[0].format.color,
        terminal_ansi_color(1, false, palette)
    );
    assert_eq!(
        lines[1].sections[0].format.color,
        Color32::from_rgb(1, 2, 3)
    );
}
#[test]
pub(crate) fn carries_terminal_color_across_the_lines_it_spans() {
    let palette = AppTheme::Dark.palette();
    // Splitting the buffer into rows is a rendering decision. A colour the
    // CLI never closed still has to reach the rows underneath it.
    let lines = terminal_line_layouts("\x1b[31mfailed:\n  first\n\x1b[0mdone", palette);

    assert_eq!(lines.len(), 3);
    assert_eq!(lines[1].sections[0].format.color, palette.danger);
    assert_eq!(lines[2].sections[0].format.color, palette.terminal_fg);
    assert_eq!(terminal_plain_text(&lines), "failed:\n  first\ndone");
}
#[test]
pub(crate) fn keeps_a_row_for_every_captured_line() {
    let palette = AppTheme::Dark.palette();
    // The viewport reserves one row per line, so a blank line has to be a
    // line: dropping it would draw every row below it one row too high.
    let lines = terminal_line_layouts("first\n\nthird\n", palette);

    assert_eq!(lines.len(), 4);
    assert!(lines[1].is_empty());
    assert!(lines[3].is_empty());
}
#[test]
pub(crate) fn preserves_japanese_terminal_text() {
    let lines = terminal_line_layouts(
        "\x1b[36m待機中です。何をしましょうか？\x1b[0m",
        AppTheme::Dark.palette(),
    );

    assert_eq!(lines[0].text, "待機中です。何をしましょうか？");
    assert_eq!(lines[0].sections[0].format.font_id, FontId::monospace(15.0));
}
#[test]
pub(crate) fn maps_tui_control_keys_without_intercepting_macos_commands() {
    assert_eq!(
        terminal_key_binding(egui::Key::ArrowUp, egui::Modifiers::NONE),
        Some("Up".into())
    );
    assert_eq!(
        terminal_key_binding(
            egui::Key::C,
            egui::Modifiers {
                ctrl: true,
                ..Default::default()
            }
        ),
        Some("C-c".into())
    );
    assert_eq!(
        terminal_key_binding(
            egui::Key::Tab,
            egui::Modifiers {
                shift: true,
                ..Default::default()
            }
        ),
        Some("BTab".into())
    );
    assert_eq!(
        terminal_key_binding(
            egui::Key::C,
            egui::Modifiers {
                command: true,
                ..Default::default()
            }
        ),
        None
    );
}
#[test]
pub(crate) fn terminal_grid_uses_the_available_right_pane_size() {
    // The cell is measured from the face in use, so this is the grid a
    // 15 pt Sarasa pane asks tmux for.
    let cell = egui::vec2(7.6, 19.0);
    assert_eq!(
        terminal_grid_size(egui::vec2(1_480.0, 1_040.0), cell),
        (192, 53)
    );
    assert_eq!(terminal_grid_size(egui::vec2(10.0, 10.0), cell), (40, 12));
    // A wider face has to mean fewer columns, or tmux would wrap lines at
    // a width the pane cannot draw and the ends would be clipped.
    assert_eq!(
        terminal_grid_size(egui::vec2(1_480.0, 1_040.0), egui::vec2(9.0, 22.0)),
        (162, 46)
    );
}
