#[test]
pub(crate) fn preserves_every_native_resume_command_without_a_second_prompt() {
    for (command, _) in [
        (
            "codex resume 12345678-abcd-0123-abcd-1234567890ab",
            CliProvider::Codex,
        ),
        (
            "claude --resume 12345678-abcd-0123-abcd-1234567890ab",
            CliProvider::Claude,
        ),
        (
            "agy --conversation 12345678-abcd-0123-abcd-123456789abc",
            CliProvider::Gemini,
        ),
    ] {
        let launched = agent_shell_command(command, "do not repeat");
        assert!(
            !launched.contains("do not repeat"),
            "a resume must never replay the original request: {launched}"
        );
        // Whatever a launch adds, it must still be the same resume of the
        // same conversation.
        assert!(
            launched.ends_with(command.split_whitespace().last().unwrap()),
            "{launched}"
        );
        assert_eq!(launched, suppress_codex_startup_update_prompt(command));
    }
    let id = "12345678-abcd-0123-abcd-1234567890ab";
    assert_eq!(
        CliProvider::Codex.native_resume_command(id),
        format!("codex resume {id}")
    );
    assert_eq!(
        CliProvider::Claude.native_resume_command(id),
        format!("claude --resume {id}")
    );
    assert_eq!(
        CliProvider::Gemini.native_resume_command(id),
        format!("agy --conversation {id}")
    );
}
