/// The switches are the feature: a person combines a mode with one or more
/// of them, and the command has to come out in the CLI's own spelling
/// whatever order they were clicked in.
#[test]
pub(crate) fn combines_launch_switches_with_the_mode_beside_them() {
    assert_eq!(
        build_agent_launch_command(
            "codex",
            "",
            "",
            "workspace-write",
            "",
            &flag_ids(&["search", "approval-never"])
        ),
        Ok("codex --sandbox workspace-write --ask-for-approval never --search".into())
    );
    // Catalogue order, not click order — the same set is the same command.
    assert_eq!(
        build_agent_launch_command(
            "codex",
            "",
            "",
            "workspace-write",
            "",
            &flag_ids(&["approval-never", "search"])
        ),
        build_agent_launch_command(
            "codex",
            "",
            "",
            "workspace-write",
            "",
            &flag_ids(&["search", "approval-never"])
        )
    );
    assert_eq!(
        build_agent_launch_command(
            "claude",
            "",
            "",
            "acceptEdits",
            "",
            &flag_ids(&["ide", "verbose"])
        ),
        Ok("claude --permission-mode acceptEdits --ide --verbose".into())
    );
    assert_eq!(
        build_agent_launch_command(
            "gemini",
            "",
            "",
            "accept-edits",
            "",
            &flag_ids(&["sandbox"])
        ),
        Ok("agy --mode accept-edits --sandbox".into())
    );
    // A repeated ID is a person clicking twice, not a doubled flag.
    assert_eq!(
        build_agent_launch_command("claude", "", "", "", "", &flag_ids(&["ide", "ide"])),
        Ok("claude --ide".into())
    );
}
/// Every exclusivity here is one the CLI itself enforces, verified against
/// the installed binaries. Letting a rejected pair through would open a
/// tmux window that prints a usage error and dies with a session record
/// already written for it.
#[test]
pub(crate) fn refuses_switch_combinations_the_cli_rejects() {
    assert!(build_agent_launch_command(
        "codex",
        "",
        "",
        "",
        "",
        &flag_ids(&["approval-never", "approve-for-me"])
    )
    .is_err());
    assert!(build_agent_launch_command(
        "codex",
        "",
        "",
        "",
        "",
        &flag_ids(&["approval-never", "bypass-approvals"])
    )
    .is_err());
    assert!(build_agent_launch_command(
        "codex",
        "",
        "",
        "workspace-write",
        "",
        &flag_ids(&["approve-for-me"])
    )
    .is_err());
    // The bypass switch is fine beside a sandbox: Codex accepts that pair.
    assert!(build_agent_launch_command(
        "codex",
        "",
        "",
        "read-only",
        "",
        &flag_ids(&["bypass-approvals"])
    )
    .is_ok());
    assert!(build_agent_launch_command(
        "claude",
        "",
        "",
        "",
        "",
        &flag_ids(&["skip-permissions", "allow-skip-permissions"])
    )
    .is_err());
    // A switch belonging to another CLI, and any switch at all on a custom
    // command, are both refused rather than pasted in.
    assert!(build_agent_launch_command("claude", "", "", "", "", &flag_ids(&["search"])).is_err());
    assert!(
        build_agent_launch_command("custom", "my-agent", "", "", "", &flag_ids(&["search"]))
            .is_err()
    );
}
#[test]
pub(crate) fn every_displayed_provider_option_passes_its_typed_contract() {
    for agent in ["codex", "claude", "gemini"] {
        for mode in agent_mode_options(agent) {
            assert!(
                build_agent_launch_command(agent, "", "", mode, "", &[]).is_ok(),
                "{agent} mode {mode}"
            );
        }
        for effort in agent_effort_options(agent) {
            assert!(
                build_agent_launch_command(agent, "", "", "", effort, &[]).is_ok(),
                "{agent} effort {effort}"
            );
        }
        for flag in agent_flag_options(agent) {
            assert!(
                build_agent_launch_command(agent, "", "", "", "", &flag_ids(&[flag.id])).is_ok(),
                "{agent} flag {}",
                flag.id
            );
            assert!(
                !flag.args.is_empty(),
                "{agent} flag {} adds nothing",
                flag.id
            );
        }
    }
}
#[test]
pub(crate) fn every_launchable_agent_ships_a_decodable_mark() {
    for agent in ["codex", "claude", "gemini"] {
        let (name, bytes) =
            agent_icon_asset(agent).unwrap_or_else(|| panic!("{agent} has no mark"));
        let mark =
            decode_png_mark(bytes).unwrap_or_else(|| panic!("{name} is not a decodable PNG"));
        // The shared square is what lets marks of different shapes sit
        // in the same box beside a label.
        assert_eq!(mark.size, [128, 128], "{name}");
    }
    // A plain terminal, a custom command, and an older record naming some
    // other binary have no vendor mark to draw.
    for agent in ["terminal", "existing terminal", "custom", "my-agent"] {
        assert!(agent_icon_asset(agent).is_none(), "{agent}");
    }
}

#[test]
/// The brand mark is the bundle icon's ring with the icon's dark plate keyed
/// out. The plate is the part that was deliberately dropped: kept, it puts the
/// only black tile on screen onto the light theme, and re-exporting the artwork
/// from the master without redoing the keying is exactly how it would come
/// back — silently, and only visible on the one theme least likely to be
/// looked at.
///
/// So this checks the properties that make it the right asset rather than its
/// bytes: a hash would fail on any legitimate redraw, and these would not.
pub(crate) fn the_brand_mark_is_a_transparent_ring_not_a_plate() {
    let mark = decode_png_mark(BRAND_MARK).expect("the brand mark should be a decodable PNG");
    // The same square the three vendor marks ship at, so every mark the app
    // draws as a picture is resampled from the same size.
    assert_eq!(mark.size, [128, 128]);

    let at = |x: usize, y: usize| mark.pixels[y * 128 + x];
    // The plate would have filled all four corners and the ring's hole.
    for (x, y) in [(0, 0), (127, 0), (0, 127), (127, 127), (64, 64)] {
        assert_eq!(
            at(x, y).a(),
            0,
            "({x}, {y}) is not transparent — the plate is still in the mark"
        );
    }
    // And the ring itself has to have survived the keying: fully opaque
    // somewhere, and orange rather than the single ink a glyph would be.
    let ring = mark
        .pixels
        .iter()
        .find(|pixel| pixel.a() == 255)
        .expect("the ring should be fully opaque somewhere");
    assert!(
        ring.r() > ring.g() && ring.g() > ring.b(),
        "the ring is {ring:?}, which is not the brand orange"
    );
}

#[test]
/// Every mark is `include_bytes!`d into the binary and decoded on the frame
/// that first draws it. `assets/operon-icon-1024.png` is the same artwork at
/// 1.1 MB, one `include_bytes!` path away, and pointing a constant at it would
/// cost a megabyte of binary and a 1024x1024 decode inside a draw path — which
/// is work the per-frame rules forbid and which no other test would notice.
pub(crate) fn every_bundled_mark_is_small_enough_to_ship() {
    const CEILING: usize = 40 * 1024;
    for (name, bytes) in [
        ("BRAND_MARK", BRAND_MARK),
        ("AGENT_ICON_CLAUDE", AGENT_ICON_CLAUDE),
        ("AGENT_ICON_CODEX", AGENT_ICON_CODEX),
        ("AGENT_ICON_ANTIGRAVITY", AGENT_ICON_ANTIGRAVITY),
    ] {
        assert!(
            bytes.len() <= CEILING,
            "{name} is {} bytes, over the {CEILING}-byte ceiling — is it pointing at the master?",
            bytes.len()
        );
    }
}

#[test]
/// Operon's own mark is artwork, and the glyph vocabulary is for actions. The
/// mark used to be a Phosphor dashed circle drawn as 14pt text in the same ink
/// as the word beside it, which is why it read as a character rather than as a
/// product. Putting a `BRAND` back into the vocabulary is that mistake
/// returning, and so is either drawing site going back to text.
pub(crate) fn the_brand_is_drawn_as_artwork_and_not_from_the_glyph_vocabulary() {
    for (name, _) in ICON_VOCABULARY {
        assert!(
            !name.contains("BRAND"),
            "{name} makes Operon's own mark a glyph again"
        );
    }
    // Named by the two surfaces that must draw it, not by the file they
    // currently live in. This guard used to read `src/app.rs` and count call
    // sites in it; change 021 moved the drawing out and it failed for a reason
    // that had nothing to do with the brand. Counting across the whole tree
    // instead would have been *weaker* than what it replaced — a third site
    // anywhere would let one of these two go back to text and still reach the
    // total. So the bodies are found wherever they are, and each is asked
    // separately. Lesson 014.
    for function in ["ui_topbar", "ui_projects"] {
        let body = rust_function_body(function)
            .unwrap_or_else(|| panic!("{function} が src/ のどこにもありません"));
        assert!(
            body.contains("brand_mark_image("),
            "{function} は Operon のマークを画像ではなく文字で描いています"
        );
    }
}

#[test]
pub(crate) fn only_the_light_theme_builds_egui_from_a_light_base() {
    // `Palette::dark` is what egui derives every widget default it is not
    // handed from. A table whose flag disagrees with its own surfaces
    // draws untouched widgets for the other theme entirely.
    assert!(!AppTheme::Light.visuals().dark_mode);
    for theme in [AppTheme::Dark, AppTheme::HighContrast] {
        assert!(theme.visuals().dark_mode, "{}", theme.label());
    }
}

/// A theme is only implemented if you can read it. Every colour that
/// carries meaning is checked against the surfaces it is actually drawn
/// on, at the WCAG 2.1 AA ratio for the size it is drawn at — 4.5:1 for
/// text at any size the app draws, 3:1 for the outlines that mark hover,
/// press, and keyboard focus.
///
/// A page spends the window it was given. The failure this pins is a page
/// that stops growing part way — a fixed column on a wide display answers a
/// window somebody dragged open by widening its own two margins.
#[test]
pub(crate) fn a_page_grows_with_the_window_it_is_drawn_in() {
    let widths = [480.0_f32, 900.0, 1_440.0, 2_008.0, 3_840.0];
    for pair in widths.windows(2) {
        let (narrow, wide) = (pair[0], pair[1]);
        assert!(
            page_column_width(wide) > page_column_width(narrow),
            "a {wide}px window must draw a wider page than a {narrow}px one"
        );
        // The margin is a gutter, not a place to park the rest of the
        // screen: whatever the window gains, the page gains nearly all of.
        let gained = page_column_width(wide) - page_column_width(narrow);
        assert!(
            gained >= (wide - narrow) - PAGE_GUTTER * 2.0,
            "a {narrow}px → {wide}px window gave the page only {gained}px"
        );
    }
    for width in widths {
        let page = page_column_width(width);
        assert!(page > 0.0 && page <= width, "{width}px window");
        let gutter = (width - page) / 2.0;
        assert!(gutter <= PAGE_GUTTER, "{width}px window: {gutter}px gutter");
        // A narrow window is not mostly margin.
        assert!(gutter <= width * 0.04 + 0.01, "{width}px window");
    }
    assert_eq!(page_column_width(0.0), 0.0);
}

/// This is the test that makes the light theme real work rather than a
/// call to `Visuals::light()`: every status hue that the dark themes
/// brighten has to be re-mixed dark enough to survive on paper, and
/// nothing but a measurement will tell you whether it was.
#[test]
pub(crate) fn every_theme_stays_readable() {
    let mut failures = Vec::new();
    let mut require = |ratio: f32, minimum: f32, what: String| {
        if ratio < minimum {
            failures.push(format!("{what}: {ratio:.2}:1, needs {minimum:.1}:1"));
        }
    };
    for theme in AppTheme::all() {
        let name = theme.label();
        let palette = theme.palette();
        // Text sits on the panel, on a card, and on the white of a text
        // edit, so each ink is checked against all three.
        let surfaces = [
            ("panel", palette.panel),
            ("raised", palette.raised),
            ("card", palette.card),
            ("inset", palette.inset),
            ("window", palette.window),
            ("row-selected", palette.row_selected),
        ];
        let inks = [
            ("text_strong", palette.text_strong, 4.5),
            ("text", palette.text, 4.5),
            ("text_muted", palette.text_muted, 4.5),
            ("text_faint", palette.text_faint, 4.5),
            ("branch", palette.branch, 4.5),
            ("link", palette.link, 4.5),
            ("accent_text", palette.accent_text, 4.5),
            ("accent_soft", palette.accent_soft, 4.5),
            ("info", palette.info, 4.5),
            ("success", palette.success, 4.5),
            ("calm", palette.calm, 4.5),
            ("warning", palette.warning, 4.5),
            ("danger", palette.danger, 4.5),
            ("sand", palette.sand, 4.5),
            ("agent_codex", palette.agent_codex, 4.5),
            ("agent_claude", palette.agent_claude, 4.5),
            ("agent_antigravity", palette.agent_antigravity, 4.5),
            ("agent_unknown", palette.agent_unknown, 4.5),
        ];
        for (ink_name, ink, minimum) in inks {
            for (surface_name, surface) in surfaces {
                require(
                    contrast_ratio(ink, surface),
                    minimum,
                    format!("{name}: {ink_name} on {surface_name}"),
                );
            }
        }
        // Uncoloured terminal output is the single largest block of text
        // in the app, and it answers to its own ink rather than to ANSI 7.
        require(
            contrast_ratio(palette.terminal_fg, palette.terminal_bg),
            4.5,
            format!("{name}: terminal_fg on terminal_bg"),
        );
        // Filled buttons: the brand fill and every vendor fill have to
        // carry a label, and `readable_text_on` picks which ink.
        for (fill_name, fill) in [
            ("accent", palette.accent),
            ("agent_codex", palette.agent_codex),
            ("agent_claude", palette.agent_claude),
            ("agent_antigravity", palette.agent_antigravity),
            ("agent_unknown", palette.agent_unknown),
            ("control", palette.control),
        ] {
            require(
                contrast_ratio(readable_text_on(fill, palette), fill),
                4.5,
                format!("{name}: button label on {fill_name}"),
            );
        }
        // A diff row is a wash with code on top of it, so the code has to
        // survive the wash: the line itself in `text`, its line numbers in
        // `text_muted`, and its sign in the diff ink. The washes are also
        // checked against `inset`, the surface the editor and the diff are
        // drawn on — a wash nobody can see is a diff with no marks at all.
        // 1.1:1 is deliberately low: these are wide bands of colour with a
        // hue of their own, not text, and GitHub's own light-theme washes
        // measure about 1.05:1 against white.
        for (side_name, wash, ink, mark) in [
            (
                "added",
                palette.diff_added_bg,
                palette.diff_added,
                palette.diff_added_emphasis,
            ),
            (
                "removed",
                palette.diff_removed_bg,
                palette.diff_removed,
                palette.diff_removed_emphasis,
            ),
        ] {
            for (ink_name, over) in [
                ("text", palette.text),
                ("text_muted", palette.text_muted),
                ("sign", ink),
            ] {
                require(
                    contrast_ratio(over, wash),
                    4.5,
                    format!("{name}: {ink_name} on the {side_name} wash"),
                );
            }
            // The sign is also drawn in a summary line beside ordinary
            // prose, so it has to work on the surfaces text works on.
            for (surface_name, surface) in surfaces {
                require(
                    contrast_ratio(ink, surface),
                    4.5,
                    format!("{name}: diff {side_name} sign on {surface_name}"),
                );
            }
            require(
                contrast_ratio(wash, palette.inset),
                1.1,
                format!("{name}: the {side_name} wash against the editor surface"),
            );
            // The word mark is a band a few characters wide *inside* the row
            // wash, so it is read against the wash and never against the page.
            // It has to be findable there — 1.5:1 is above GitHub's own
            // word-level marks, which measure 1.23:1 to 1.49:1 — while the
            // code drawn on top of it stays readable. Only `text` is checked
            // over it: the line numbers and the sign sit left of the line and
            // are never covered by a mark.
            require(
                contrast_ratio(mark, wash),
                1.5,
                format!("{name}: the {side_name} word mark against its own wash"),
            );
            require(
                contrast_ratio(palette.text, mark),
                4.5,
                format!("{name}: text on the {side_name} word mark"),
            );
        }
        // Every ANSI slot has to be legible on the terminal's own
        // background, including the black and white ends that a naive
        // table leaves invisible on one theme or the other.
        for (index, colour) in palette.ansi.iter().enumerate() {
            require(
                contrast_ratio(*colour, palette.terminal_bg),
                4.5,
                format!("{name}: ansi[{index}] on terminal_bg"),
            );
        }
        for (index, colour) in palette.ansi_bright.iter().enumerate() {
            require(
                contrast_ratio(*colour, palette.terminal_bg),
                4.5,
                format!("{name}: ansi_bright[{index}] on terminal_bg"),
            );
        }
        // Outlines are shapes rather than text, so they answer to the
        // 3:1 non-text rule — and only the ones that carry a state do.
        // `border` is what marks a hovered control, `border_strong` a
        // pressed one and a focused row; both are checked on every surface
        // because a hovered card and a focused row sit on all of them.
        // `border_subtle` is a separator and is exempt.
        for (line_name, line) in [
            ("border", palette.border),
            ("border_strong", palette.border_strong),
        ] {
            for (surface_name, surface) in surfaces {
                require(
                    contrast_ratio(line, surface),
                    3.0,
                    format!("{name}: {line_name} on {surface_name}"),
                );
            }
        }
        // The terminal viewport has to be findable against the panel
        // behind it. It is a fill inside a border, and either one alone
        // shows where it starts, so the theme is free to lean on whichever
        // suits it — the dark themes sink the fill, the light one draws
        // the edge.
        require(
            contrast_ratio(palette.terminal_bg, palette.panel)
                .max(contrast_ratio(palette.terminal_border, palette.panel)),
            1.2,
            format!("{name}: terminal edge against the panel"),
        );
        // The drop veil is a translucent black over whatever page was
        // showing, so it has to be composited before it can be measured —
        // and it is measured over the *lightest* surface it can cover,
        // which is the veil at its weakest.
        let veil = {
            let alpha = f32::from(palette.scrim.a()) / 255.0;
            let over = |source: u8, surface: u8| {
                (f32::from(source) + f32::from(surface) * (1.0 - alpha)).round() as u8
            };
            Color32::from_rgb(
                over(palette.scrim.r(), palette.raised.r()),
                over(palette.scrim.g(), palette.raised.g()),
                over(palette.scrim.b(), palette.raised.b()),
            )
        };
        require(
            contrast_ratio(palette.on_scrim, veil),
            4.5,
            format!("{name}: on_scrim over the composited veil"),
        );
    }
    assert!(
        failures.is_empty(),
        "unreadable pairs:\n{}",
        failures.join("\n")
    );
}

/// Keyboard focus on a custom-drawn row is a stroke or nothing: the helper
/// decides, the call sites only paint. Both arms are pinned so a refactor
/// that drops the outline fails here rather than shipping an invisible stop
/// on the Tab order.
#[test]
pub(crate) fn keyboard_focus_on_a_custom_row_is_a_strong_outline_or_nothing() {
    for theme in AppTheme::all() {
        let palette = theme.palette();
        assert_eq!(
            focus_stroke(true, palette),
            Some(egui::Stroke::new(1.0, palette.border_strong)),
            "{}",
            theme.label(),
        );
        assert_eq!(focus_stroke(false, palette), None, "{}", theme.label());
    }
}

/// `DESIGN.md` carries the tokens as YAML front matter, in the format
/// <https://github.com/google-labs-code/design.md> specifies, so that the
/// design system is readable by a person and by the next agent to open
/// this repository. A document that says one thing while the binary paints
/// another is worse than no document, so the two are compared here: every
/// role, in every theme, by name and by value, in both directions.
#[test]
pub(crate) fn design_md_documents_exactly_what_the_app_paints() {
    use std::collections::BTreeMap;

    let document = include_str!("../DESIGN.md");
    let front_matter = document
        .strip_prefix("---\n")
        .and_then(|rest| rest.split_once("\n---\n"))
        .map(|(front_matter, _)| front_matter)
        .expect("DESIGN.md must open with a --- fenced front matter block");
    let colors = front_matter
        .split_once("\ncolors:\n")
        .map(|(_, rest)| rest)
        .expect("DESIGN.md front matter must define colors");
    let mut documented = BTreeMap::new();
    for line in colors.lines() {
        // The colours block ends at the next top-level key.
        if !line.starts_with("  ") && !line.trim().is_empty() {
            break;
        }
        let Some((name, value)) = line.trim().split_once(": \"") else {
            continue;
        };
        documented.insert(name.to_owned(), value.trim_end_matches('"').to_owned());
    }

    // Rust cannot walk a struct's fields, so a role added to `Palette` and
    // forgotten in `tokens()` would be invisible to the comparison below.
    // This count is the tripwire: raising it is the step that reminds you
    // to document the new role and give it a value in all three themes.
    assert_eq!(
        AppTheme::Dark.palette().tokens().len(),
        62,
        "a role was added to or removed from Palette::tokens"
    );

    let mut painted = BTreeMap::new();
    for (theme, prefix) in [
        (AppTheme::Dark, "dark"),
        (AppTheme::Light, "light"),
        (AppTheme::HighContrast, "contrast"),
    ] {
        for (name, colour) in theme.palette().tokens() {
            let hex = if colour.a() == 255 {
                format!("#{:02X}{:02X}{:02X}", colour.r(), colour.g(), colour.b())
            } else {
                format!(
                    "#{:02X}{:02X}{:02X}{:02X}",
                    colour.r(),
                    colour.g(),
                    colour.b(),
                    colour.a()
                )
            };
            painted.insert(format!("{prefix}-{name}"), hex);
        }
    }

    // The four brand colours name the identity rather than a role, so they
    // are documented without a theme prefix and are not painted directly.
    for brand in ["primary", "secondary", "tertiary", "neutral"] {
        assert!(
            documented.remove(brand).is_some(),
            "DESIGN.md must name the brand colour `{brand}`"
        );
    }

    let mut drift = Vec::new();
    for (name, expected) in &painted {
        match documented.get(name) {
            Some(actual) if actual == expected => {}
            Some(actual) => drift.push(format!(
                "{name}: DESIGN.md says {actual}, app paints {expected}"
            )),
            None => drift.push(format!(
                "{name}: painted by the app, missing from DESIGN.md"
            )),
        }
    }
    for name in documented.keys() {
        if !painted.contains_key(name) {
            drift.push(format!(
                "{name}: documented in DESIGN.md, painted by nothing"
            ));
        }
    }
    assert!(
        drift.is_empty(),
        "DESIGN.md has drifted:\n{}",
        drift.join("\n")
    );
}

/// ANSI numbers mean colours, not table offsets: a CLI that asks for red
/// has to get the theme's red in every theme.
#[test]
pub(crate) fn ansi_numbers_map_to_the_colours_they_name() {
    for theme in AppTheme::all() {
        let palette = theme.palette();
        let name = theme.label();
        assert_eq!(
            terminal_ansi_color(1, false, palette),
            palette.danger,
            "{name} red"
        );
        assert_eq!(
            terminal_ansi_color(2, false, palette),
            palette.success,
            "{name} green"
        );
        assert_eq!(
            terminal_ansi_color(3, false, palette),
            palette.warning,
            "{name} yellow"
        );
        assert_eq!(
            terminal_ansi_color(4, false, palette),
            palette.info,
            "{name} blue"
        );
        // Out-of-range indices clamp rather than panicking on output the
        // app did not write.
        assert_eq!(
            terminal_ansi_color(200, false, palette),
            palette.ansi[7],
            "{name} clamp"
        );
        // The 256-colour grey a CLI writes its hints in has to stay a
        // hint: readable, but quieter than ordinary output.
        let hint = terminal_ansi_256_color(244, palette);
        let ordinary = terminal_ansi_256_color(252, palette);
        assert!(
            contrast_ratio(hint, palette.terminal_bg) >= 3.0,
            "{name}: 256-colour hint grey is invisible"
        );
        assert!(
            contrast_ratio(hint, palette.terminal_bg)
                < contrast_ratio(ordinary, palette.terminal_bg),
            "{name}: 256-colour hint grey does not read as quieter"
        );
    }
}

/// Switching themes has to reach the terminal too. Output is coloured once
/// and cached as a laid-out job, so a stale cache would leave every open
/// terminal in the colours of the theme it was captured under.
#[test]
pub(crate) fn switching_themes_recolours_open_terminals() {
    let root = std::env::temp_dir().join(format!("operon-theme-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let data_file = root.join("store.json");
    let session_id = Uuid::new_v4();
    let mut app = OperonApp::from_state(data_file, Store::default(), ToolStatus::default(), None);
    app.set_session_output(session_id, "\x1b[31m失敗しました\x1b[0m".to_owned(), None);
    let dark = app.terminal_layouts.get(&session_id).cloned().unwrap();
    assert_eq!(dark[0].sections[0].format.color, DARK_PALETTE.danger);

    app.store.theme = AppTheme::Light;
    let context = egui::Context::default();
    app.apply_appearance(&context);
    assert!(app.terminal_layouts.is_empty());

    app.set_session_output(session_id, "\x1b[31m失敗しました\x1b[0m".to_owned(), None);
    let light = app.terminal_layouts.get(&session_id).cloned().unwrap();
    assert_eq!(light[0].sections[0].format.color, LIGHT_PALETTE.danger);
    fs::remove_dir_all(&root).ok();
}

/// One press and one release, on separate passes. egui reads a click out of
/// a release that lands on the widget the press went to, so a press and a
/// release inside a single pass is not a click at all.
pub(crate) fn click_at(
    context: &egui::Context,
    position: egui::Pos2,
    mut pass: impl FnMut(&egui::Context),
) {
    let input = |events: Vec<egui::Event>| egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(900.0, 600.0),
        )),
        events,
        ..Default::default()
    };
    let button = |pressed| {
        vec![
            egui::Event::PointerMoved(position),
            egui::Event::PointerButton {
                pos: position,
                button: egui::PointerButton::Primary,
                pressed,
                modifiers: egui::Modifiers::default(),
            },
        ]
    };
    let _ = context.run(input(button(true)), &mut pass);
    let _ = context.run(input(button(false)), &mut pass);
}

/// A card that opens the thing it describes has to lose to the controls
/// drawn on it, or the stop button on a session row would silently open a
/// terminal instead of stopping anything. That ordering is a property of
/// `UiBuilder::sense` registering the card behind its own contents, not of
/// the rect it is given, so it is worth pinning to a test.
#[test]
pub(crate) fn a_clickable_card_yields_to_the_controls_drawn_on_it() {
    for aim in ["surface", "label", "button"] {
        let context = egui::Context::default();
        let card_rect = std::cell::Cell::new(egui::Rect::NOTHING);
        let label_rect = std::cell::Cell::new(egui::Rect::NOTHING);
        let button_rect = std::cell::Cell::new(egui::Rect::NOTHING);
        let card_clicks = std::cell::Cell::new(0);
        let button_clicks = std::cell::Cell::new(0);
        let mut pass = |context: &egui::Context| {
            egui::CentralPanel::default().show(context, |ui| {
                let row = clickable_card(ui, &DARK_PALETTE, "row", true, |ui| {
                    ui.horizontal(|ui| {
                        label_rect.set(ui.label("セッション名").rect);
                        let button = ui.button("停止");
                        button_rect.set(button.rect);
                        if button.clicked() {
                            button_clicks.set(button_clicks.get() + 1);
                        }
                    });
                });
                card_rect.set(row.response.rect);
                if row.response.clicked() {
                    card_clicks.set(card_clicks.get() + 1);
                }
            });
        };
        let _ = context.run(egui::RawInput::default(), &mut pass);
        let target = match aim {
            // The far end of the row, where nothing but the card is drawn.
            "surface" => card_rect.get().right_center() - egui::vec2(20.0, 0.0),
            "label" => label_rect.get().center(),
            _ => button_rect.get().center(),
        };
        click_at(&context, target, &mut pass);

        if aim == "button" {
            assert_eq!(button_clicks.get(), 1, "the button lost its own click");
            assert_eq!(
                card_clicks.get(),
                0,
                "the card took a click meant for the button"
            );
        } else {
            assert_eq!(
                card_clicks.get(),
                1,
                "the card did not take a click on {aim}"
            );
            assert_eq!(button_clicks.get(), 0, "the button took a click on {aim}");
        }
    }
}

/// Tapping a session anywhere in a list is what opens its terminal: the
/// recent-sessions list on the dashboard is read as a list of places to go,
/// and a row that only responds to one small glyph is a row that does not
/// look like one.
#[test]
pub(crate) fn tapping_a_session_row_opens_its_terminal() {
    let root = std::env::temp_dir().join(format!("operon-row-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let session = test_session(Uuid::new_v4(), SessionStatus::Active);
    let mut store = Store::default();
    store.sessions.push(session.clone());
    let mut app =
        OperonApp::from_state(root.join("store.json"), store, ToolStatus::default(), None);
    app.page = Page::Home;
    app.selected_session = None;

    let context = egui::Context::default();
    let card_rect = std::cell::Cell::new(egui::Rect::NOTHING);
    let mut pass = |context: &egui::Context| {
        egui::CentralPanel::default().show(context, |ui| {
            let before = ui.next_widget_position();
            app.session_card(ui, &session);
            card_rect.set(egui::Rect::from_min_max(before, ui.min_rect().max));
        });
    };
    let _ = context.run(egui::RawInput::default(), &mut pass);
    // The status column, which carries a label and nothing clickable.
    let target = card_rect.get().left_top() + egui::vec2(40.0, 24.0);
    click_at(&context, target, &mut pass);

    assert_eq!(app.page, Page::Sessions);
    assert_eq!(app.selected_session, Some(session.id));
    fs::remove_dir_all(&root).ok();
}

/// One verb per state, shared by every surface that acts on a session: the
/// pane corner, the session card, and the grid node all draw what
/// `session_verb` returns, so the word and the action cannot drift apart
/// between them. A stop that has not landed yet must stay pressable — the
/// retry path for a pending cancellation is pressing the same verb again — so
/// it keeps its action rather than going dark while the terminal winds down.
#[test]
pub(crate) fn session_verb_names_one_verb_per_state() {
    let mut session = test_session(Uuid::new_v4(), SessionStatus::Active);

    let verb = session_verb(&session, false).expect("an active session offers its verb");
    assert_eq!(verb.label, "停止");
    assert!(verb.danger, "stop is the one danger verb");
    assert!(matches!(verb.action, SessionVerbAction::Stop));

    let verb = session_verb(&session, true).expect("a stopping session keeps its verb");
    assert_eq!(verb.label, "停止中…");
    assert!(
        matches!(verb.action, SessionVerbAction::Stop),
        "a pending cancellation is retried by pressing the verb again"
    );

    session.status = SessionStatus::Queued;
    let verb = session_verb(&session, false).expect("a queued session offers force-start");
    assert_eq!(verb.label, "今すぐ開始");
    assert!(matches!(verb.action, SessionVerbAction::Start));

    session.status = SessionStatus::Failed;
    session.native_session_id = Some("native-id".into());
    let verb = session_verb(&session, false).expect("a failed session offers its verb");
    assert_eq!(verb.label, "会話 ID から再開");
    assert!(matches!(verb.action, SessionVerbAction::ResumeNative));

    session.native_session_id = None;
    let verb = session_verb(&session, false).expect("a failed session offers its verb");
    assert_eq!(verb.label, "再試行");
    assert!(matches!(verb.action, SessionVerbAction::Start));

    session.status = SessionStatus::Exited;
    session.native_session_id = Some("native-id".into());
    let verb = session_verb(&session, false).expect("an ended native session can resume");
    assert_eq!(verb.label, "会話 ID から再開");
    assert!(matches!(verb.action, SessionVerbAction::ResumeNative));

    session.native_session_id = None;
    assert!(
        session_verb(&session, false).is_none(),
        "a plain exited session has no verb; closing its terminal is not one"
    );

    for status in [
        SessionStatus::Starting,
        SessionStatus::Unknown,
        SessionStatus::Cancelled,
    ] {
        session.status = status.clone();
        assert!(
            session_verb(&session, false).is_none(),
            "status {status:?} has no verb without a native conversation id"
        );
    }
}

#[test]
pub(crate) fn relative_time_is_human_readable() {
    let reference = now();
    assert_eq!(relative_time(reference), "たった今");
    assert_eq!(relative_time(reference.saturating_sub(120)), "2分前");
    assert_eq!(relative_time(reference.saturating_sub(7_200)), "2時間前");
    assert_eq!(relative_time(reference.saturating_sub(172_800)), "2日前");
}

#[test]
pub(crate) fn bundled_terminal_fonts_keep_cjk_at_exactly_two_ascii_cells() {
    use ab_glyph::Font;

    for font_data in [
        include_bytes!("../assets/fonts/SarasaMonoJ-Regular.ttf").as_slice(),
        include_bytes!("../assets/fonts/SarasaMonoK-Regular.ttf").as_slice(),
        include_bytes!("../assets/fonts/SarasaTermJ-Regular.ttf").as_slice(),
        include_bytes!("../assets/fonts/SarasaFixedJ-Regular.ttf").as_slice(),
    ] {
        let font = ab_glyph::FontRef::try_from_slice(font_data)
            .expect("the bundled static terminal font should parse");
        for character in ['X', 'あ', '次', '한'] {
            assert_ne!(font.glyph_id(character).0, 0, "missing {character}");
        }
        let ascii_advance = font.h_advance_unscaled(font.glyph_id('X'));
        assert_eq!(
            font.h_advance_unscaled(font.glyph_id('あ')),
            ascii_advance * 2.0
        );
        assert_eq!(
            font.h_advance_unscaled(font.glyph_id('次')),
            ascii_advance * 2.0
        );
        assert_eq!(
            font.h_advance_unscaled(font.glyph_id('한')),
            ascii_advance * 2.0
        );
    }
}

