/// Every name in the vocabulary has to be a glyph the bundled icon font
/// actually draws, and no earlier face in the chain may claim its
/// codepoint. Both failures are silent: a missing glyph is a blank box, and
/// a shadowed one is whatever the text face happens to keep there.
#[test]
pub(crate) fn every_icon_resolves_from_the_bundled_icon_font() {
    use ab_glyph::Font;

    let phosphor = ab_glyph::FontRef::try_from_slice(egui_phosphor::Variant::Regular.font_bytes())
        .expect("the bundled icon font should parse");
    let sarasa = ab_glyph::FontRef::try_from_slice(
        include_bytes!("../assets/fonts/SarasaUiJ-Regular.ttf").as_slice(),
    )
    .expect("the bundled UI font should parse");

    for (name, icon) in ICON_VOCABULARY {
        let mut characters = icon.chars();
        let character = characters
            .next()
            .unwrap_or_else(|| panic!("{name} is empty"));
        assert!(
            characters.next().is_none(),
            "{name} is more than one glyph, so it cannot line up with the text beside it"
        );
        assert_ne!(
            phosphor.glyph_id(character).0,
            0,
            "{name} is not a glyph the icon font draws"
        );
        assert_eq!(
            sarasa.glyph_id(character).0,
            0,
            "{name} would be drawn by the text face instead of the icon font"
        );
    }
}

/// Not every mark in the app is an icon. Three characters are written into
/// text rather than named through `ICON_*`: the bullet a rendered Markdown
/// list gets, the arrow in `old → new` on a renamed file, and the minus in
/// a `−3` count beside a `+12`. They are punctuation inside a phrase rather
/// than pictograms standing in for one, so the rule they answer to is the
/// opposite of the icons' — they must come from the *text* face, at the
/// weight of the words around them, and never from the icon font.
#[test]
pub(crate) fn the_typographic_marks_in_text_come_from_the_text_face() {
    use ab_glyph::Font;

    let sarasa = ab_glyph::FontRef::try_from_slice(
        include_bytes!("../assets/fonts/SarasaUiJ-Regular.ttf").as_slice(),
    )
    .expect("the bundled UI font should parse");
    for (what, character) in [
        ("the Markdown list bullet", '•'),
        ("the rename arrow", '→'),
        ("the minus in a diff count", '−'),
    ] {
        assert_ne!(
            sarasa.glyph_id(character).0,
            0,
            "{what} is not a glyph the text face draws, so it would fall \
             through to whichever face in the chain happens to own it"
        );
    }
}
