#[test]
pub(crate) fn instance_lock_holder_process() {
    let (Ok(store), Ok(ready)) = (
        std::env::var("OPERON_TEST_INSTANCE_STORE"),
        std::env::var("OPERON_TEST_INSTANCE_READY"),
    ) else {
        return;
    };
    let _lock = acquire_instance_lock(Path::new(&store)).unwrap();
    fs::write(ready, "locked").unwrap();
    thread::sleep(Duration::from_secs(10));
}
#[test]
pub(crate) fn instance_lock_rejects_a_second_process_and_releases_after_crash() {
    let root = std::env::temp_dir().join(format!("operon-instance-lock-{}", Uuid::new_v4()));
    let store = root.join("store.json");
    let ready = root.join("ready");
    let mut holder = Command::new(std::env::current_exe().unwrap())
        .args([
            "--exact",
            "tests::instance_lock_holder_process",
            "--nocapture",
        ])
        .env("OPERON_TEST_INSTANCE_STORE", &store)
        .env("OPERON_TEST_INSTANCE_READY", &ready)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    for _ in 0..CHECKPOINT_POLLS {
        if ready.exists() {
            break;
        }
        assert!(holder.try_wait().unwrap().is_none());
        thread::sleep(Duration::from_millis(10));
    }
    assert!(ready.exists());

    assert!(acquire_instance_lock(&store)
        .unwrap_err()
        .to_string()
        .contains("別の Operon プロセス"));
    holder.kill().unwrap();
    holder.wait().unwrap();
    assert!(acquire_instance_lock(&store).is_ok());
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn instance_lock_distinguishes_storage_errors_from_contention() {
    let root = std::env::temp_dir().join(format!("operon-instance-error-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let blocked_parent = root.join("not-a-directory");
    fs::write(&blocked_parent, "file").unwrap();

    let error = acquire_instance_lock(&blocked_parent.join("store-v2.json")).unwrap_err();

    assert!(matches!(error, InstanceLockError::Unavailable(_)));
    assert!(!error.to_string().contains("別の Operon プロセス"));
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn imports_the_legacy_store_once_without_modifying_its_snapshot() {
    let root = std::env::temp_dir().join(format!("operon-store-migration-{}", Uuid::new_v4()));
    let legacy = root.join("store.json");
    let current = root.join("store-v2.json");
    let pending = Uuid::new_v4();
    let legacy_store = Store {
        projects: vec![Project {
            id: Uuid::new_v4(),
            path: PathBuf::from("/tmp/imported-project"),
            name: "imported-project".into(),
            added_at: now(),
        }],
        pending_cancellations: vec![pending],
        ..Store::default()
    };
    save_store(&legacy, &legacy_store).unwrap();
    save_cancellation_intents(&legacy, &[pending]).unwrap();
    let original_store = fs::read(&legacy).unwrap();
    let original_sidecar = fs::read(cancellation_intents_file(&legacy)).unwrap();

    let migration = import_legacy_store_if_needed(&current, &legacy).unwrap();

    assert!(migration.notice.is_some());
    assert!(!migration.durability_retry_needed);
    assert_eq!(
        load_store(&current).unwrap().projects,
        legacy_store.projects
    );
    assert_eq!(load_cancellation_intents(&current).unwrap(), vec![pending]);
    assert_eq!(fs::read(&legacy).unwrap(), original_store);
    assert_eq!(
        fs::read(cancellation_intents_file(&legacy)).unwrap(),
        original_sidecar
    );

    save_store(&current, &Store::default()).unwrap();
    assert!(import_legacy_store_if_needed(&current, &legacy)
        .unwrap()
        .notice
        .is_none());
    assert!(load_store(&current).unwrap().projects.is_empty());
    fs::remove_dir_all(root).unwrap();
}
