pub(crate) fn current_and_legacy_builds_use_distinct_store_files() {
    let candidates = legacy_app_data_files();
    assert_eq!(app_data_file().file_name().unwrap(), "store-v2.json");
    assert!(!candidates.contains(&app_data_file()));
    // The pre-rename protected index outranks either pre-versioned one, so
    // a Mac that ran both keeps the newer snapshot.
    assert_eq!(
        candidates[0],
        legacy_brand_data_directory().join("store-v2.json")
    );
    assert!(candidates[1..]
        .iter()
        .all(|candidate| candidate.file_name().unwrap() == "store.json"));
    assert_ne!(legacy_brand_data_directory(), app_data_directory());
    assert_eq!(
        instance_lock_file(&app_data_file()).unwrap(),
        instance_lock_file(&app_data_directory().join("store.json")).unwrap()
    );
}
#[test]
pub(crate) fn the_newest_legacy_snapshot_wins_and_none_of_them_are_modified() {
    let root = std::env::temp_dir().join(format!("operon-brand-migration-{}", Uuid::new_v4()));
    let renamed = root.join("previous-brand-store-v2.json");
    let pre_versioned = root.join("previous-brand-store.json");
    let current = root.join("store-v2.json");
    let store_with = |name: &str| Store {
        projects: vec![Project {
            id: Uuid::new_v4(),
            path: PathBuf::from("/tmp/operon-brand-migration"),
            name: name.into(),
            added_at: now(),
        }],
        ..Store::default()
    };
    save_store(&renamed, &store_with("renamed")).unwrap();
    save_store(&pre_versioned, &store_with("pre-versioned")).unwrap();
    let original_renamed = fs::read(&renamed).unwrap();
    let original_pre_versioned = fs::read(&pre_versioned).unwrap();

    let migration = import_first_legacy_store(
        &current,
        &[
            renamed.clone(),
            root.join("absent.json"),
            pre_versioned.clone(),
        ],
    )
    .unwrap();

    assert!(migration
        .notice
        .unwrap()
        .contains("previous-brand-store-v2"));
    assert_eq!(load_store(&current).unwrap().projects[0].name, "renamed");
    assert_eq!(fs::read(&renamed).unwrap(), original_renamed);
    assert_eq!(fs::read(&pre_versioned).unwrap(), original_pre_versioned);

    assert!(
        import_first_legacy_store(&current, &[renamed, pre_versioned])
            .unwrap()
            .notice
            .is_none()
    );
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn atomic_write_distinguishes_precommit_failure_from_committed_unsynced_data() {
    let root = std::env::temp_dir().join(format!("operon-atomic-write-phases-{}", Uuid::new_v4()));
    let path = root.join("store.json");
    fs::create_dir_all(&root).unwrap();
    fs::write(&path, b"old").unwrap();

    let precommit = write_file_atomically_with_sync(
        &path,
        b"not-committed",
        |_| Err(std::io::Error::other("injected file sync failure")),
        |_| Ok(()),
    );
    assert!(precommit.is_err());
    assert_eq!(fs::read(&path).unwrap(), b"old");

    let postcommit = write_file_atomically_with_sync(
        &path,
        b"committed",
        |_| Ok(()),
        |_| Err(std::io::Error::other("injected directory sync failure")),
    )
    .unwrap();
    assert!(matches!(postcommit, WriteOutcome::CommittedButNotSynced(_)));
    assert_eq!(fs::read(&path).unwrap(), b"committed");
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn committed_unsynced_persistence_keeps_memory_and_schedules_a_retry() {
    let mut app = test_app(PathBuf::from("/tmp/operon-committed-unsynced.json"));
    let project = Project {
        id: Uuid::new_v4(),
        path: PathBuf::from("/tmp/project"),
        name: "project".into(),
        added_at: now(),
    };
    app.store.projects.push(project.clone());

    assert!(
        app.apply_persist_result(Ok(WriteOutcome::CommittedButNotSynced(
            "injected directory sync failure".into()
        )))
    );

    assert_eq!(app.store.projects, vec![project]);
    assert!(app.store_retry_pending);
    assert!(app
        .durability_warning
        .as_deref()
        .is_some_and(
            |notice| notice.contains("書き込まれました") && !notice.contains("適用されていません")
        ));
}
#[test]
pub(crate) fn cancellation_waits_when_neither_recovery_copy_is_confirmed_durable() {
    let root = std::env::temp_dir().join(format!("operon-cancel-dual-unsynced-{}", Uuid::new_v4()));
    let session_id = Uuid::new_v4();
    let mut app = OperonApp::from_state(
        root.join("store.json"),
        Store {
            sessions: vec![test_session(session_id, SessionStatus::Active)],
            ..Store::default()
        },
        ToolStatus::default(),
        None,
    );
    let previous_store = app.store.clone();
    app.store.pending_cancellations.push(session_id);

    let ready_to_stop = app.apply_cancellation_intent_write_results(
        previous_store,
        Ok(WriteOutcome::CommittedButNotSynced(
            "injected sidecar directory sync failure".into(),
        )),
        Ok(WriteOutcome::CommittedButNotSynced(
            "injected main directory sync failure".into(),
        )),
    );

    assert!(!ready_to_stop);
    assert_eq!(app.store.sessions[0].status, SessionStatus::Active);
    assert_eq!(app.store.pending_cancellations, vec![session_id]);
    assert!(app.store_retry_pending);
    assert!(!app
        .background_tasks
        .contains(&BackgroundKey::SessionStop(session_id)));
    assert!(app
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("tmux は変更していません")));

    app.retry_pending_store();
    assert!(!app.store_retry_pending);
    assert!(app.persist_cancellation_intent(session_id));
    fs::remove_dir_all(root).unwrap();
}
