#[test]
pub(crate) fn partial_legacy_import_retries_without_modifying_the_legacy_snapshot() {
    let root = std::env::temp_dir().join(format!("operon-partial-import-{}", Uuid::new_v4()));
    let legacy = root.join("store.json");
    let current = root.join("store-v2.json");
    let pending = Uuid::new_v4();
    save_store(&legacy, &Store::default()).unwrap();
    save_cancellation_intents(&legacy, &[pending]).unwrap();
    let original_store = fs::read(&legacy).unwrap();
    let original_sidecar = fs::read(cancellation_intents_file(&legacy)).unwrap();
    let mut fail_main_once = true;

    let error = import_legacy_store_if_needed_with_writer(&current, &legacy, |path, contents| {
        if path == current && fail_main_once {
            fail_main_once = false;
            Err(anyhow!("injected interruption before main-store commit"))
        } else {
            write_file_atomically(path, contents)
        }
    })
    .unwrap_err();
    assert!(format!("{error:#}").contains("main-store commit"));
    assert!(!current.exists());
    assert_eq!(load_cancellation_intents(&current).unwrap(), vec![pending]);

    let retried = import_legacy_store_if_needed(&current, &legacy).unwrap();
    assert!(retried.notice.is_some());
    assert!(current.exists());
    assert_eq!(load_cancellation_intents(&current).unwrap(), vec![pending]);
    assert_eq!(fs::read(&legacy).unwrap(), original_store);
    assert_eq!(
        fs::read(cancellation_intents_file(&legacy)).unwrap(),
        original_sidecar
    );
    fs::remove_dir_all(root).unwrap();
}
