pub(crate) fn failed_session_has_a_durable_retry_transition() {
    let root = std::env::temp_dir().join(format!("operon-session-retry-{}", Uuid::new_v4()));
    let project_path = root.join("project");
    fs::create_dir_all(&project_path).unwrap();
    let project_id = Uuid::new_v4();
    let session_id = Uuid::new_v4();
    let mut session = test_session(session_id, SessionStatus::Failed);
    session.project_id = project_id;
    session.worktree_path = Some(project_path.clone());
    session.agent = "definitely-missing-operon-agent".into();
    session.agent_command = "definitely-missing-operon-agent".into();
    session.tmux_name = format!("operon-retry-{}", session_id.simple());
    let mut app = test_app(root.join("store.json"));
    app.store.projects.push(Project {
        id: project_id,
        path: project_path,
        name: "retry-project".into(),
        added_at: now(),
    });
    app.store.sessions.push(session);

    app.start_session(session_id);

    assert_eq!(app.store.sessions[0].status, SessionStatus::Starting);
    assert!(app
        .background_tasks
        .contains(&BackgroundKey::SessionStart(session_id)));
    assert_eq!(
        load_store(&app.data_file).unwrap().sessions[0].status,
        SessionStatus::Starting
    );
    wait_for_background_task(
        &mut app,
        &BackgroundKey::SessionStart(session_id),
        Duration::from_secs(15),
    );
    assert_eq!(app.store.sessions[0].status, SessionStatus::Failed);
    assert_eq!(
        load_store(&app.data_file).unwrap().sessions[0].status,
        SessionStatus::Failed
    );
    assert!(app
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("開始できませんでした")));
    fs::remove_dir_all(root).unwrap();
}
/// The end of a turn is what the user asked to hear about, and it has to
/// survive the poll cadence: the same idle screen is seen over and over.
#[test]
pub(crate) fn announces_a_finished_turn_once_per_managed_session() {
    let root = std::env::temp_dir().join(format!("operon-activity-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let session_id = Uuid::new_v4();
    let mut session = test_session(session_id, SessionStatus::Active);
    session.name = "auth refactor".into();
    session.agent = "claude".into();
    let mut app = OperonApp::from_state(
        root.clone(),
        Store {
            sessions: vec![session],
            notifications_enabled: true,
            ..Store::default()
        },
        ToolStatus::default(),
        None,
    );
    let mut announced = Vec::new();
    for activity in [
        AgentActivity::Idle,
        AgentActivity::Idle,
        AgentActivity::Working,
        AgentActivity::Idle,
        AgentActivity::Idle,
        AgentActivity::Idle,
        AgentActivity::Idle,
    ] {
        announced.extend(app.session_activity_notifications(vec![(session_id, activity)]));
    }
    assert_eq!(announced, vec!["Claude Code が完了しました: auth refactor"]);
    // A session that is gone stops being tracked rather than accumulating.
    app.session_activity_notifications(Vec::new());
    assert!(app.session_activity.is_empty());
    fs::remove_dir_all(root).unwrap();
}
