#[test]
pub(crate) fn external_start_state_is_retained_when_metadata_save_fails() {
    let root = std::env::temp_dir().join(format!("operon-external-start-save-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let session_id = Uuid::new_v4();
    let mut app = OperonApp::from_state(
        root.clone(),
        Store {
            sessions: vec![test_session(session_id, SessionStatus::Starting)],
            ..Store::default()
        },
        ToolStatus::default(),
        None,
    );
    app.background_tasks
        .insert(BackgroundKey::SessionStart(session_id));
    app.background_sender
        .send(BackgroundResult::SessionStarted {
            session_id,
            result: Ok(Some("feature/retry".into())),
        })
        .unwrap();

    app.process_background_results();

    assert_eq!(app.store.sessions[0].status, SessionStatus::Active);
    assert_eq!(
        app.store.sessions[0].branch.as_deref(),
        Some("feature/retry")
    );
    assert!(app.store_retry_pending);
    assert_eq!(app.selected_session, Some(session_id));
    fs::remove_dir_all(root).unwrap();
}

