#[test]
pub(crate) fn prevents_removing_a_record_required_by_a_queued_session() {
    let parent_id = Uuid::new_v4();
    let mut queued = test_session(Uuid::new_v4(), SessionStatus::Queued);
    queued.depends_on = vec![parent_id];
    let sessions = vec![test_session(parent_id, SessionStatus::Exited), queued];
    assert_eq!(queued_dependency_count(&sessions, parent_id), 1);
    assert_eq!(queued_dependency_count(&sessions, Uuid::new_v4()), 0);

    let root = std::env::temp_dir().join(format!("operon-dependency-{}", Uuid::new_v4()));
    let mut app = OperonApp::from_state(
        root.join("store.json"),
        Store {
            sessions,
            ..Store::default()
        },
        ToolStatus::default(),
        None,
    );
    app.remove_session_record(parent_id);
    assert!(app
        .store
        .sessions
        .iter()
        .any(|session| session.id == parent_id));
    assert!(app
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("依存されています")));
}

#[test]
pub(crate) fn removing_the_last_session_keeps_its_project() {
    let root = std::env::temp_dir().join(format!("operon-last-session-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let project_id = Uuid::new_v4();
    let session_id = Uuid::new_v4();
    let mut session = test_session(session_id, SessionStatus::Exited);
    session.project_id = project_id;
    let project = Project {
        id: project_id,
        path: root.clone(),
        name: "Retained project".into(),
        added_at: now(),
    };
    let mut app = OperonApp::from_state(
        root.join("store.json"),
        Store {
            projects: vec![project],
            sessions: vec![session],
            ..Store::default()
        },
        ToolStatus::default(),
        None,
    );

    app.remove_session_record(session_id);

    assert!(app.store.sessions.is_empty());
    assert_eq!(app.store.projects.len(), 1);
    assert_eq!(app.store.projects[0].id, project_id);
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn recognizes_agent_modes_that_require_explicit_confirmation() {
    assert!(is_dangerous_agent_mode("danger-full-access"));
    assert!(is_dangerous_agent_mode("bypassPermissions"));
    assert!(!is_dangerous_agent_mode("dontAsk"));
    assert!(!is_dangerous_agent_mode("workspace-write"));
    // Every value this recognises has to be one a picker can still
    // produce. A rule for a value no mode table offers is one that reads
    // as protection and gives none.
    for agent in ["codex", "claude", "gemini"] {
        for mode in agent_mode_options(agent) {
            if is_dangerous_agent_mode(mode) {
                assert!(
                    launch_needs_acknowledgement(agent, mode, &[], ""),
                    "{agent} mode {mode}"
                );
            }
        }
    }
    let reachable = ["codex", "claude", "gemini"]
        .iter()
        .flat_map(|agent| agent_mode_options(agent))
        .filter(|mode| is_dangerous_agent_mode(mode))
        .count();
    assert_eq!(
        reachable, 2,
        "a dangerous mode was added or removed without updating is_dangerous_agent_mode"
    );
}
/// The mode picker stopped being the only way to ask for an unguarded run
/// once the switches arrived, so the confirmation has to read both.
#[test]
pub(crate) fn a_dangerous_switch_asks_for_the_same_confirmation_a_dangerous_mode_does() {
    assert!(launch_needs_acknowledgement(
        "claude",
        "",
        &flag_ids(&["skip-permissions"]),
        ""
    ));
    assert!(launch_needs_acknowledgement(
        "codex",
        "read-only",
        &flag_ids(&["bypass-approvals"]),
        ""
    ));
    assert!(launch_needs_acknowledgement(
        "gemini",
        "",
        &flag_ids(&["skip-permissions"]),
        ""
    ));
    assert!(launch_needs_acknowledgement(
        "codex",
        "danger-full-access",
        &[],
        ""
    ));
    assert!(!launch_needs_acknowledgement(
        "codex",
        "workspace-write",
        &flag_ids(&["approval-never", "search"]),
        ""
    ));
    assert!(!launch_needs_acknowledgement(
        "claude",
        "acceptEdits",
        &flag_ids(&["allow-skip-permissions"]),
        ""
    ));
}

/// The custom agent has no mode picker and no switches, so for years the one
/// route that could put `--dangerously-skip-permissions` in front of tmux was
/// also the one route with no confirmation in front of it. The gate reads the
/// line now, and it reads it out of the same tables the checkboxes are drawn
/// from — so a CLI that renames its switch is one edit in the table.
#[test]
pub(crate) fn a_dangerous_switch_typed_into_a_custom_command_still_asks() {
    let mut asked = 0;
    for agent in AGENTS {
        for flag in agent_flag_options(agent) {
            if !flag.dangerous {
                continue;
            }
            // Both spellings. Every dangerous switch in the tables today is a
            // single argument, so these two strings are equal and the loop's
            // real work is the spaced form — the `=` coverage that matters is
            // the three explicit commands below. The joined form is here so
            // that the first multi-argument dangerous switch is covered by the
            // loop that already walks the table, rather than by remembering.
            for command in [
                format!("{} {}", agent, flag.args.join(" ")),
                format!("{} {}", agent, flag.args.join("=")),
            ] {
                assert!(
                    launch_needs_acknowledgement("custom", "", &[], &command),
                    "`{command}` runs the agent without asking and was not gated"
                );
            }
            asked += 1;
        }
    }
    assert!(
        asked >= 3,
        "no dangerous switch was found in any table, so this proved nothing"
    );

    // The dangerous mode values reach a command line the same way, in both
    // spellings every CLI here accepts. The joined form was a hole: clap and
    // commander both take `--long=value`, and `is_safe_agent_command` permits
    // `=` on purpose, so matching only the spaced form left one route to an
    // unguarded run with nothing asked.
    for command in [
        "codex --sandbox danger-full-access",
        "codex --sandbox=danger-full-access",
        "claude --permission-mode=bypassPermissions",
        // One hyphen. `agy` is Go's `flag` package and takes a long flag either
        // way — confirmed against the binary, which reports only the *other*
        // argument as undefined when both are passed. The table spells two
        // dashes, so until the comparison stripped them this launched
        // Antigravity with every tool auto-approved and nothing asked.
        "agy -dangerously-skip-permissions",
        // clap's hidden alias for --dangerously-bypass-approvals-and-sandbox.
        // `codex -a never --yolo` refuses by naming the long form, which is how
        // it was identified. No picker draws it, so nothing in the flag tables
        // could ever have caught it.
        "codex --yolo",
    ] {
        assert!(
            launch_needs_acknowledgement("custom", "", &[], command),
            "`{command}` runs the agent without asking and was not gated"
        );
    }

    // Every alias walked from its own table, for the same reason the switches
    // are: one that is written down and not walked is one nothing checks.
    for alias in DANGEROUS_ARGUMENT_ALIASES {
        let command = format!("codex {}", alias.join(" "));
        assert!(
            launch_needs_acknowledgement("custom", "", &[], &command),
            "`{command}` is written down as an unguarded run and was not gated"
        );
    }

    // An ordinary line is not gated, or the confirmation stops meaning
    // anything.
    assert!(!launch_needs_acknowledgement(
        "custom",
        "",
        &[],
        "aider --model gpt-5"
    ));

    // Matched as whole arguments. A path that spells the switch inside a longer
    // token is not the switch, and a rule that fired on it would train people
    // to tick the box without reading it.
    assert!(!launch_needs_acknowledgement(
        "custom",
        "",
        &[],
        "/opt/--dangerously-skip-permissions-notes/run.sh"
    ));
}

/// A preset written by this build has to survive being read back, and a
/// store written before presets existed has to load without one.
#[test]
pub(crate) fn a_store_without_presets_still_loads() {
    let store =
        parse_store_contents(br#"{"schema_version":4,"projects":[],"sessions":[]}"#.as_slice())
            .unwrap();
    assert!(store.agent_launch_presets.is_empty());
}
/// Consent is keyed to the combination it was given for, so no edit path
/// has to remember to withdraw it — including edit paths written later.
#[test]
pub(crate) fn editing_the_combination_withdraws_the_consent_given_for_it() {
    let mut app = test_app(PathBuf::from("/tmp/operon-ack.json"));
    app.selected_agent = "codex".into();
    app.agent_model_input = String::new();
    app.agent_mode_input = "read-only".into();
    app.agent_effort_input = String::new();
    app.agent_flag_inputs = flag_ids(&["bypass-approvals"]);
    app.acknowledged_launch = Some(app.pending_launch());
    assert!(app.launch_acknowledged());

    // Ticking the switches in the other order is the same combination.
    app.agent_flag_inputs = flag_ids(&["bypass-approvals"]);
    assert!(app.launch_acknowledged());

    app.agent_flag_inputs.push("search".into());
    assert!(
        !app.launch_acknowledged(),
        "consent survived an edit to the combination"
    );

    // And consent for one CLI is never consent for another.
    app.acknowledged_launch = Some(app.pending_launch());
    assert!(app.launch_acknowledged());
    app.select_agent("claude");
    assert_eq!(app.acknowledged_launch, None);
}
