#[test]
pub(crate) fn git_changes_include_untracked_renamed_and_unborn_repository_content() {
    let root = std::env::temp_dir().join(format!("operon-git-changes-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    for arguments in [
        vec!["init"],
        vec!["config", "user.email", "test@example.invalid"],
        vec!["config", "user.name", "Operon test"],
    ] {
        assert!(git_command(&root)
            .args(arguments)
            .status()
            .unwrap()
            .success());
    }
    fs::write(root.join("old.txt"), "tracked\n").unwrap();
    assert!(git_command(&root)
        .args(["add", "old.txt"])
        .status()
        .unwrap()
        .success());
    assert!(git_command(&root)
        .args(["commit", "-m", "initial"])
        .status()
        .unwrap()
        .success());
    assert!(git_command(&root)
        .args(["mv", "old.txt", "new.txt"])
        .status()
        .unwrap()
        .success());
    fs::write(root.join("untracked.txt"), "new local content\n").unwrap();

    let status = git_output(
        &root,
        &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
    )
    .unwrap();
    let files = parse_porcelain_changed_files(&status);
    assert!(files.iter().any(|file| file.path == "new.txt"));
    assert!(files
        .iter()
        .any(|file| file.status == "??" && file.path == "untracked.txt"));
    assert!(git_working_tree_diff(&root, Some("untracked.txt"))
        .unwrap()
        .contains("new local content"));
    fs::remove_dir_all(root).unwrap();

    let unborn = std::env::temp_dir().join(format!("operon-git-unborn-{}", Uuid::new_v4()));
    fs::create_dir_all(&unborn).unwrap();
    assert!(git_command(&unborn).arg("init").status().unwrap().success());
    fs::write(unborn.join("first.txt"), "before first commit\n").unwrap();
    let diff = git_working_tree_diff(&unborn, None).unwrap();
    assert!(diff.contains("before first commit"));
    fs::remove_dir_all(unborn).unwrap();
}
/// The parse behind the review pane, checked against the shape `git diff`
/// actually writes rather than against a hand-typed idea of it: a rename
/// with edits, and the `--no-index` diff this app synthesises for a file
/// git is not tracking yet.
#[test]
pub(crate) fn parses_the_diff_shapes_git_writes_for_a_working_tree() {
    let root = std::env::temp_dir().join(format!("operon-diff-parse-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let git = |arguments: &[&str]| {
        assert!(git_command(&root)
            .args(arguments)
            .status()
            .unwrap()
            .success());
    };
    git(&["init"]);
    git(&["config", "user.email", "test@example.com"]);
    git(&["config", "user.name", "Test"]);
    fs::write(root.join("a.txt"), "one\ntwo\nthree\n").unwrap();
    git(&["add", "a.txt"]);
    git(&["commit", "-m", "one"]);
    git(&["mv", "a.txt", "b.txt"]);
    fs::write(root.join("b.txt"), "one\nTWO\nthree\nfour\n").unwrap();
    fs::write(root.join("fresh.txt"), "brand new\n").unwrap();

    let files = parse_unified_diff(&git_working_tree_diff(&root, None).unwrap());
    assert_eq!(files.len(), 2, "{files:#?}");

    let renamed = &files[0];
    assert_eq!(renamed.path, "b.txt");
    assert_eq!(renamed.renamed_from.as_deref(), Some("a.txt"));
    assert_eq!(renamed.change, DiffFileChange::Renamed);
    assert_eq!((renamed.added, renamed.removed), (2, 1));
    // `two` was line 2 of the old file and nothing in the new one; `TWO`
    // is line 2 of the new file and nothing in the old.
    let removed = renamed
        .lines
        .iter()
        .find(|line| line.kind == DiffLineKind::Removed)
        .unwrap();
    assert_eq!(removed.text, "two");
    assert_eq!((removed.old_number, removed.new_number), (Some(2), None));
    let added = renamed
        .lines
        .iter()
        .find(|line| line.kind == DiffLineKind::Added)
        .unwrap();
    assert_eq!(added.text, "TWO");
    assert_eq!((added.old_number, added.new_number), (None, Some(2)));
    // The context line after them is numbered on both sides, and the two
    // sides have parted company by one.
    let context = renamed
        .lines
        .iter()
        .filter(|line| line.kind == DiffLineKind::Context)
        .nth(1)
        .unwrap();
    assert_eq!(context.text, "three");
    assert_eq!((context.old_number, context.new_number), (Some(3), Some(3)));

    let fresh = &files[1];
    assert_eq!(fresh.path, "fresh.txt");
    assert_eq!(fresh.change, DiffFileChange::Added);
    assert_eq!((fresh.added, fresh.removed), (1, 0));
    // `--- /dev/null` names no file, so it must not be counted as the
    // removal of one.
    assert!(fresh
        .lines
        .iter()
        .all(|line| line.kind != DiffLineKind::Removed));
    fs::remove_dir_all(root).unwrap();
}

/// A diff the parser has never seen the shape of still has to render. Every
/// unrecognised line becomes a note rather than disappearing, because a
/// review pane that silently drops a line is worse than one that shows an
/// odd one.
#[test]
pub(crate) fn an_unrecognised_diff_line_is_kept_rather_than_dropped() {
    let files = parse_unified_diff(concat!(
        "diff --git a/binary.png b/binary.png\n",
        "index 1111111..2222222 100644\n",
        "Binary files a/binary.png and b/binary.png differ\n",
        "\n",
        "… 差分を 175 KiB で切り詰めました\n",
    ));
    assert_eq!(files.len(), 1);
    assert_eq!(files[0].path, "binary.png");
    assert!(files[0].note.is_some());
    assert!(files[0]
        .lines
        .iter()
        .any(|line| line.kind == DiffLineKind::Note && line.text.contains("切り詰め")));
}

/// The marked substrings of one file's diff, side by side with their sign, so
/// that a test asserts the *words* a reader would see banded rather than the
/// byte offsets that happen to produce them. An offset that drifts one token
/// left still reads as a plausible number; the wrong word does not.
fn marked_words(diff: &str) -> Vec<(DiffLineKind, Vec<String>)> {
    parse_unified_diff(diff)
        .into_iter()
        .flat_map(|file| file.lines)
        .filter(|line| matches!(line.kind, DiffLineKind::Added | DiffLineKind::Removed))
        .map(|line| {
            let marked = line
                .highlights
                .iter()
                .map(|span| line.text[span.clone()].to_owned())
                .collect();
            (line.kind, marked)
        })
        .collect()
}

fn rewrite_diff(removed: &[&str], added: &[&str]) -> String {
    let mut diff = String::from("diff --git a/src/app.rs b/src/app.rs\n--- a/src/app.rs\n+++ b/src/app.rs\n@@ -1,2 +1,2 @@\n");
    for line in removed {
        diff.push_str(&format!("-{line}\n"));
    }
    for line in added {
        diff.push_str(&format!("+{line}\n"));
    }
    diff
}

/// The reason this pane exists: an agent that rewrote one line in place should
/// not make a person compare eighty columns by eye. Only the words that moved
/// are marked, and a whole word is marked rather than the letters inside it —
/// a rename banded letter by letter is harder to read than no marks at all.
///
/// Japanese is in here because a mark is a byte range and a byte range taken
/// mid-character is a panic in the layout, not a wrong colour.
#[test]
pub(crate) fn a_rewritten_line_marks_only_the_words_that_changed() {
    for (removed, added, old_marks, new_marks) in [
        (
            "    let ready = restore_previous_session(project, false);",
            "    let ready = restore_previous_session(project, true);",
            vec!["false"],
            vec!["true"],
        ),
        // Two separate edits in one line: the marks are two bands, not one
        // band spanning everything between them.
        (
            "let total = first + second;",
            "let total = first - third;",
            vec!["+", "second"],
            vec!["-", "third"],
        ),
        // Pure insertion into a line: nothing is marked on the side that lost
        // nothing, and the whole of the new tail is marked on the side that
        // gained it.
        (
            "run(project);",
            "run(project, options);",
            vec![],
            vec![", options"],
        ),
        // The scripts that put no space between their words: a rule that only
        // knew about runs of alphanumeric characters would make each of these
        // lines a single token and mark the whole sentence or none of it.
        (
            "    セッションを復元しました。",
            "    セッションを破棄しました。",
            vec!["復元"],
            vec!["破棄"],
        ),
        (
            "    세션을 복원했습니다.",
            "    세션을 삭제했습니다.",
            vec!["복원"],
            vec!["삭제"],
        ),
    ] {
        let marks = marked_words(&rewrite_diff(&[removed], &[added]));
        assert_eq!(
            marks,
            vec![
                (
                    DiffLineKind::Removed,
                    old_marks.iter().map(|word| word.to_string()).collect()
                ),
                (
                    DiffLineKind::Added,
                    new_marks.iter().map(|word| word.to_string()).collect()
                ),
            ],
            "{removed} → {added}"
        );
    }
}

/// A mark is a claim that these two rows are the same line. Where they are not
/// — a block replaced outright — the claim would be false, so the pane says
/// nothing extra and the row wash carries the change on its own, exactly as it
/// did before this feature existed.
#[test]
pub(crate) fn an_unrelated_replacement_keeps_its_row_wash_and_no_word_marks() {
    for (removed, added) in [
        (
            "let ready = false;",
            "notify_the_operator_about_the_queue();",
        ),
        ("a", "b"),
        ("", "let ready = true;"),
    ] {
        let marks = marked_words(&rewrite_diff(&[removed], &[added]));
        assert!(
            marks.iter().all(|(_, words)| words.is_empty()),
            "{removed:?} → {added:?} was marked as a rewrite: {marks:?}"
        );
    }
}

/// Pairing is positional inside a replacement block, and a block whose two
/// runs are different lengths is the case where positional pairing can pair
/// the wrong two lines. The similarity gate is what makes that safe: the
/// surplus line keeps no marks, and a pair that turns out to be unrelated
/// keeps none either. The failure this test pins down is a *missing* mark —
/// never a mark pointing at the wrong words.
#[test]
pub(crate) fn a_replacement_block_pairs_its_lines_in_order_and_leaves_the_surplus_alone() {
    let marks = marked_words(&rewrite_diff(
        &["let first = 1;", "let second = 2;"],
        &["let first = 11;", "let second = 22;", "let third = 33;"],
    ));
    assert_eq!(
        marks,
        vec![
            (DiffLineKind::Removed, vec!["1".to_string()]),
            (DiffLineKind::Removed, vec!["2".to_string()]),
            (DiffLineKind::Added, vec!["11".to_string()]),
            (DiffLineKind::Added, vec!["22".to_string()]),
            // The third addition has no counterpart. It was inserted, not
            // rewritten, and nothing about it is marked.
            (DiffLineKind::Added, vec![]),
        ]
    );

    // A removal with no counterpart shifts every later line of its block, so
    // this is the shape where positional pairing pairs unrelated lines. It
    // must produce no marks rather than confident wrong ones.
    let shifted = marked_words(&rewrite_diff(
        &["drop_the_stale_worktree(project);", "let second = 2;"],
        &["let second = 22;"],
    ));
    assert!(
        shifted.iter().all(|(_, words)| words.is_empty()),
        "a shifted block invented a pairing: {shifted:?}"
    );

    // Context lines and hunk headers are not part of any pair and never carry
    // a mark, however similar they are to a line that does.
    let whole = parse_unified_diff(&rewrite_diff(&["let a = 1;"], &["let a = 2;"]));
    assert!(whole
        .iter()
        .flat_map(|file| &file.lines)
        .filter(|line| !matches!(line.kind, DiffLineKind::Added | DiffLineKind::Removed))
        .all(|line| line.highlights.is_empty()));
}

/// A minified bundle is one line of a hundred thousand tokens, and the word
/// comparison is quadratic. Past `DIFF_WORD_TOKEN_LIMIT` the pair keeps the
/// prefix and suffix it can find in linear time and marks everything between
/// them as one span — a blunter answer, but still the truth, and still bounded.
///
/// The two changes have to sit at opposite ends of the line for this to be the
/// ceiling's test rather than the prefix trim's: an edit in the middle of a
/// long line is trimmed down to a handful of tokens before the ceiling is ever
/// consulted, which is the whole point of trimming first. The shared head and
/// tail also have to be substantial, because a single band covering most of a
/// row is thrown away by the similarity gate — the fallback is blunter than
/// the full comparison, never louder than it.
#[test]
pub(crate) fn a_line_past_the_word_comparison_ceiling_still_marks_its_middle() {
    let run = |prefix: &str, count: usize| {
        (0..count)
            .map(|index| format!("{prefix}{index}"))
            .collect::<Vec<_>>()
            .join(" ")
    };
    let (head, tail) = (run("head", 100), run("tail", 100));
    let line =
        |filler: &str, first: &str, last: &str| format!("{head} {first} {filler} {last} {tail}");

    let over = run("token", DIFF_WORD_TOKEN_LIMIT);
    let marks = marked_words(&rewrite_diff(
        &[&line(&over, "old_first", "old_last")],
        &[&line(&over, "new_first", "new_last")],
    ));
    assert_eq!(marks.len(), 2);
    for (kind, words) in &marks {
        // One span, not two. Under the ceiling the comparison finds the shared
        // filler and marks only the two ends; over it the filler is swallowed
        // by the single span, which is the honest cheap answer.
        assert_eq!(words.len(), 1, "{kind:?} did not fall back to one span");
        assert!(words[0].contains("token0"), "{kind:?} lost the middle");
        // The shared head and tail stay outside the mark, so the reader still
        // learns where in the line the change is.
        assert!(!words[0].contains("head0"), "{kind:?} marked the head");
        assert!(!words[0].contains("tail0"), "{kind:?} marked the tail");
    }
    assert!(marks[0].1[0].starts_with("old_first"));
    assert!(marks[0].1[0].ends_with("old_last"));
    assert!(marks[1].1[0].starts_with("new_first"));
    assert!(marks[1].1[0].ends_with("new_last"));

    // The same shape under the ceiling takes the full comparison and marks the
    // two ends separately. Without this the assertions above would also pass
    // on a build that had no ceiling and no fallback at all.
    let under = run("token", DIFF_WORD_TOKEN_LIMIT / 4);
    let precise = marked_words(&rewrite_diff(
        &[&line(&under, "old_first", "old_last")],
        &[&line(&under, "new_first", "new_last")],
    ));
    assert_eq!(
        precise
            .iter()
            .map(|(_, words)| words.clone())
            .collect::<Vec<_>>(),
        vec![
            vec!["old_first".to_string(), "old_last".to_string()],
            vec!["new_first".to_string(), "new_last".to_string()],
        ]
    );
}

/// A comparison nobody paints is a comparison nobody has. This runs the whole
/// route — git's bytes, the parse, the pairing, the layout the pane hands to
/// egui — and asserts the band is on the changed word and on nothing else.
///
/// Lesson 005: the marks could be computed perfectly and dropped on the way to
/// the screen, and every other test in this file would still be green.
#[test]
pub(crate) fn a_marked_row_is_painted_with_its_emphasis_band() {
    let palette = AppTheme::Dark.palette();
    let files = parse_unified_diff(&rewrite_diff(
        &["let ready = false;"],
        &["let ready = true;"],
    ));
    let lines = files
        .iter()
        .flat_map(|file| &file.lines)
        .filter(|line| matches!(line.kind, DiffLineKind::Added | DiffLineKind::Removed))
        .collect::<Vec<_>>();
    assert_eq!(lines.len(), 2);

    for (line, word, expected) in [
        (lines[0], "false", palette.diff_removed_emphasis),
        (lines[1], "true", palette.diff_added_emphasis),
    ] {
        let job = diff_line_layout(line, 8.0, palette);
        let background_at = |needle: &str| {
            let at = job.text.find(needle).expect("the word is in the row");
            job.sections
                .iter()
                .find(|section| section.byte_range.start <= at && section.byte_range.end > at)
                .map(|section| section.format.background)
        };
        assert_eq!(background_at(word), Some(expected), "{word}");
        // Everything the two lines share is drawn on the row wash alone. The
        // band is what says "this part moved", so a band under `ready` would
        // be a lie about a word that did not.
        assert_eq!(
            background_at("ready"),
            Some(Color32::TRANSPARENT),
            "{word}: an unchanged word was banded"
        );
        // The whole line survives the split into banded and unbanded sections.
        assert!(job.text.ends_with(&line.text), "{word}: the row lost text");
    }

    // A context line has no marks, so it is laid out exactly as it was before
    // any of this existed: one section for the line, no band.
    let context = DiffLine {
        kind: DiffLineKind::Context,
        old_number: Some(1),
        new_number: Some(1),
        text: "let ready = false;".to_owned(),
        highlights: Vec::new(),
    };
    let job = diff_line_layout(&context, 8.0, palette);
    assert!(job
        .sections
        .iter()
        .all(|section| section.format.background == Color32::TRANSPARENT));
}

/// Draw the editor for real, without a window.
///
/// Everything else in this file is tested as a function, and a pane can be
/// made of correct functions and still panic the moment it is drawn — an
/// index taken from one frame's state and used against another's, a layout
/// that allocates a NaN, two widgets that end up with one egui id. egui
/// lays out perfectly well with no backend behind it, so the way to find
/// that is to lay the pane out.
///
/// Every view is drawn, twice: the second pass is where a widget that
/// depends on last frame's state gets to be wrong.
#[test]
pub(crate) fn the_editor_draws_every_view_without_a_window() {
    let root = std::env::temp_dir().join(format!("operon-editor-draw-{}", Uuid::new_v4()));
    fs::create_dir_all(root.join("docs")).unwrap();
    fs::write(
        root.join("docs/plan.md"),
        "# Plan\n\n- do the thing\n\n```rust\nlet x = 1;\n```\n\n| a | b |\n|---|---|\n| 1 | 2 |\n",
    )
    .unwrap();
    fs::write(root.join("main.rs"), "fn main() {\n    todo!()\n}\n").unwrap();
    fs::write(
        root.join("settings.json"),
        "{\n  \"agent\": \"codex\",\n  \"active\": true\n}\n",
    )
    .unwrap();

    let data_file = root.join("store.json");
    let mut app = test_app(data_file);
    let project = Project {
        id: Uuid::new_v4(),
        name: "draw".into(),
        path: root.clone(),
        added_at: now(),
    };
    app.store.projects.push(project.clone());
    app.select_project(Some(project.id));
    app.project_tab = ProjectTab::Files;

    // Open both files and let the reads land, so the panes have something
    // to draw rather than a spinner.
    app.open_document(&project, PathBuf::from("docs/plan.md"));
    app.open_document(&project, PathBuf::from("main.rs"));
    app.open_document(&project, PathBuf::from("settings.json"));
    for file in ["docs/plan.md", "main.rs", "settings.json"] {
        wait_for_background_task(
            &mut app,
            &BackgroundKey::FileOpen(project_document(&project, file)),
            Duration::from_secs(10),
        );
    }
    wait_for_background_task(
        &mut app,
        &BackgroundKey::Files(project.id),
        Duration::from_secs(10),
    );
    assert!(
        app.open_documents
            .iter()
            .all(|document| document.read_only.is_none()),
        "both files should have opened: {:?}",
        app.open_documents
    );
    // Something to fold and something to diff. The directory is expanded
    // so the recursive half of the tree is drawn too.
    app.expanded_directories
        .insert((project.id, PathBuf::from("docs")));
    app.diff_file_cache.insert(
        (project.id, Some("main.rs".to_owned())),
        parse_unified_diff(concat!(
            "diff --git a/main.rs b/main.rs\n",
            "index 1111111..2222222 100644\n",
            "--- a/main.rs\n",
            "+++ b/main.rs\n",
            "@@ -1,3 +1,3 @@\n",
            " fn main() {\n",
            "-    todo!()\n",
            "+    println!(\"hi\");\n",
            " }\n",
        )),
    );
    app.git_diff_cache
        .insert((project.id, Some("main.rs".to_owned())), Ok(String::new()));

    let context = egui::Context::default();
    for pass in 0..2 {
        for (view, path) in [
            (EditorView::Preview, "docs/plan.md"),
            (EditorView::Edit, "docs/plan.md"),
            (EditorView::Edit, "main.rs"),
            (EditorView::Edit, "settings.json"),
            (EditorView::Diff, "main.rs"),
        ] {
            app.editor_view = view;
            app.active_document = Some(project_document(&project, path));
            context.begin_pass(egui::RawInput::default());
            egui::CentralPanel::default().show(&context, |ui| {
                app.ui_files(ui, &project);
            });
            let output = context.end_pass();
            assert!(
                !output.shapes.is_empty(),
                "pass {pass}: {view:?} of {path} drew nothing"
            );
        }
        // The empty state, and the whole-project review pane beside it.
        app.active_document = None;
        app.editor_view = EditorView::Edit;
        context.begin_pass(egui::RawInput::default());
        egui::CentralPanel::default().show(&context, |ui| {
            app.ui_files(ui, &project);
            app.git_view = GitView::Diff;
            app.ui_git(ui, &project);
        });
        let _ = context.end_pass();
    }
    fs::remove_dir_all(root).unwrap();
}

/// The one thing this editor must never do. Agents in this app write to
/// the same working tree a person is reading, so a file changing under an
/// open tab is routine — and a save that won that race would delete an
/// agent's work with no message and no undo.
#[test]
pub(crate) fn a_save_refuses_to_overwrite_work_that_landed_after_the_file_was_opened() {
    let root = std::env::temp_dir().join(format!("operon-save-race-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("plan.md"), "# opened\n").unwrap();

    // The agent writes while the tab is open.
    fs::write(root.join("plan.md"), "# what the agent wrote\n").unwrap();

    let refused = save_project_file(
        &root,
        Path::new("plan.md"),
        "# opened\n",
        "# what the person typed\n",
    );
    assert!(refused.is_err());
    assert_eq!(
        fs::read_to_string(root.join("plan.md")).unwrap(),
        "# what the agent wrote\n",
        "the agent's bytes have to still be there"
    );

    // Having re-read it, the same save goes through.
    save_project_file(
        &root,
        Path::new("plan.md"),
        "# what the agent wrote\n",
        "# what the person typed\n",
    )
    .unwrap();
    assert_eq!(
        fs::read_to_string(root.join("plan.md")).unwrap(),
        "# what the person typed\n"
    );
    fs::remove_dir_all(root).unwrap();
}

/// A hook or a shell script that came back from the editor without its
/// executable bit would be a silent breakage, so the mode rides across the
/// atomic replacement — and the replacement leaves no temporary behind.
#[test]
pub(crate) fn saving_keeps_the_file_mode_and_cleans_up_after_itself() {
    let root = std::env::temp_dir().join(format!("operon-save-mode-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let script = root.join("hook.sh");
    fs::write(&script, "#!/bin/sh\necho before\n").unwrap();
    fs::set_permissions(&script, fs::Permissions::from_mode(0o755)).unwrap();

    save_project_file(
        &root,
        Path::new("hook.sh"),
        "#!/bin/sh\necho before\n",
        "#!/bin/sh\necho after\n",
    )
    .unwrap();

    assert_eq!(
        fs::metadata(&script).unwrap().permissions().mode() & 0o777,
        0o755
    );
    assert_eq!(
        fs::read_to_string(&script).unwrap(),
        "#!/bin/sh\necho after\n"
    );
    let leftovers = fs::read_dir(&root)
        .unwrap()
        .filter_map(|entry| entry.ok())
        .filter(|entry| entry.file_name().to_string_lossy().contains(".tmp-"))
        .count();
    assert_eq!(leftovers, 0);
    fs::remove_dir_all(root).unwrap();
}

/// Everything the editor reaches for goes through one containment check,
/// and a path that climbs out of the project does not get read or written.
#[test]
pub(crate) fn the_editor_cannot_reach_outside_the_project() {
    let root = std::env::temp_dir().join(format!("operon-escape-{}", Uuid::new_v4()));
    fs::create_dir_all(root.join("inside")).unwrap();
    fs::write(root.join("secret.txt"), "not yours\n").unwrap();
    let project = root.join("inside");

    assert!(read_file_for_editing(&project, Path::new("../secret.txt")).is_err());
    assert!(save_project_file(
        &project,
        Path::new("../secret.txt"),
        "not yours\n",
        "overwritten\n"
    )
    .is_err());
    assert_eq!(
        fs::read_to_string(root.join("secret.txt")).unwrap(),
        "not yours\n"
    );
    fs::remove_dir_all(root).unwrap();
}

/// The watch's whole job is to say nothing almost every time and something
/// exactly when the bytes moved. A rewrite with the same content is not a
/// change: agents rewrite files they did not really alter, and a warning raised
/// over that is a warning people learn to ignore.
#[test]
pub(crate) fn a_changed_file_is_reported_and_an_unchanged_one_is_not() {
    let root = std::env::temp_dir().join(format!("operon-watch-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let note = root.join("plan.md");
    fs::write(&note, "# Plan\n").unwrap();

    assert_eq!(
        read_file_for_editing_if_changed(&root, Path::new("plan.md"), "# Plan\n").unwrap(),
        None,
        "unchanged bytes are not a change"
    );
    // The same bytes written again, which is what a stamp would have called a
    // change and this deliberately does not.
    fs::write(&note, "# Plan\n").unwrap();
    assert_eq!(
        read_file_for_editing_if_changed(&root, Path::new("plan.md"), "# Plan\n").unwrap(),
        None,
        "a rewrite with the same content is not a change"
    );

    fs::write(&note, "# Plan\n\n- [x] done\n").unwrap();
    assert_eq!(
        read_file_for_editing_if_changed(&root, Path::new("plan.md"), "# Plan\n").unwrap(),
        Some(FileOpenOutcome::Text("# Plan\n\n- [x] done\n".into()))
    );
    // A file that became unopenable while it was open is a change too: it has
    // something to say that the buffer on screen does not.
    fs::write(&note, "x".repeat(EDITOR_FILE_MAX_BYTES + 1)).unwrap();
    assert!(matches!(
        read_file_for_editing_if_changed(&root, Path::new("plan.md"), "# Plan\n").unwrap(),
        Some(FileOpenOutcome::Unopenable(reason)) if reason.contains("KiB")
    ));
    fs::remove_dir_all(root).unwrap();
}

/// Open a document in a throwaway project and let the read land, so a watch
/// test starts from the state the editor is actually in.
fn app_with_open_document(name: &str, contents: &str) -> (OperonApp, Project, PathBuf) {
    let root = std::env::temp_dir().join(format!("operon-{name}-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("plan.md"), contents).unwrap();
    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: name.into(),
        path: root.clone(),
        added_at: now(),
    };
    app.store.projects.push(project.clone());
    app.select_project(Some(project.id));
    app.project_tab = ProjectTab::Files;
    app.open_document(&project, PathBuf::from("plan.md"));
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileOpen(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );
    (app, project, root)
}

/// With nothing typed there is nothing to lose, so the agent's write simply
/// becomes what the editor is showing — and says so, rather than a prompt whose
/// only sensible answer is yes.
#[test]
pub(crate) fn an_agents_write_reaches_an_unmodified_buffer_by_itself() {
    let (mut app, project, root) = app_with_open_document("adopt", "# Plan\n");
    assert_eq!(app.open_documents[0].buffer, "# Plan\n");

    fs::write(
        root.join("plan.md"),
        "# Plan\n\n- [x] エージェントが書いた\n",
    )
    .unwrap();
    app.watch_active_document(&project);
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileWatch(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );

    assert_eq!(
        app.open_documents[0].buffer,
        "# Plan\n\n- [x] エージェントが書いた\n"
    );
    assert_eq!(app.open_documents[0].disk, app.open_documents[0].buffer);
    assert!(
        !app.open_documents[0].external_change,
        "nothing was at stake, so nothing is raised"
    );
    assert!(
        app.notice
            .as_deref()
            .is_some_and(|notice| notice.contains("読み直しました")),
        "the reload is stated: {:?}",
        app.notice
    );
    fs::remove_dir_all(root).unwrap();
}

/// The invariant this whole change exists for: what a person typed is never the
/// thing a refresh throws away. The bar is raised instead, and both ways out of
/// it are theirs to take.
#[test]
pub(crate) fn an_agents_write_never_overwrites_what_a_person_typed() {
    let (mut app, project, root) = app_with_open_document("keep", "# Plan\n");
    app.open_documents[0].buffer = "# Plan\n\n人が書いた行\n".into();

    fs::write(root.join("plan.md"), "# Plan\n\nエージェントが書いた行\n").unwrap();
    app.watch_active_document(&project);
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileWatch(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );

    assert_eq!(
        app.open_documents[0].buffer, "# Plan\n\n人が書いた行\n",
        "the buffer is untouched"
    );
    assert_eq!(
        app.open_documents[0].disk, "# Plan\n",
        "and so is what the editor believes is on disk, which is what the save
         guard compares against"
    );
    assert!(app.open_documents[0].external_change);
    fs::remove_dir_all(root).unwrap();
}

/// The bar states one fact, so it goes away when that fact stops being true.
/// Reloading is the person deciding the agent's copy wins.
#[test]
pub(crate) fn the_bar_clears_when_the_document_is_reloaded() {
    let (mut app, project, root) = app_with_open_document("clear", "# Plan\n");
    app.open_documents[0].buffer = "# Plan\n\n人が書いた行\n".into();
    fs::write(root.join("plan.md"), "# Plan\n\nエージェントが書いた行\n").unwrap();
    app.watch_active_document(&project);
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileWatch(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );
    assert!(app.open_documents[0].external_change);

    app.reload_document(&project_document(&project, "plan.md"));
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileOpen(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );

    assert!(!app.open_documents[0].external_change);
    assert_eq!(
        app.open_documents[0].buffer,
        "# Plan\n\nエージェントが書いた行\n"
    );

    // And it stays clear: the next watch has nothing left to report.
    app.last_editor_file_watch = None;
    app.watch_active_document(&project);
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileWatch(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );
    assert!(!app.open_documents[0].external_change);
    fs::remove_dir_all(root).unwrap();
}

/// A watch's answer is only about the document that asked it. A reload or a
/// save landing while the read is in flight moves `disk`, and an answer that
/// compared the file against the bytes from before that would roll the document
/// back to a version nobody asked for — and announce it as an agent's write.
///
/// Both halves are the same defect, and both are what `known` closes: the
/// second is the reload rollback the review found, and the first is why ⌘S is
/// not followed by a notice claiming the file reloaded.
#[test]
pub(crate) fn a_watch_answer_about_an_older_document_is_dropped() {
    let (mut app, project, root) = app_with_open_document("stale", "# Plan\n");

    // The save landed first. The watch is still carrying an answer it worked
    // out against "# Plan\n", which is no longer what this document holds.
    app.open_documents[0].disk = "# Plan\n\n保存した行\n".into();
    app.open_documents[0].buffer = "# Plan\n\n保存した行\n".into();
    app.notice = None;
    app.apply_watched_file(
        &project_document(&project, "plan.md"),
        "# Plan\n",
        Ok(Some(FileOpenOutcome::Text("# Plan\n\n保存した行\n".into()))),
    );
    assert_eq!(app.notice, None, "nothing to say, so nothing is said");
    assert!(!app.open_documents[0].external_change);

    // The reload landed first, and brought version C. The watch answers with
    // version B, which it read before the reload was even asked for. Applying
    // it would put B on screen and call it fresh.
    app.open_documents[0].disk = "# Plan\n\nC\n".into();
    app.open_documents[0].buffer = "# Plan\n\nC\n".into();
    app.apply_watched_file(
        &project_document(&project, "plan.md"),
        "# Plan\n",
        Ok(Some(FileOpenOutcome::Text("# Plan\n\nB\n".into()))),
    );
    assert_eq!(
        app.open_documents[0].buffer, "# Plan\n\nC\n",
        "the reload the person asked for is not rolled back"
    );
    assert_eq!(app.notice, None);

    // And a read still in flight is the same fact one moment earlier: the
    // answer is dropped even though `known` still matches, because what it is
    // about is already being replaced.
    app.open_documents[0].disk = "# Plan\n".into();
    app.open_documents[0].buffer = "# Plan\n".into();
    app.background_tasks
        .insert(BackgroundKey::FileOpen(project_document(
            &project, "plan.md",
        )));
    app.apply_watched_file(
        &project_document(&project, "plan.md"),
        "# Plan\n",
        Ok(Some(FileOpenOutcome::Text("# Plan\n\nB\n".into()))),
    );
    assert_eq!(app.open_documents[0].buffer, "# Plan\n");
    assert_eq!(app.notice, None);
    fs::remove_dir_all(root).unwrap();
}

/// A failed save is a sentence addressed to the person. A reload answers it,
/// because a reload is the person deciding; a watch nobody asked for does not,
/// and must not take the sentence away before it has been read.
#[test]
pub(crate) fn a_watch_does_not_answer_a_failed_save_on_the_persons_behalf() {
    let (mut app, project, root) = app_with_open_document("unread", "# Plan\n");
    app.open_documents[0].save_error = Some("保存できませんでした: 権限がありません".into());

    // The person undid their edits, so there is nothing at stake and the write
    // is adopted — but the error is still unanswered.
    fs::write(root.join("plan.md"), "# Plan\n\nエージェントが書いた行\n").unwrap();
    app.watch_active_document(&project);
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileWatch(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );

    assert_eq!(
        app.open_documents[0].buffer,
        "# Plan\n\nエージェントが書いた行\n"
    );
    assert_eq!(
        app.open_documents[0].save_error.as_deref(),
        Some("保存できませんでした: 権限がありません"),
        "the failed save is still on screen"
    );

    // A reload is the person answering it, so it goes.
    app.reload_document(&project_document(&project, "plan.md"));
    wait_for_background_task(
        &mut app,
        &BackgroundKey::FileOpen(project_document(&project, "plan.md")),
        Duration::from_secs(10),
    );
    assert_eq!(app.open_documents[0].save_error, None);
    fs::remove_dir_all(root).unwrap();
}

/// A binary file and an oversized one are ordinary things to click on in a
/// project tree. Neither is an error; both say why they cannot be edited.
#[test]
pub(crate) fn a_file_the_editor_cannot_edit_says_so_instead_of_failing() {
    let root = std::env::temp_dir().join(format!("operon-unopenable-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("note.md"), "# hello\n").unwrap();
    fs::write(root.join("binary.bin"), [0x00, 0x01, 0x02, 0x03]).unwrap();
    fs::write(
        root.join("corrupt.png"),
        [0x89, b'P', b'N', b'G', 0x00, 0x1a],
    )
    .unwrap();
    fs::write(root.join("huge.log"), "x".repeat(EDITOR_FILE_MAX_BYTES + 1)).unwrap();

    assert_eq!(
        read_file_for_editing(&root, Path::new("note.md")).unwrap(),
        FileOpenOutcome::Text("# hello\n".into())
    );
    assert!(matches!(
        read_file_for_editing(&root, Path::new("binary.bin")).unwrap(),
        FileOpenOutcome::Unopenable(reason) if reason.contains("バイナリ")
    ));
    assert!(matches!(
        read_file_for_editing(&root, Path::new("corrupt.png")).unwrap(),
        FileOpenOutcome::Unopenable(reason) if reason.contains("デコード")
    ));
    assert!(matches!(
        read_file_for_editing(&root, Path::new("huge.log")).unwrap(),
        FileOpenOutcome::Unopenable(reason) if reason.contains("KiB")
    ));
    fs::remove_dir_all(root).unwrap();
}

/// The file tree and editor intentionally share their extension vocabulary:
/// every familiar project format receives the same code treatment in both
/// places, while an unknown suffix stays honestly plain.
#[test]
pub(crate) fn the_editor_classifies_common_project_text_formats() {
    for (name, language) in [
        ("README.md", EditorLanguage::Markdown),
        ("guide.markdown", EditorLanguage::Markdown),
        ("component.mdx", EditorLanguage::Markdown),
        ("main.rs", EditorLanguage::Rust),
        ("app.js", EditorLanguage::JavaScript),
        ("view.jsx", EditorLanguage::JavaScript),
        ("app.ts", EditorLanguage::TypeScript),
        ("view.tsx", EditorLanguage::TypeScript),
        ("tool.py", EditorLanguage::Python),
        ("server.go", EditorLanguage::Go),
        ("task.rb", EditorLanguage::Ruby),
        ("hook.sh", EditorLanguage::Shell),
        ("hook.bash", EditorLanguage::Shell),
        ("hook.zsh", EditorLanguage::Shell),
        ("main.c", EditorLanguage::C),
        ("header.h", EditorLanguage::Cpp),
        ("main.cpp", EditorLanguage::Cpp),
        ("header.hpp", EditorLanguage::Cpp),
        ("app.swift", EditorLanguage::Swift),
        ("app.kt", EditorLanguage::Kotlin),
        ("App.java", EditorLanguage::Java),
        ("app.cs", EditorLanguage::CSharp),
        ("app.m", EditorLanguage::ObjectiveC),
        ("app.php", EditorLanguage::Php),
        ("component.vue", EditorLanguage::Vue),
        ("query.sql", EditorLanguage::Sql),
        ("page.html", EditorLanguage::Html),
        ("feed.xml", EditorLanguage::Xml),
        ("style.css", EditorLanguage::Css),
        ("settings.json", EditorLanguage::Json),
        ("Cargo.toml", EditorLanguage::Toml),
        ("workflow.yaml", EditorLanguage::Yaml),
        ("workflow.yml", EditorLanguage::Yaml),
        ("settings.ini", EditorLanguage::Ini),
        ("Dockerfile", EditorLanguage::Dockerfile),
        ("Makefile", EditorLanguage::Makefile),
        ("tool.mjs", EditorLanguage::JavaScript),
        ("tool.mts", EditorLanguage::TypeScript),
        (".env.local", EditorLanguage::Shell),
        ("script.lua", EditorLanguage::Lua),
        ("notes.txt", EditorLanguage::Plain),
    ] {
        let path = Path::new(name);
        assert_eq!(editor_language(path), language, "{name}");
        assert_eq!(
            is_markdown(path),
            language == EditorLanguage::Markdown,
            "{name}"
        );
        assert_eq!(
            file_tree_icon(name) == ICON_FILE_CODE,
            !matches!(language, EditorLanguage::Markdown | EditorLanguage::Plain),
            "{name}"
        );
    }
}

/// Formatting never changes what a person edits. It only breaks the text into
/// coloured sections, for every supported family and for malformed input that
/// agents often leave while they are mid-write.
#[test]
pub(crate) fn syntax_layout_keeps_common_format_text_intact_and_coloured() {
    let palette = AppTheme::Dark.palette();
    for (language, source, expected_colours) in [
        (
            EditorLanguage::Rust,
            "pub fn run() { // comment\n    let value = \"ok\";\n}\n",
            vec![palette.accent_text, palette.text_muted, palette.success],
        ),
        (
            EditorLanguage::Json,
            "{\n  \"enabled\": true,\n  \"count\": 2\n}\n",
            vec![palette.info, palette.warning, palette.sand],
        ),
        (
            EditorLanguage::Yaml,
            "name: operon # local\nactive: true\n",
            vec![palette.text_muted, palette.warning],
        ),
        (
            EditorLanguage::Markdown,
            "# Plan\nUse `cargo test`.\n",
            vec![palette.accent_text, palette.success],
        ),
        (
            EditorLanguage::Html,
            "<main>hello</main>\n",
            vec![palette.info],
        ),
    ] {
        let layout = syntax_layout(source, language, palette);
        assert_eq!(layout.text, source, "{language:?}");
        let colours = layout
            .sections
            .iter()
            .map(|section| section.format.color)
            .collect::<Vec<_>>();
        for colour in expected_colours {
            assert!(colours.contains(&colour), "{language:?} missed {colour:?}");
        }
    }

    let plain = syntax_layout("{ surely: plain }\n", EditorLanguage::Plain, palette);
    assert_eq!(plain.text, "{ surely: plain }\n");
    assert!(plain
        .sections
        .iter()
        .all(|section| section.format.color == palette.text));

    let incomplete = syntax_layout("/* agent is still writing", EditorLanguage::Rust, palette);
    assert_eq!(incomplete.text, "/* agent is still writing");
    assert_eq!(
        incomplete
            .sections
            .last()
            .map(|section| section.format.color),
        Some(palette.text_muted)
    );
}

/// A multiline comment and an embedded script are ordinary HTML shapes, not
/// malformed edge cases. The highlighter must preserve their bytes while
/// carrying its grammar state across lines.
#[test]
pub(crate) fn syntax_layout_carries_markup_grammar_across_lines() {
    let palette = AppTheme::Dark.palette();
    let source = "<!-- agent is still writing\nits review note -->\n<script>\nconst ready = true;\n</script>\n";
    let layout = syntax_layout(source, EditorLanguage::Html, palette);
    assert_eq!(layout.text, source);

    let comment_offset = source.find("its review note").unwrap();
    let comment_colour = layout
        .sections
        .iter()
        .find(|section| {
            section.byte_range.start <= comment_offset && section.byte_range.end > comment_offset
        })
        .map(|section| section.format.color);
    assert_eq!(comment_colour, Some(palette.text_muted));

    let keyword_offset = source.find("const").unwrap();
    let keyword_colour = layout
        .sections
        .iter()
        .find(|section| {
            section.byte_range.start <= keyword_offset && section.byte_range.end > keyword_offset
        })
        .map(|section| section.format.color);
    assert_eq!(keyword_colour, Some(palette.accent_text));
}

/// Every extension the tree calls code has a concrete grammar path. A comment
/// is the smallest portable proof because it keeps its semantic role across
/// languages without inventing a valid program for each one.
#[test]
pub(crate) fn syntax_layout_covers_each_declared_language_family() {
    let palette = AppTheme::Dark.palette();
    let comment_cases = [
        (EditorLanguage::Rust, "// Rust\n"),
        (EditorLanguage::JavaScript, "// JavaScript\n"),
        (EditorLanguage::TypeScript, "// TypeScript\n"),
        (EditorLanguage::Python, "# Python\n"),
        (EditorLanguage::Go, "// Go\n"),
        (EditorLanguage::Ruby, "# Ruby\n"),
        (EditorLanguage::Shell, "# Shell\n"),
        (EditorLanguage::C, "// C\n"),
        (EditorLanguage::Cpp, "// C++\n"),
        (EditorLanguage::Swift, "// Swift\n"),
        (EditorLanguage::Kotlin, "// Kotlin\n"),
        (EditorLanguage::Java, "// Java\n"),
        (EditorLanguage::CSharp, "// C#\n"),
        (EditorLanguage::ObjectiveC, "// Objective-C\n"),
        (EditorLanguage::Php, "<?php // PHP\n?>\n"),
        (EditorLanguage::Vue, "<!-- Vue -->\n"),
        (EditorLanguage::Sql, "-- SQL\n"),
        (EditorLanguage::Html, "<!-- HTML -->\n"),
        (EditorLanguage::Xml, "<!-- XML -->\n"),
        (EditorLanguage::Css, "/* CSS */\n"),
        (EditorLanguage::Toml, "# TOML\n"),
        (EditorLanguage::Yaml, "# YAML\n"),
        (EditorLanguage::Ini, "# INI\n"),
        (EditorLanguage::Dockerfile, "# Dockerfile\n"),
        (EditorLanguage::Makefile, "# Makefile\n"),
        (EditorLanguage::Lua, "-- Lua\n"),
    ];
    for (language, source) in comment_cases {
        let layout = syntax_layout(source, language, palette);
        assert_eq!(layout.text, source, "{language:?}");
        assert!(
            layout
                .sections
                .iter()
                .any(|section| section.format.color == palette.text_muted),
            "{language:?} did not recognise its comment grammar"
        );
    }

    let json = syntax_layout("{\"enabled\": true}\n", EditorLanguage::Json, palette);
    assert!(json
        .sections
        .iter()
        .any(|section| section.format.color == palette.info));
    let markdown = syntax_layout("# Heading\n", EditorLanguage::Markdown, palette);
    assert!(markdown
        .sections
        .iter()
        .any(|section| section.format.color == palette.accent_text));
}

/// Egui may ask a TextEdit layouter once per frame. An unchanged document must
/// return its previous grammar and gutter layout; a changed buffer or palette
/// must build exactly one fresh result.
#[test]
pub(crate) fn editor_text_layout_cache_reuses_unchanged_document() {
    let mut cache = EditorTextLayoutCache::default();
    let dark = AppTheme::Dark.palette();
    let source = "const ready = true;\n";

    let first = cache
        .layout_for(source, EditorLanguage::JavaScript, dark)
        .syntax
        .text
        .clone();
    assert_eq!(first, source);
    assert_eq!(cache.builds(), 1);
    assert_eq!(
        cache
            .layout_for(source, EditorLanguage::JavaScript, dark)
            .line_numbers,
        "1"
    );
    assert_eq!(cache.builds(), 1, "unchanged text must reuse its layout");

    cache.layout_for("const ready = false;\n", EditorLanguage::JavaScript, dark);
    assert_eq!(cache.builds(), 2);
    cache.layout_for(
        "const ready = false;\n",
        EditorLanguage::JavaScript,
        AppTheme::Light.palette(),
    );
    assert_eq!(
        cache.builds(),
        3,
        "a palette change needs a new semantic layout"
    );
}

/// A second agent write may leave Git status exactly the same (` M file.rs`).
/// An open editor Diff is therefore discarded by the scheduled refresh itself,
/// before its replacement background request arrives.
#[test]
pub(crate) fn changed_working_tree_invalidates_an_open_editor_diff() {
    let project_id = Uuid::new_v4();
    let mut app = test_app(std::env::temp_dir().join(format!("operon-diff-fresh-{project_id}")));
    let file = Some("src/main.rs".to_owned());
    app.git_changes_cache.insert(
        project_id,
        Ok(GitChangesSnapshot {
            status: "## main\n M src/main.rs\n".into(),
            files: vec![ChangedFile {
                status: "M".into(),
                path: "src/main.rs".into(),
            }],
        }),
    );
    app.git_diff_cache
        .insert((project_id, file.clone()), Ok("old diff".into()));
    app.diff_file_cache
        .insert((project_id, file.clone()), Vec::new());

    app.editor_view = EditorView::Diff;
    app.open_documents.push(OpenDocument {
        project: project_id,
        root: PathBuf::from("/tmp/diff-project"),
        path: PathBuf::from("src/main.rs"),
        branch: None,
        project_rooted: true,
        disk: String::new(),
        buffer: String::new(),
        read_only: None,
        save_error: None,
        external_change: false,
        image_data: None,
    });
    app.active_document = Some(DocumentId {
        project: project_id,
        root: PathBuf::from("/tmp/diff-project"),
        path: PathBuf::from("src/main.rs"),
    });
    let refreshed_file = app.invalidate_open_editor_diff(project_id);

    assert_eq!(refreshed_file.as_deref(), Some("src/main.rs"));
    assert!(app.git_changes_cache.contains_key(&project_id));
    assert!(!app.git_diff_cache.contains_key(&(project_id, file.clone())));
    assert!(!app.diff_file_cache.contains_key(&(project_id, file)));
}

/// Git reports the same ` M` status before and after a second unstaged write.
/// The editor must nevertheless replace the old bytes with a new per-file Diff.
#[test]
pub(crate) fn editor_diff_refreshes_after_a_second_write_with_unchanged_git_status() {
    let root = std::env::temp_dir().join(format!("operon-editor-diff-fresh-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let git = |arguments: &[&str]| {
        assert!(git_command(&root)
            .args(arguments)
            .status()
            .unwrap()
            .success());
    };
    git(&["init"]);
    git(&["config", "user.email", "test@example.invalid"]);
    git(&["config", "user.name", "Operon test"]);
    fs::write(root.join("agent.rs"), "fn main() {}\n").unwrap();
    git(&["add", "agent.rs"]);
    git(&["commit", "-m", "initial"]);

    fs::write(
        root.join("agent.rs"),
        "fn main() { first_agent_write(); }\n",
    )
    .unwrap();
    let status_before = git_output(&root, &["status", "--short"]).unwrap();
    fs::write(
        root.join("agent.rs"),
        "fn main() { second_agent_write(); }\n",
    )
    .unwrap();
    let status_after = git_output(&root, &["status", "--short"]).unwrap();
    assert_eq!(
        status_before, status_after,
        "the status fingerprint is unchanged"
    );

    let project = Project {
        id: Uuid::new_v4(),
        name: "diff freshness".into(),
        path: root.clone(),
        added_at: now(),
    };
    let mut app = test_app(root.join("store.json"));
    app.editor_view = EditorView::Diff;
    show_document(&mut app, &project, "agent.rs");
    let key = (project.id, Some("agent.rs".to_owned()));
    app.git_diff_cache
        .insert(key.clone(), Ok("first_agent_write".into()));
    app.diff_file_cache.insert(key.clone(), Vec::new());

    app.refresh_editor_git_views(&project);
    assert!(!app.git_diff_cache.contains_key(&key));
    assert!(!app.diff_file_cache.contains_key(&key));
    wait_for_background_task(
        &mut app,
        &BackgroundKey::GitDiff(project.id, Some("agent.rs".into())),
        Duration::from_secs(10),
    );
    let refreshed = app.git_diff_cache.get(&key).unwrap().as_ref().unwrap();
    assert!(refreshed.contains("second_agent_write"));
    assert!(!refreshed.contains("first_agent_write"));
    fs::remove_dir_all(root).unwrap();
}

/// An older Git child can finish after an agent write invalidates its result.
/// Its generation must be discarded and must schedule the newer generation,
/// even though the task key prevented two children from running at once.
#[test]
pub(crate) fn stale_inflight_editor_diff_result_is_replaced_by_its_new_generation() {
    let root = std::env::temp_dir().join(format!("operon-diff-generation-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let git = |arguments: &[&str]| {
        assert!(git_command(&root)
            .args(arguments)
            .status()
            .unwrap()
            .success());
    };
    git(&["init"]);
    git(&["config", "user.email", "test@example.invalid"]);
    git(&["config", "user.name", "Operon test"]);
    fs::write(root.join("agent.rs"), "fn main() {}\n").unwrap();
    git(&["add", "agent.rs"]);
    git(&["commit", "-m", "initial"]);
    fs::write(
        root.join("agent.rs"),
        "fn main() { newest_generation_write(); }\n",
    )
    .unwrap();
    let project = Project {
        id: Uuid::new_v4(),
        name: "generation".into(),
        path: root.clone(),
        added_at: now(),
    };
    let file = Some("agent.rs".to_owned());
    let key = (project.id, file.clone());
    let mut app = test_app(root.join("store.json"));
    app.store.projects.push(project.clone());
    app.editor_view = EditorView::Diff;
    show_document(&mut app, &project, "agent.rs");
    app.background_tasks
        .insert(BackgroundKey::GitDiff(project.id, file.clone()));

    assert_eq!(app.invalidate_open_editor_diff(project.id), file);
    app.request_git_diff(&project, file.clone());
    assert!(app
        .background_tasks
        .contains(&BackgroundKey::GitDiff(project.id, file.clone())));

    app.background_sender
        .send(BackgroundResult::GitDiff {
            project_id: project.id,
            file: file.clone(),
            generation: 0,
            result: Ok("old agent output".into()),
        })
        .unwrap();
    app.process_background_results();

    assert!(!app.git_diff_cache.contains_key(&key));
    assert!(app
        .background_tasks
        .contains(&BackgroundKey::GitDiff(project.id, file.clone())));
    wait_for_background_task(
        &mut app,
        &BackgroundKey::GitDiff(project.id, file),
        Duration::from_secs(10),
    );
    let refreshed = app.git_diff_cache.get(&key).unwrap().as_ref().unwrap();
    assert!(refreshed.contains("newest_generation_write"));
    assert!(!refreshed.contains("old agent output"));
    fs::remove_dir_all(root).unwrap();
}

/// The flat scan folds back into the tree it came from, directories first
/// at every level — the order every file tree a person has used puts them
/// in, and not the byte order the paths arrive in.
#[test]
pub(crate) fn the_project_tree_puts_directories_before_files() {
    let tree = build_file_tree(&[
        PathBuf::from("README.md"),
        PathBuf::from("src/main.rs"),
        PathBuf::from("src/ui/panel.rs"),
        PathBuf::from("src/ui/theme.rs"),
        PathBuf::from("assets/icon.png"),
    ]);
    assert_eq!(
        tree.iter()
            .map(|node| node.name.as_str())
            .collect::<Vec<_>>(),
        ["assets", "src", "README.md"]
    );
    let source = tree.iter().find(|node| node.name == "src").unwrap();
    // `ui/` is a directory and `main.rs` a file, so `ui` leads even though
    // `main.rs` sorts before it.
    assert_eq!(
        source
            .children
            .iter()
            .map(|node| node.name.as_str())
            .collect::<Vec<_>>(),
        ["ui", "main.rs"]
    );
    assert_eq!(
        source.children[0].children[0].path,
        PathBuf::from("src/ui/panel.rs")
    );
    assert!(!source.children[1].is_directory());
}

/// The blocks an agent's notes are actually made of.
#[test]
pub(crate) fn markdown_renders_what_agents_write() {
    let blocks = parse_markdown(concat!(
        "# Plan\n",
        "\n",
        "Rewrite the parser.\n",
        "\n",
        "- first step\n",
        "  - nested step\n",
        "1. numbered\n",
        "\n",
        "この案は ~~却下~~ です。\n",
        "\n",
        "> a quote\n",
        "\n",
        "```rust\n",
        "# not a heading\n",
        "let x = 1;\n",
        "```\n",
        "\n",
        "| name | count |\n",
        "|------|-------|\n",
        "| a    | 1     |\n",
    ));
    assert_eq!(
        blocks[0],
        MarkdownBlock::Heading {
            level: 1,
            text: "Plan".into()
        }
    );
    assert_eq!(
        blocks[1],
        MarkdownBlock::Paragraph("Rewrite the parser.".into())
    );
    assert_eq!(
        blocks[2],
        MarkdownBlock::Bullet {
            depth: 0,
            marker: "•".into(),
            text: "first step".into(),
            task: None
        }
    );
    assert_eq!(
        blocks[3],
        MarkdownBlock::Bullet {
            depth: 1,
            marker: "•".into(),
            text: "nested step".into(),
            task: None
        }
    );
    assert_eq!(
        blocks[4],
        MarkdownBlock::Bullet {
            depth: 0,
            marker: "1.".into(),
            text: "numbered".into(),
            task: None
        }
    );
    // Struck-out text is a run inside a paragraph, not a block of its own.
    assert_eq!(
        blocks[5],
        MarkdownBlock::Paragraph("この案は ~~却下~~ です。".into())
    );
    assert_eq!(
        parse_markdown_spans("この案は ~~却下~~ です。"),
        vec![
            MarkdownSpan::Text("この案は ".into()),
            MarkdownSpan::Strike("却下".into()),
            MarkdownSpan::Text(" です。".into()),
        ]
    );
    assert_eq!(blocks[6], MarkdownBlock::Quote("a quote".into()));
    // A `#` inside a fence is a shell comment, and stays one.
    assert_eq!(
        blocks[7],
        MarkdownBlock::Code {
            language: "rust".into(),
            lines: vec!["# not a heading".into(), "let x = 1;".into()]
        }
    );
    assert_eq!(
        blocks[8],
        MarkdownBlock::Table {
            header: vec!["name".into(), "count".into()],
            rows: vec![vec!["a".into(), "1".into()]]
        }
    );
}

/// A plan is a list of steps and a review is a list of findings, so a checklist
/// is the shape an agent's document actually arrives in. The brackets come off
/// the text and become a box; anything that is not exactly a box stays the text
/// it was, because `[z] pick one` is a list item and `see [x](url)` is a link.
#[test]
pub(crate) fn a_checklist_renders_as_checkboxes() {
    let blocks = parse_markdown(concat!(
        "- [ ] 移行を書く\n",
        "- [x] スキーマを読む\n",
        "- [X] 大文字も同じ\n",
        "- [z] pick one\n",
        "- [x]\n",
        "- ordinary\n",
    ));
    let task_of = |index: usize| match &blocks[index] {
        MarkdownBlock::Bullet { task, text, .. } => (*task, text.clone()),
        other => panic!("block {index} should be a bullet: {other:?}"),
    };
    assert_eq!(task_of(0), (Some(false), "移行を書く".to_owned()));
    assert_eq!(task_of(1), (Some(true), "スキーマを読む".to_owned()));
    assert_eq!(task_of(2), (Some(true), "大文字も同じ".to_owned()));
    // Not a box. The brackets stay in the text rather than being eaten.
    assert_eq!(task_of(3), (None, "[z] pick one".to_owned()));
    // An agent writing a checklist a line at a time produces this every time.
    assert_eq!(task_of(4), (Some(true), String::new()));
    assert_eq!(task_of(5), (None, "ordinary".to_owned()));
    // A bracket inside a line is content, not a box: only the head counts.
    assert_eq!(split_task_marker("see [x](url)"), (None, "see [x](url)"));

    // An ordered checklist is both numbered and ticked, and the number is half
    // of what the reader is counting with. The marker survives the box.
    let ordered = parse_markdown("1. [x] スキーマを読む\n");
    assert_eq!(
        ordered[0],
        MarkdownBlock::Bullet {
            depth: 0,
            marker: "1.".into(),
            text: "スキーマを読む".into(),
            task: Some(true)
        }
    );
}

/// A fence carries a word and the project tree classifies by extension, so
/// `fence_language` has to bridge the two — and has to land on `Plain` for
/// everything it does not know, because `Plain` is what `syntax_layout` reads
/// as "leave this alone".
#[test]
pub(crate) fn a_fence_is_coloured_by_the_language_it_names() {
    assert_eq!(fence_language("rust"), EditorLanguage::Rust);
    // The words that are not also extensions, and the extensions that are not
    // also words, both have to arrive at the same place.
    assert_eq!(fence_language("rs"), EditorLanguage::Rust);
    assert_eq!(fence_language("python"), EditorLanguage::Python);
    assert_eq!(fence_language("py"), EditorLanguage::Python);
    assert_eq!(fence_language("bash"), EditorLanguage::Shell);
    assert_eq!(fence_language("console"), EditorLanguage::Shell);
    assert_eq!(fence_language("yml"), EditorLanguage::Yaml);
    assert_eq!(fence_language("c#"), EditorLanguage::CSharp);
    assert_eq!(fence_language("dockerfile"), EditorLanguage::Dockerfile);
    // Only the first word: a fence may carry attributes after its language.
    assert_eq!(fence_language("rust,ignore"), EditorLanguage::Rust);
    assert_eq!(fence_language("python title=\"x\""), EditorLanguage::Python);
    // The two that must not be coloured.
    assert_eq!(fence_language(""), EditorLanguage::Plain);
    assert_eq!(fence_language("output"), EditorLanguage::Plain);

    let palette = AppTheme::Dark.palette();
    let mut cache = MarkdownPreviewCache::default();
    let document = cache.document_for(
        "```rust\nlet x = 1;\n```\n\n```\nplain\n```\n\n```output\nplain\n```\n",
        palette,
    );
    assert_eq!(document.blocks.len(), 3);
    let runs = |index: usize| match &document.blocks[index] {
        RenderedBlock::Code { job, .. } => job.sections.len(),
        other => panic!(
            "block {index} should be a fence: {:?}",
            std::mem::discriminant(other)
        ),
    };
    assert!(
        runs(0) > 1,
        "a coloured fence is more than one run: {}",
        runs(0)
    );
    // Plain is one run for the whole body — the monospace an unlabelled fence
    // had before any of this existed.
    assert_eq!(runs(1), 1, "a bare fence stays plain");
    assert_eq!(runs(2), 1, "a fence naming nothing known stays plain");
}

/// The rendered view is the default for Markdown, so before this cache the pane
/// a person spends the most time in was re-parsing and re-highlighting the
/// whole document sixty times a second. The cache key is the thing to check,
/// not the parser.
#[test]
pub(crate) fn a_rendered_document_is_built_once_however_many_frames_read_it() {
    let palette = AppTheme::Dark.palette();
    let mut cache = MarkdownPreviewCache::default();
    let text = "# Plan\n\n- [ ] step\n\n```rust\nlet x = 1;\n```\n";

    cache.document_for(text, palette);
    cache.document_for(text, palette);
    cache.document_for(text, palette);
    assert_eq!(cache.builds(), 1, "an unchanged frame builds nothing");

    cache.document_for("# Plan\n\n- [x] step\n", palette);
    assert_eq!(cache.builds(), 2, "changed text rebuilds");

    // "builds nothing" has to mean the whole parse, not just the block half.
    // The inline runs used to be found again on every frame, for every heading,
    // paragraph, bullet, quote, and table cell — the claim was in spec.md and
    // the counter above could not see it. So the runs are in the cache, and
    // this is what says so.
    let document = cache.document_for(
        "# **Plan**\n\nsee `x` and **y**\n\n- [ ] a *step*\n\n> a ~~quote~~\n\n| a | b |\n|---|---|\n| `c` | **d** |\n",
        palette,
    );
    let runs = |block: &RenderedBlock| match block {
        RenderedBlock::Heading { spans, .. }
        | RenderedBlock::Paragraph(spans)
        | RenderedBlock::Bullet { spans, .. }
        | RenderedBlock::Quote(spans) => spans.len(),
        RenderedBlock::Table { rows, .. } => rows.iter().flatten().map(Vec::len).sum(),
        _ => 0,
    };
    assert!(
        document.blocks.iter().all(|block| runs(block) > 0),
        "every text-bearing block arrives with its runs already found"
    );
    assert_eq!(
        document.blocks.iter().map(runs).sum::<usize>(),
        1 + 4 + 2 + 2 + 2,
        "and they are the runs the markers imply, not one run per block"
    );

    // The theme decides every ink in the fence, so it is part of the key.
    cache.document_for("# Plan\n\n- [x] step\n", AppTheme::Light.palette());
    assert_eq!(cache.builds(), 4, "a changed theme rebuilds");
}

/// An inline marker only counts where it closes. Agents write prose about
/// code, and prose about code is full of lone asterisks and backticks.
#[test]
pub(crate) fn markdown_spans_only_count_where_they_close() {
    assert_eq!(
        parse_markdown_spans("run `cargo test` on **main**"),
        vec![
            MarkdownSpan::Text("run ".into()),
            MarkdownSpan::Code("cargo test".into()),
            MarkdownSpan::Text(" on ".into()),
            MarkdownSpan::Strong("main".into()),
        ]
    );
    assert_eq!(
        parse_markdown_spans("a lone * and a lone ` stay put"),
        vec![MarkdownSpan::Text("a lone * and a lone ` stay put".into())]
    );
    assert_eq!(
        parse_markdown_spans("see [the docs](https://example.com/x)"),
        vec![
            MarkdownSpan::Text("see ".into()),
            MarkdownSpan::Link {
                text: "the docs".into(),
                url: "https://example.com/x".into()
            },
        ]
    );
    // `#tag` is a word. A heading has a space after its hashes.
    assert_eq!(parse_atx_heading("#tag"), None);
    assert_eq!(parse_atx_heading("## Why ##"), Some((2, "Why".to_owned())));
}

/// A hunk header numbers both sides, and a one-line hunk writes its range
/// without a comma.
#[test]
pub(crate) fn hunk_headers_number_both_sides() {
    assert_eq!(parse_hunk_header("@@ -12,7 +40,9 @@"), Some((12, 40)));
    assert_eq!(
        parse_hunk_header("@@ -1 +1 @@ fn parse(&self)"),
        Some((1, 1))
    );
    // A merge conflict's combined diff numbers three sides at once, which
    // this parser does not claim to understand.
    assert_eq!(parse_hunk_header("@@@ -1,2 -1,2 +1,3 @@@"), None);
}

#[test]
pub(crate) fn git_diff_enforces_one_capture_budget_for_large_tracked_and_untracked_content() {
    let root = std::env::temp_dir().join(format!("operon-git-cap-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    for arguments in [
        vec!["init"],
        vec!["config", "user.email", "test@example.invalid"],
        vec!["config", "user.name", "Operon test"],
    ] {
        assert!(git_command(&root)
            .args(arguments)
            .status()
            .unwrap()
            .success());
    }
    fs::write(root.join("tracked.txt"), "base\n").unwrap();
    assert!(git_command(&root)
        .args(["add", "tracked.txt"])
        .status()
        .unwrap()
        .success());
    assert!(git_command(&root)
        .args(["commit", "-m", "initial"])
        .status()
        .unwrap()
        .success());

    let large_line = format!("{}\n", "x".repeat(GIT_DIFF_MAX_BYTES * 2));
    fs::write(root.join("tracked.txt"), &large_line).unwrap();
    let tracked = git_working_tree_diff(&root, None).unwrap();
    assert!(tracked.contains("差分を"));
    assert!(tracked.len() <= GIT_DIFF_MAX_BYTES + 64);

    assert!(git_command(&root)
        .args(["restore", "tracked.txt"])
        .status()
        .unwrap()
        .success());
    fs::write(root.join("untracked.txt"), large_line).unwrap();
    let untracked = git_working_tree_diff(&root, None).unwrap();
    assert!(untracked.contains("差分を"));
    assert!(untracked.len() <= GIT_DIFF_MAX_BYTES + 64);
    fs::remove_dir_all(root).unwrap();
}
