/// A restored conversation has to be recognisable in a list of restored
/// conversations, so its title carries the work rather than the mechanism.
#[test]
pub(crate) fn names_a_restored_session_after_its_conversation() {
    let source = CliSession {
        provider: CliProvider::Codex,
        native_id: "0199aa11-bbbb-cccc-dddd-eeeeffff0000".into(),
        id: "0199aa11-bbbb-cccc-dddd-eeeeffff0000".into(),
        title: Some("0199aa11-bbbb-cccc-dddd-eeeeffff0000".into()),
        last_user_message: Some(
            "# ログイン画面の不具合を調べて直して\n関連するテストも実行して".into(),
        ),
        branch: None,
        updated_at: 0,
        path: PathBuf::from("/tmp/operon-restore-name.jsonl"),
    };
    assert_eq!(
        restored_session_name(&source),
        "ログイン画面の不具合を調べて直して"
    );

    // A conversation ID is an identifier, not a name: falling back to it
    // would only repeat what the card already shows.
    let untitled = CliSession {
        title: Some("0199aa11-bbbb-cccc-dddd-eeeeffff0000".into()),
        last_user_message: None,
        ..source.clone()
    };
    assert_eq!(
        restored_session_name(&untitled),
        "Codex CLI から引き継いだ会話"
    );

    let long = CliSession {
        last_user_message: Some("あ".repeat(80)),
        ..source
    };
    assert_eq!(
        restored_session_name(&long),
        format!("{}…", "あ".repeat(SESSION_TOPIC_NAME_MAX_CHARS))
    );

    assert_eq!(
        plain_terminal_name(Path::new("/Users/someone/dev/operon")),
        "operon のターミナル"
    );
}

/// Records saved before titles carried the work cannot be rewritten — the
/// name is the user's own data — so they are read rather than displayed
/// verbatim: the request becomes the title, and the mechanism is dropped.
#[test]
pub(crate) fn shortens_legacy_mechanism_names_into_a_title() {
    let mut restored = test_session(Uuid::new_v4(), SessionStatus::Active);
    restored.name = "Antigravity で会話全履歴を復元（Codex CLI から）".into();
    restored.goal = "ping".into();
    restored.agent = "gemini".into();
    assert_eq!(session_title(&restored), "ping");

    // Without a request to quote, the stand-in still has to be shorter than
    // the sentence it replaces and specific to this session.
    let bare = Session {
        goal: String::new(),
        ..restored.clone()
    };
    assert_eq!(session_title(&bare), "Codex から復元");

    let legacy_handoff = Session {
        name: "Handoff: Claude Code → Codex CLI".into(),
        goal: String::new(),
        agent: "codex".into(),
        ..restored.clone()
    };
    assert_eq!(session_title(&legacy_handoff), "Claude から復元");

    let untitled = Session {
        name: "Untitled gemini session".into(),
        goal: String::new(),
        ..restored.clone()
    };
    assert_eq!(session_title(&untitled), "Antigravity のセッション");

    // A name someone chose is never rewritten.
    let named = Session {
        name: "ログイン不具合の調査".into(),
        ..restored
    };
    assert_eq!(session_title(&named), "ログイン不具合の調査");
}

/// The list has to separate "still thinking" from "waiting on you": both
/// are a running tmux session, and only one of them needs an answer.
#[test]
pub(crate) fn reports_what_a_session_is_actually_doing() {
    let session = test_session(Uuid::new_v4(), SessionStatus::Active);
    let sessions = vec![session.clone()];
    let working = session_status_view(&sessions, &session, false, Some(AgentActivity::Working));
    // The kind, not the word: four words name fourteen states (change 090),
    // and the distinction this test guards is the state's.
    assert_eq!(working.kind, SessionStatusKind::Working);
    let awaiting = session_status_view(
        &sessions,
        &session,
        false,
        Some(AgentActivity::AwaitingInput),
    );
    assert_eq!(awaiting.kind, SessionStatusKind::Waiting);
    assert!(awaiting.hint.contains("ターミナルを開いて"));
    assert_ne!(working.tone, awaiting.tone);
    // A stop that has been asked for outranks whatever the screen shows.
    assert_eq!(
        session_status_view(&sessions, &session, true, Some(AgentActivity::Working)).kind,
        SessionStatusKind::Stopping
    );

    let parent = test_session(Uuid::new_v4(), SessionStatus::Failed);
    let mut blocked = test_session(Uuid::new_v4(), SessionStatus::Queued);
    blocked.depends_on = vec![parent.id];
    let queued = vec![parent, blocked.clone()];
    let blocked_view = session_status_view(&queued, &blocked, false, None);
    assert_eq!(blocked_view.kind, SessionStatusKind::Blocked);
    assert!(blocked_view.hint.contains("test"));
}

/// Renaming is a store write, so it has to survive a restart — and an empty
/// name must not leave a session nobody can identify.
#[test]
pub(crate) fn renaming_a_session_is_durable() {
    let root = std::env::temp_dir().join(format!("operon-rename-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let data_file = root.join("store.json");
    let session_id = Uuid::new_v4();
    let mut app = OperonApp::from_state(
        data_file.clone(),
        Store {
            sessions: vec![test_session(session_id, SessionStatus::Exited)],
            ..Store::default()
        },
        ToolStatus::default(),
        None,
    );
    let session = app.store.sessions[0].clone();
    app.begin_session_rename(&session);
    assert_eq!(app.rename_input, "test");
    app.rename_input = "  ログイン不具合の調査  ".into();
    app.commit_session_rename();
    assert_eq!(app.store.sessions[0].name, "ログイン不具合の調査");
    assert!(app.renaming_session.is_none());

    app.begin_session_rename(&app.store.sessions[0].clone());
    app.rename_input = "   ".into();
    app.commit_session_rename();
    assert_eq!(app.store.sessions[0].name, "ログイン不具合の調査");
    assert!(app
        .notice
        .as_deref()
        .is_some_and(|notice| notice.contains("空にできません")));

    let restarted = OperonApp::from_state(
        data_file.clone(),
        load_store(&data_file).unwrap(),
        ToolStatus::default(),
        None,
    );
    assert_eq!(restarted.store.sessions[0].name, "ログイン不具合の調査");
    fs::remove_dir_all(root).unwrap();
}

