pub(crate) fn retry_state_matrix_refuses_unsafe_terminals_and_cleans_only_dead_ones() {
    let cases = [
        (TmuxState::Alive, RetryTmuxAction::RefuseAlive),
        (TmuxState::Dead, RetryTmuxAction::RemoveDead),
        (TmuxState::Gone, RetryTmuxAction::Ready),
        (TmuxState::Unknown, RetryTmuxAction::RefuseUnknown),
    ];
    for (state, expected) in cases {
        assert_eq!(
            retry_tmux_action(TmuxObservation {
                state,
                exit_status: None,
            }),
            expected
        );
    }
    for status in [
        SessionStatus::Starting,
        SessionStatus::Active,
        SessionStatus::Queued,
        SessionStatus::Exited,
        SessionStatus::Cancelled,
        SessionStatus::Unknown,
    ] {
        assert!(!can_retry_session(&status));
    }
    assert!(can_retry_session(&SessionStatus::Failed));
}
