/// Only an exit status the app actually read may be called a failure.
///
/// A reboot takes the tmux server with it and every session it was holding
/// disappears at once. None of those failed — the app never saw how they
/// ended — and stamping them red turns a record into an accusation, on a
/// list where the only visible outcome is then "FAILED" with a `DONE` count of
/// zero.
#[test]
pub(crate) fn a_vanished_terminal_is_recorded_as_unresolved_rather_than_failed() {
    let unresolved = [
        TmuxObservation {
            state: TmuxState::Gone,
            exit_status: None,
        },
        TmuxObservation {
            state: TmuxState::Dead,
            exit_status: None,
        },
    ];
    for observation in unresolved {
        for current in [
            SessionStatus::Starting,
            SessionStatus::Active,
            SessionStatus::Unknown,
        ] {
            assert_eq!(
                session_status_after_observation(&current, observation),
                Some(SessionStatus::Lost),
                "{current:?} + {observation:?}"
            );
        }
    }
    assert!(can_retry_session(&SessionStatus::Lost));
    // A state that has already settled is never re-judged, however the
    // terminal behind it looks now.
    for settled in [
        SessionStatus::Exited,
        SessionStatus::Failed,
        SessionStatus::Cancelled,
        SessionStatus::Lost,
        SessionStatus::Queued,
    ] {
        for observation in unresolved {
            assert_eq!(
                session_status_after_observation(&settled, observation),
                None,
                "{settled:?}"
            );
        }
    }
    // An observation that says nothing changes nothing, and a session
    // already known to be running is not re-announced as running.
    for current in [SessionStatus::Starting, SessionStatus::Active] {
        assert_eq!(
            session_status_after_observation(
                &current,
                TmuxObservation {
                    state: TmuxState::Unknown,
                    exit_status: None,
                }
            ),
            None
        );
    }
    assert_eq!(
        session_status_after_observation(
            &SessionStatus::Active,
            TmuxObservation {
                state: TmuxState::Alive,
                exit_status: None,
            }
        ),
        None
    );
}
/// The rows already on a person's screen are the reason this bug was
/// noticed, so the fix has to reach them too — a verdict the app can no
/// longer support is not made true by having been written down.
#[test]
pub(crate) fn failures_recorded_before_the_evidence_rule_are_re_judged_once() {
    let root = std::env::temp_dir().join(format!("operon-refailure-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let legacy = Store {
        schema_version: EVIDENCE_BASED_FAILURE_SCHEMA_VERSION - 1,
        sessions: vec![
            test_session(Uuid::new_v4(), SessionStatus::Failed),
            test_session(Uuid::new_v4(), SessionStatus::Exited),
            test_session(Uuid::new_v4(), SessionStatus::Cancelled),
        ],
        ..Store::default()
    };
    let with_tmux = ToolStatus {
        tmux: true,
        ..ToolStatus::default()
    };
    let app = OperonApp::from_state(
        root.join("store.json"),
        legacy.clone(),
        with_tmux.clone(),
        None,
    );
    let statuses = |app: &OperonApp| {
        app.store
            .sessions
            .iter()
            .map(|session| session.status.clone())
            .collect::<Vec<_>>()
    };
    assert_eq!(
        statuses(&app),
        vec![
            // Pollable again, so tmux decides rather than the old build.
            SessionStatus::Unknown,
            SessionStatus::Exited,
            SessionStatus::Cancelled,
        ]
    );

    // Without tmux nothing would ever answer the question, and a permanent
    // "状態を確認中" is worse than the wrong answer it replaced.
    assert_eq!(
        statuses(&OperonApp::from_state(
            root.join("store.json"),
            legacy.clone(),
            ToolStatus::default(),
            None,
        ))[0],
        SessionStatus::Failed
    );

    // Once, not on every launch: a failure this build recorded from a real
    // exit status stays a failure.
    let current = Store {
        schema_version: EVIDENCE_BASED_FAILURE_SCHEMA_VERSION,
        ..legacy
    };
    assert_eq!(
        statuses(&OperonApp::from_state(
            root.join("store.json"),
            current,
            with_tmux,
            None,
        ))[0],
        SessionStatus::Failed
    );
    fs::remove_dir_all(root).unwrap();
}
