/// Sdlc 098. The suite drives real tmux, and it used to drive the person's:
/// every session a test made landed on the default server (or the one `$TMUX`
/// names), an interrupted test left it there for Operon's recovery screen, and
/// with no server running a test started the default one — so a person's
/// sessions then lived on a server a test had made. `tmux_command` puts the
/// suite on a server of its own; this holds that nothing reaches tmux beside it.
#[test]
pub(crate) fn every_tmux_the_crate_runs_goes_through_tmux_command() {
    // The two ways this crate starts a program by name, each spelled in two
    // halves so this test is not one of its own findings.
    let spawns = [
        concat!("Command::new(", "\"tmux\""),
        concat!("command_output_in_dir(", "\"tmux\""),
    ];
    // Whitespace out, because rustfmt breaks a long call after its `(` and a
    // per-line match then reads the call and `"tmux",` apart — which is how the
    // first version of this test missed one.
    let found: Vec<String> = source_files()
        .into_iter()
        .flat_map(|(path, text)| {
            let code: String = text
                .lines()
                .filter(|line| !line.trim_start().starts_with("//"))
                .flat_map(|line| line.chars().filter(|c| !c.is_whitespace()))
                .collect();
            spawns
                .iter()
                .flat_map(|spawn| code.matches(spawn))
                .map(|_| path.display().to_string())
                .collect::<Vec<_>>()
        })
        .collect();
    assert!(
        found.len() == 1 && found[0].ends_with("src/tmux.rs"),
        "tmux_command を通らずに tmux を起動している箇所があります: {found:#?}"
    );
}
/// The same promise from the other side: a session a test starts is on the
/// suite's server, and the server a bare `tmux` reaches has never heard of it.
#[test]
pub(crate) fn a_session_a_test_starts_is_not_on_the_persons_tmux_server() {
    if !tool_available("tmux") {
        return;
    }
    let name = format!("operon-test-{}", Uuid::new_v4().simple());
    start_empty_tmux_session(&name, Path::new("/tmp"), &[]).unwrap();
    let on_suite_server = tmux_state(&name);
    // The one deliberate tmux outside `tmux_command`: through `sh`, so the
    // guard above does not count it, and asking what a person's shell reaches.
    let on_default_server = Command::new("/bin/sh")
        .args(["-c", "tmux has-session -t \"=$1\" 2>/dev/null", "sh", &name])
        .status()
        .unwrap()
        .success();
    kill_tmux_session(&name);
    assert_eq!(on_suite_server, TmuxState::Alive);
    assert!(
        !on_default_server,
        "テストが作った tmux セッションが既定のサーバーにあります"
    );
}
