pub(crate) fn starts_an_agent_command_in_a_retainable_tmux_session() {
    if !tool_available("tmux") {
        return;
    }
    let name = format!("operon-test-{}", Uuid::new_v4().simple());
    start_tmux_agent_session(&name, Path::new("/tmp"), "/bin/echo operon-smoke-test", &[]).unwrap();
    let mut output = String::new();
    let mut state = TmuxState::Unknown;
    for _ in 0..20 {
        std::thread::sleep(Duration::from_millis(50));
        output = tmux_capture(&name).unwrap_or_default();
        state = tmux_state(&name);
        if output.contains("operon-smoke-test") && state == TmuxState::Dead {
            break;
        }
    }
    let _ = tmux_command().args(["kill-session", "-t", &name]).output();
    assert_eq!(state, TmuxState::Dead);
    assert!(output.contains("operon-smoke-test"));
}
/// The screen read must come from the live pane, not its scrollback: a real
/// session scrolls its finished turns up and would otherwise keep reporting
/// the interrupt hint printed minutes ago.
#[test]
pub(crate) fn reads_run_state_from_the_live_pane_rather_than_its_scrollback() {
    if !tool_available("tmux") {
        return;
    }
    let name = format!("operon-test-{}", Uuid::new_v4().simple());
    // Print the hint, then push it off the visible screen with enough
    // output to fill the pane — exactly what a finished turn does.
    start_tmux_agent_session(
        &name,
        Path::new("/tmp"),
        "/bin/sh -c 'echo \"• Working (3s • esc to interrupt)\"; sleep 15; yes \"scrolled output\" | head -80; sleep 30'",
        &[],
    )
    .unwrap();
    let mut working = AgentActivity::Idle;
    for _ in 0..280 {
        std::thread::sleep(Duration::from_millis(50));
        working = detect_agent_activity(&tmux_capture_screen(&name).unwrap_or_default());
        if working == AgentActivity::Working {
            break;
        }
    }
    let mut scrolled = AgentActivity::Working;
    for _ in 0..280 {
        std::thread::sleep(Duration::from_millis(50));
        scrolled = detect_agent_activity(&tmux_capture_screen(&name).unwrap_or_default());
        if scrolled == AgentActivity::Idle {
            break;
        }
    }
    let _ = tmux_command().args(["kill-session", "-t", &name]).output();
    assert_eq!(working, AgentActivity::Working);
    assert_eq!(scrolled, AgentActivity::Idle);
}
