#[test]
pub(crate) fn packaging_lock_rejects_a_concurrent_transaction_before_building() {
    use std::os::unix::fs::MetadataExt;

    let root = std::env::temp_dir().join(format!("operon-package-lock-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let lock = root.join(".operon-package.lockfile");
    let ready = root.join("ready");
    let mut holder = Command::new("/usr/bin/lockf")
        .args(["-t", "0", "-k"])
        .arg(&lock)
        .arg("/bin/sh")
        .args(["-c", "touch \"$1\"; sleep 120", "operon-lock-holder"])
        .arg(&ready)
        .spawn()
        .unwrap();
    for _ in 0..CHECKPOINT_POLLS {
        if ready.exists() {
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }
    assert!(ready.exists());
    // A `cargo` that only fails: since 096 the packager runs `cargo test`, and
    // with the real one a lock that stopped refusing would run this suite, and
    // this test, again without end instead of going red.
    let fake_bin = root.join("fake-bin");
    fs::create_dir_all(&fake_bin).unwrap();
    let fake_cargo = fake_bin.join("cargo");
    fs::write(&fake_cargo, "#!/bin/sh\nexit 42\n").unwrap();
    let mut permissions = fs::metadata(&fake_cargo).unwrap().permissions();
    std::os::unix::fs::PermissionsExt::set_mode(&mut permissions, 0o755);
    fs::set_permissions(&fake_cargo, permissions).unwrap();
    let output = Command::new("bash")
        .arg("scripts/package-macos.sh")
        .env("OPERON_DIST_DIR", &root)
        .env(
            "PATH",
            format!(
                "{}:{}",
                fake_bin.display(),
                std::env::var("PATH").unwrap_or_default()
            ),
        )
        .output()
        .unwrap();
    assert!(!output.status.success());
    assert!(String::from_utf8_lossy(&output.stderr).contains("already running"));
    let inode = fs::metadata(&lock).unwrap().ino();
    let _ = holder.kill();
    let _ = holder.wait();
    let reacquired = Command::new("/usr/bin/lockf")
        .args(["-t", "0", "-k"])
        .arg(&lock)
        .arg("/usr/bin/true")
        .status()
        .unwrap();
    assert!(reacquired.success());
    assert_eq!(fs::metadata(&lock).unwrap().ino(), inode);
    fs::remove_dir_all(root).unwrap();
}
#[test]
pub(crate) fn packaging_lock_allows_exactly_one_of_two_simultaneous_packagers() {
    use std::os::unix::fs::PermissionsExt;

    let root = std::env::temp_dir().join(format!("operon-package-race-{}", Uuid::new_v4()));
    let fake_bin = root.join("fake-bin");
    fs::create_dir_all(&fake_bin).unwrap();
    let marker = root.join("build-marker");
    let fake_cargo = fake_bin.join("cargo");
    fs::write(
        &fake_cargo,
        "#!/bin/sh\nprintf 'build\\n' >> \"$OPERON_TEST_MARKER\"\necho fake-cargo-reached >&2\nsleep 1\nexit 42\n",
    )
    .unwrap();
    let mut permissions = fs::metadata(&fake_cargo).unwrap().permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(&fake_cargo, permissions).unwrap();
    let path = format!(
        "{}:{}",
        fake_bin.display(),
        std::env::var("PATH").unwrap_or_default()
    );

    let launch = || {
        Command::new("bash")
            .arg("scripts/package-macos.sh")
            .env("OPERON_DIST_DIR", &root)
            .env("OPERON_TEST_MARKER", &marker)
            .env("PATH", &path)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap()
    };
    let first = launch();
    let second = launch();
    let first = first.wait_with_output().unwrap();
    let second = second.wait_with_output().unwrap();

    assert!(!first.status.success());
    assert!(!second.status.success());
    let errors = [
        String::from_utf8_lossy(&first.stderr),
        String::from_utf8_lossy(&second.stderr),
    ];
    assert_eq!(
        errors
            .iter()
            .filter(|error| error.contains("fake-cargo-reached"))
            .count(),
        1
    );
    assert_eq!(
        errors
            .iter()
            .filter(|error| error.contains("already running"))
            .count(),
        1
    );
    assert_eq!(fs::read_to_string(&marker).unwrap().lines().count(), 1);
    assert!(root.join(".operon-package.lockfile").is_file());
    fs::remove_dir_all(root).unwrap();
}
/// Sdlc 096. The installed application is built from whatever the tree holds,
/// committed or not, so the packager itself runs the three gates before it
/// builds; the Stop gate no longer nags about uncommitted Rust. A `cargo` that
/// records its arguments and stops at `build` shows the order.
///
/// And none of them inherits the packaging lock (fd 9): the suite starts
/// processes that can outlive it — a tmux server — and one holding the lock
/// refuses every later packager with nothing running. Review of 096.
#[test]
pub(crate) fn the_packager_runs_the_three_gates_before_it_builds() {
    use std::os::unix::fs::PermissionsExt;

    let root = std::env::temp_dir().join(format!("operon-package-gates-{}", Uuid::new_v4()));
    let fake_bin = root.join("fake-bin");
    fs::create_dir_all(&fake_bin).unwrap();
    let log = root.join("cargo-calls");
    let fake_cargo = fake_bin.join("cargo");
    fs::write(
        &fake_cargo,
        "#!/bin/sh\nprintf '%s\\n' \"$*\" >> \"$OPERON_TEST_MARKER\"\n\
         [ -e /dev/fd/9 ] && echo 'holds the packaging lock' >> \"$OPERON_TEST_MARKER\"\n\
         [ \"$1\" = build ] && exit 42\nexit 0\n",
    )
    .unwrap();
    let mut permissions = fs::metadata(&fake_cargo).unwrap().permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(&fake_cargo, permissions).unwrap();
    let path = format!(
        "{}:{}",
        fake_bin.display(),
        std::env::var("PATH").unwrap_or_default()
    );

    let output = Command::new("bash")
        .arg("scripts/package-macos.sh")
        .env("OPERON_DIST_DIR", &root)
        .env("OPERON_TEST_MARKER", &log)
        .env("PATH", &path)
        .output()
        .unwrap();
    let calls = fs::read_to_string(&log).unwrap_or_default();
    fs::remove_dir_all(&root).unwrap();

    assert!(
        !output.status.success(),
        "偽の cargo build が失敗しても packager が成功しました"
    );
    assert_eq!(
        calls.lines().collect::<Vec<_>>(),
        [
            "fmt --check",
            "test --locked",
            "clippy --locked -- -D warnings",
            "build --release --locked",
        ],
        "packager が 3 つの検査を build の前に走らせていないか、子プロセスが packaging lock を引き継いでいます"
    );
}
