pub(crate) fn bundle_replacement_rolls_back_normal_failures_after_each_swap() {
    for (phase, failure_variable) in [
        ("first", "OPERON_TEST_FAIL_AFTER_FIRST_SWAP"),
        ("second", "OPERON_TEST_FAIL_AFTER_SECOND_SWAP"),
    ] {
        for has_previous in [false, true] {
            let root = std::env::temp_dir().join(format!(
                "operon-bundle-normal-rollback-{phase}-{has_previous}-{}",
                Uuid::new_v4()
            ));
            let staged = root.join("staged.app");
            let bundle = root.join("Operon.app");
            let previous = root.join("Operon.previous.app");
            fs::create_dir_all(&staged).unwrap();
            fs::create_dir_all(&bundle).unwrap();
            fs::write(staged.join("marker"), "new").unwrap();
            fs::write(bundle.join("marker"), "current-good").unwrap();
            if has_previous {
                fs::create_dir_all(&previous).unwrap();
                fs::write(previous.join("marker"), "older-good").unwrap();
            }

            let output = Command::new("bash")
                .arg("scripts/replace-macos-bundle.sh")
                .arg(&staged)
                .arg(&bundle)
                .arg(&previous)
                .env(failure_variable, "1")
                .output()
                .unwrap();

            assert!(!output.status.success());
            assert_eq!(
                fs::read_to_string(bundle.join("marker")).unwrap(),
                "current-good"
            );
            assert_eq!(fs::read_to_string(staged.join("marker")).unwrap(), "new");
            if has_previous {
                assert_eq!(
                    fs::read_to_string(previous.join("marker")).unwrap(),
                    "older-good"
                );
            } else {
                assert!(!previous.exists());
            }
            assert!(String::from_utf8_lossy(&output.stderr).contains("restored"));
            fs::remove_dir_all(root).unwrap();
        }
    }
}
#[test]
pub(crate) fn term_after_either_atomic_swap_restores_the_exact_previous_generation() {
    for has_previous in [false, true] {
        for (phase, marker_variable) in [
            ("first", "OPERON_TEST_AFTER_FIRST_SWAP_MARKER"),
            ("second", "OPERON_TEST_AFTER_SECOND_SWAP_MARKER"),
        ] {
            let root = std::env::temp_dir().join(format!(
                "operon-bundle-term-{phase}-{has_previous}-{}",
                Uuid::new_v4()
            ));
            let staged = root.join("staged.app");
            let bundle = root.join("Operon.app");
            let previous = root.join("Operon.previous.app");
            let marker = root.join("paused");
            fs::create_dir_all(&staged).unwrap();
            fs::create_dir_all(&bundle).unwrap();
            fs::write(staged.join("marker"), "new").unwrap();
            fs::write(bundle.join("marker"), "current-good").unwrap();
            if has_previous {
                fs::create_dir_all(&previous).unwrap();
                fs::write(previous.join("marker"), "older-good").unwrap();
            }
            let mut child = Command::new("bash")
                .arg("scripts/replace-macos-bundle.sh")
                .arg(&staged)
                .arg(&bundle)
                .arg(&previous)
                .env(marker_variable, &marker)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .unwrap();
            for _ in 0..CHECKPOINT_POLLS {
                if marker.exists() {
                    break;
                }
                assert!(child.try_wait().unwrap().is_none());
                thread::sleep(Duration::from_millis(10));
            }
            assert!(
                marker.exists(),
                "replacement did not pause after the {phase} swap"
            );
            assert!(Command::new("/bin/kill")
                .args(["-TERM", &child.id().to_string()])
                .status()
                .unwrap()
                .success());
            let output = child.wait_with_output().unwrap();

            assert!(!output.status.success());
            assert_eq!(
                fs::read_to_string(bundle.join("marker")).unwrap(),
                "current-good"
            );
            if has_previous {
                assert_eq!(
                    fs::read_to_string(previous.join("marker")).unwrap(),
                    "older-good"
                );
            } else {
                assert!(!previous.exists());
            }
            assert_eq!(fs::read_to_string(staged.join("marker")).unwrap(), "new");
            assert!(String::from_utf8_lossy(&output.stderr).contains("restored"));
            fs::remove_dir_all(root).unwrap();
        }
    }
}
#[test]
pub(crate) fn repeated_term_cannot_interrupt_an_in_progress_bundle_rollback() {
    for has_previous in [false, true] {
        let root = std::env::temp_dir().join(format!(
            "operon-bundle-repeated-term-{has_previous}-{}",
            Uuid::new_v4()
        ));
        let staged = root.join("staged.app");
        let bundle = root.join("Operon.app");
        let previous = root.join("Operon.previous.app");
        let after_forward = root.join("after-forward");
        let during_rollback = root.join("during-rollback");
        let release_rollback = root.join("release-rollback");
        fs::create_dir_all(&staged).unwrap();
        fs::create_dir_all(&bundle).unwrap();
        fs::write(staged.join("marker"), "new").unwrap();
        fs::write(bundle.join("marker"), "current-good").unwrap();
        if has_previous {
            fs::create_dir_all(&previous).unwrap();
            fs::write(previous.join("marker"), "older-good").unwrap();
        }
        let mut child = Command::new("bash")
            .arg("scripts/replace-macos-bundle.sh")
            .arg(&staged)
            .arg(&bundle)
            .arg(&previous)
            .env("OPERON_TEST_AFTER_SECOND_SWAP_MARKER", &after_forward)
            .env("OPERON_TEST_DURING_ROLLBACK_MARKER", &during_rollback)
            .env("OPERON_TEST_DURING_ROLLBACK_RELEASE", &release_rollback)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        for _ in 0..CHECKPOINT_POLLS {
            if after_forward.exists() {
                break;
            }
            assert!(child.try_wait().unwrap().is_none());
            thread::sleep(Duration::from_millis(10));
        }
        assert!(after_forward.exists());
        assert!(Command::new("/bin/kill")
            .args(["-TERM", &child.id().to_string()])
            .status()
            .unwrap()
            .success());
        for _ in 0..CHECKPOINT_POLLS {
            if during_rollback.exists() {
                break;
            }
            assert!(child.try_wait().unwrap().is_none());
            thread::sleep(Duration::from_millis(10));
        }
        assert!(during_rollback.exists());
        assert!(Command::new("/bin/kill")
            .args(["-TERM", &child.id().to_string()])
            .status()
            .unwrap()
            .success());
        thread::sleep(Duration::from_millis(100));
        assert!(child.try_wait().unwrap().is_none());
        fs::write(&release_rollback, "continue").unwrap();
        let output = child.wait_with_output().unwrap();

        assert!(!output.status.success());
        assert_eq!(
            fs::read_to_string(bundle.join("marker")).unwrap(),
            "current-good"
        );
        assert_eq!(fs::read_to_string(staged.join("marker")).unwrap(), "new");
        if has_previous {
            assert_eq!(
                fs::read_to_string(previous.join("marker")).unwrap(),
                "older-good"
            );
        } else {
            assert!(!previous.exists());
        }
        fs::remove_dir_all(root).unwrap();
    }
}
#[test]
pub(crate) fn a_bundle_test_pause_nobody_releases_ends_and_rolls_back() {
    // A test that dies between a pause and its signal used to leave the script
    // looping for good; two such had run nine days (sdlc 099).
    let root = std::env::temp_dir().join(format!("operon-bundle-abandoned-{}", Uuid::new_v4()));
    let staged = root.join("staged.app");
    let bundle = root.join("Operon.app");
    let previous = root.join("Operon.previous.app");
    fs::create_dir_all(&staged).unwrap();
    fs::create_dir_all(&bundle).unwrap();
    fs::create_dir_all(&previous).unwrap();
    fs::write(staged.join("marker"), "new").unwrap();
    fs::write(bundle.join("marker"), "current-good").unwrap();
    fs::write(previous.join("marker"), "older-good").unwrap();
    let mut child = Command::new("bash")
        .arg("scripts/replace-macos-bundle.sh")
        .arg(&staged)
        .arg(&bundle)
        .arg(&previous)
        .env("OPERON_TEST_PAUSE_SECONDS", "1")
        .env("OPERON_TEST_AFTER_SECOND_SWAP_MARKER", root.join("after"))
        .env("OPERON_TEST_DURING_ROLLBACK_MARKER", root.join("during"))
        .env("OPERON_TEST_DURING_ROLLBACK_RELEASE", root.join("never"))
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let mut exited = false;
    for _ in 0..CHECKPOINT_POLLS {
        if child.try_wait().unwrap().is_some() {
            exited = true;
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }
    if !exited {
        child.kill().unwrap();
    }
    let output = child.wait_with_output().unwrap();

    assert!(exited, "an unreleased test pause kept the script running");
    assert!(!output.status.success());
    assert!(root.join("after").exists());
    assert!(root.join("during").exists());
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("Test pause expired"), "{stderr}");
    assert!(stderr.contains("restored"), "{stderr}");
    assert_eq!(
        fs::read_to_string(bundle.join("marker")).unwrap(),
        "current-good"
    );
    assert_eq!(
        fs::read_to_string(previous.join("marker")).unwrap(),
        "older-good"
    );
    assert_eq!(fs::read_to_string(staged.join("marker")).unwrap(), "new");
    fs::remove_dir_all(root).unwrap();
}
