#[test]
pub(crate) fn hard_kill_after_atomic_bundle_swap_never_removes_the_canonical_app() {
    let root = std::env::temp_dir().join(format!("operon-bundle-hard-kill-{}", Uuid::new_v4()));
    let staged = root.join("staged.app");
    let bundle = root.join("Operon.app");
    let previous = root.join("Operon.previous.app");
    let marker = root.join("after-swap");
    fs::create_dir_all(&staged).unwrap();
    fs::create_dir_all(&bundle).unwrap();
    fs::create_dir_all(&previous).unwrap();
    fs::write(staged.join("marker"), "new").unwrap();
    fs::write(bundle.join("marker"), "current-good").unwrap();
    fs::write(previous.join("marker"), "older-good").unwrap();
    let mut child = Command::new("bash")
        .arg("scripts/replace-macos-bundle.sh")
        .arg(&staged)
        .arg(&bundle)
        .arg(&previous)
        .env("OPERON_TEST_AFTER_SWAP_MARKER", &marker)
        .spawn()
        .unwrap();
    for _ in 0..CHECKPOINT_POLLS {
        if marker.exists() {
            break;
        }
        assert!(child.try_wait().unwrap().is_none());
        thread::sleep(Duration::from_millis(10));
    }
    assert!(marker.exists());

    child.kill().unwrap();
    let status = child.wait().unwrap();

    assert!(!status.success());
    assert!(bundle.is_dir());
    assert_eq!(fs::read_to_string(bundle.join("marker")).unwrap(), "new");
    assert_eq!(
        fs::read_to_string(previous.join("marker")).unwrap(),
        "older-good"
    );
    assert_eq!(
        fs::read_to_string(staged.join("marker")).unwrap(),
        "current-good"
    );
    fs::remove_dir_all(root).unwrap();
}
