#[test]
pub(crate) fn lists_main_and_linked_git_worktrees() {
    let root = std::env::temp_dir().join(format!("operon-test-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("README.md"), "test\n").unwrap();
    for arguments in [
        vec!["init"],
        vec!["config", "user.email", "test@example.invalid"],
        vec!["config", "user.name", "Operon test"],
        vec!["add", "README.md"],
        vec!["commit", "-m", "initial"],
    ] {
        assert!(git_command(&root)
            .args(arguments)
            .status()
            .unwrap()
            .success());
    }
    let linked = root.join("linked");
    assert!(git_command(&root)
        .args([
            "worktree",
            "add",
            "-b",
            "feature/test",
            linked.to_str().unwrap()
        ])
        .status()
        .unwrap()
        .success());
    let worktrees = list_worktrees(&root).unwrap();
    assert_eq!(worktrees.len(), 2);
    assert!(worktrees.iter().any(|worktree| worktree.is_main));
    assert!(worktrees
        .iter()
        .any(|worktree| worktree.branch.as_deref() == Some("feature/test")));
    assert!(git_command(&root)
        .args(["worktree", "remove", linked.to_str().unwrap()])
        .status()
        .unwrap()
        .success());
    assert_eq!(list_worktrees(&root).unwrap().len(), 1);
    fs::remove_dir_all(root).unwrap();
}

#[test]
pub(crate) fn test_git_land_worktree_success_and_guardrails() {
    let root = std::env::temp_dir().join(format!("operon-test-land-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("README.md"), "mainline\n").unwrap();
    for args in [
        vec!["init", "-b", "main"],
        vec!["config", "user.email", "test@example.invalid"],
        vec!["config", "user.name", "Operon test"],
        vec!["add", "README.md"],
        vec!["commit", "-m", "initial commit"],
    ] {
        assert!(git_command(&root).args(args).status().unwrap().success());
    }

    let linked = std::env::temp_dir().join(format!("operon-test-land-wt-{}", Uuid::new_v4()));
    assert!(git_command(&root)
        .args([
            "worktree",
            "add",
            "-b",
            "feature/my-test",
            linked.to_str().unwrap()
        ])
        .status()
        .unwrap()
        .success());

    // Guardrail: 0 commits ahead
    let res = git_land_worktree(&root, &linked, "feature/my-test", false);
    assert!(res.is_err(), "Should refuse land when 0 commits ahead");

    // Add a commit in the worktree
    fs::write(linked.join("feature.txt"), "new feature\n").unwrap();
    assert!(git_command(&linked)
        .args(["add", "feature.txt"])
        .status()
        .unwrap()
        .success());
    assert!(git_command(&linked)
        .args(["commit", "-m", "feat: new file"])
        .status()
        .unwrap()
        .success());

    // Guardrail: uncommitted changes in worktree
    fs::write(linked.join("dirty.txt"), "dirty\n").unwrap();
    let res_dirty = git_land_worktree(&root, &linked, "feature/my-test", false);
    assert!(
        res_dirty.is_err(),
        "Should refuse land when worktree has uncommitted changes"
    );
    fs::remove_file(linked.join("dirty.txt")).unwrap();

    // Successful land without auto cleanup
    let land = git_land_worktree(&root, &linked, "feature/my-test", false).unwrap();
    assert_eq!(land.mainline_branch, "main");
    assert_eq!(land.worktree_branch, "feature/my-test");
    assert_eq!(land.commits_merged, 1);
    assert!(!land.cleaned_up_worktree);
    assert!(!land.deleted_branch);
    assert!(root.join("feature.txt").exists());

    // Clean up
    let _ = git_command(&root)
        .args(["worktree", "remove", linked.to_str().unwrap()])
        .status();
    let _ = fs::remove_dir_all(&linked);
    let _ = fs::remove_dir_all(root);
}

/// A project on `main` with one linked worktree on `feature/land` that is one
/// commit ahead, and a hooks directory of its own outside both trees.
///
/// The hooks directory is set as a local absolute `core.hooksPath` so a global
/// one on the machine running the suite cannot stop a fixture hook from firing,
/// and it sits outside the project so writing a hook does not dirty the
/// checkout the landing inspects. `edits` are what the worktree's commit writes.
struct LandFixture {
    root: PathBuf,
    linked: PathBuf,
    hooks: PathBuf,
}

impl LandFixture {
    fn new(main_files: &[(&str, &str)], worktree_files: &[(&str, &str)]) -> Self {
        let id = Uuid::new_v4();
        let root = std::env::temp_dir().join(format!("operon-test-land-{id}"));
        let linked = std::env::temp_dir().join(format!("operon-test-land-wt-{id}"));
        let hooks = std::env::temp_dir().join(format!("operon-test-land-hooks-{id}"));
        fs::create_dir_all(&root).unwrap();
        fs::create_dir_all(&hooks).unwrap();
        fs::write(root.join("README.md"), "mainline\n").unwrap();
        fs::write(root.join("notes.txt"), "notes\n").unwrap();
        for args in [
            vec!["init", "-b", "main"],
            vec!["config", "user.email", "test@example.invalid"],
            vec!["config", "user.name", "Operon test"],
            vec!["config", "core.hooksPath", hooks.to_str().unwrap()],
            vec!["add", "."],
            vec!["commit", "-m", "initial commit"],
        ] {
            assert!(git_command(&root).args(args).status().unwrap().success());
        }
        assert!(git_command(&root)
            .args(["worktree", "add", "-b", "feature/land"])
            .arg(&linked)
            .status()
            .unwrap()
            .success());
        let fixture = Self {
            root,
            linked,
            hooks,
        };
        fixture.commit(&fixture.linked, worktree_files, "work in the worktree");
        if !main_files.is_empty() {
            fixture.commit(&fixture.root, main_files, "work on main");
        }
        fixture
    }

    fn commit(&self, tree: &Path, files: &[(&str, &str)], message: &str) {
        for (name, contents) in files {
            fs::write(tree.join(name), contents).unwrap();
        }
        assert!(git_command(tree)
            .args(["add", "."])
            .status()
            .unwrap()
            .success());
        assert!(git_command(tree)
            .args(["commit", "-m", message])
            .status()
            .unwrap()
            .success());
    }

    fn hook(&self, name: &str, body: &str) {
        use std::os::unix::fs::PermissionsExt;
        let path = self.hooks.join(name);
        fs::write(&path, format!("#!/bin/sh\n{body}\n")).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o755)).unwrap();
    }

    fn head(&self) -> String {
        git_output(&self.root, &["rev-parse", "HEAD"])
            .unwrap()
            .trim()
            .to_owned()
    }

    fn merge_in_progress(&self) -> bool {
        git_command(&self.root)
            .args(["rev-parse", "-q", "--verify", "MERGE_HEAD"])
            .stdout(Stdio::null())
            .status()
            .unwrap()
            .success()
    }

    fn status(&self) -> String {
        git_output(&self.root, &["status", "--porcelain"]).unwrap()
    }

    fn land(&self) -> std::result::Result<LandResult, String> {
        git_land_worktree(&self.root, &self.linked, "feature/land", false)
            .map_err(|error| error.to_string())
    }
}

impl Drop for LandFixture {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.linked);
        let _ = fs::remove_dir_all(&self.root);
        let _ = fs::remove_dir_all(&self.hooks);
    }
}

/// A person half way through a merge whose resolution equals `HEAD` has a clean
/// status, so only `MERGE_HEAD` says the checkout is busy. Landing used to run
/// its own merge into that, have git refuse, and `merge --abort` the person's
/// resolution away.
#[test]
pub(crate) fn refuses_to_land_over_a_merge_already_in_progress() {
    let fixture = LandFixture::new(&[], &[("feature.txt", "feature\n")]);
    // A side branch and main disagree about README.md; the person takes main's.
    assert!(git_command(&fixture.root)
        .args(["branch", "side"])
        .status()
        .unwrap()
        .success());
    fixture.commit(&fixture.root, &[("README.md", "main\n")], "main side");
    assert!(git_command(&fixture.root)
        .args(["checkout", "-q", "side"])
        .status()
        .unwrap()
        .success());
    fixture.commit(&fixture.root, &[("README.md", "side\n")], "other side");
    assert!(git_command(&fixture.root)
        .args(["checkout", "-q", "main"])
        .status()
        .unwrap()
        .success());
    let _ = git_command(&fixture.root)
        .args(["merge", "--no-edit", "side"])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    for args in [
        vec!["checkout", "--ours", "README.md"],
        vec!["add", "README.md"],
    ] {
        assert!(git_command(&fixture.root)
            .args(args)
            .stderr(Stdio::null())
            .status()
            .unwrap()
            .success());
    }
    assert!(fixture.merge_in_progress());
    assert!(fixture.status().trim().is_empty(), "the fixture's point");

    let error = fixture.land().expect_err("a merge in progress refuses");
    assert!(error.contains("別のマージが進行中"), "{error}");
    assert!(
        fixture.merge_in_progress(),
        "the person's merge is still there to finish"
    );
    assert!(!fixture.root.join("feature.txt").exists());
}

#[test]
pub(crate) fn a_conflicting_landing_is_aborted_and_names_the_files() {
    let fixture = LandFixture::new(
        &[("README.md", "main\n"), ("notes.txt", "main notes\n")],
        &[("README.md", "feature\n"), ("notes.txt", "feature notes\n")],
    );
    let before = fixture.head();

    let error = fixture.land().expect_err("a conflict refuses");
    assert!(error.contains("競合が発生したため"), "{error}");
    assert!(error.contains("元の状態に戻しました"), "{error}");
    assert!(error.contains("README.md"), "{error}");
    assert!(error.contains("notes.txt"), "{error}");
    assert_eq!(fixture.head(), before);
    assert!(!fixture.merge_in_progress());
    assert!(fixture.status().trim().is_empty(), "{}", fixture.status());
}

#[test]
pub(crate) fn a_landing_stopped_by_a_hook_is_undone() {
    let fixture = LandFixture::new(&[], &[("feature.txt", "feature\n")]);
    fixture.hook("pre-merge-commit", "echo hook-said-no >&2\nexit 1");
    let before = fixture.head();

    let error = fixture.land().expect_err("the hook refuses");
    assert!(error.contains("マージを完了できなかった"), "{error}");
    assert!(error.contains("元の状態に戻しました"), "{error}");
    assert!(error.contains("hook-said-no"), "{error}");
    assert_eq!(fixture.head(), before);
    assert!(!fixture.merge_in_progress());
    assert!(fixture.status().trim().is_empty(), "{}", fixture.status());
    assert!(!fixture.root.join("feature.txt").exists());
}

/// The sentence promises a restore, so the restore is checked rather than
/// assumed. A hook that takes the index lock leaves the abort unable to run.
#[test]
pub(crate) fn a_landing_that_cannot_be_undone_says_so() {
    let fixture = LandFixture::new(&[], &[("feature.txt", "feature\n")]);
    fixture.hook(
        "pre-merge-commit",
        "touch \"$(git rev-parse --git-dir)/index.lock\"\nexit 1",
    );

    let error = fixture.land().expect_err("the hook refuses");
    assert!(
        fixture.root.join(".git/index.lock").exists(),
        "the fixture's hook ran"
    );
    assert!(error.contains("取り消せませんでした"), "{error}");
    assert!(!error.contains("元の状態に戻しました"), "{error}");
    assert!(fixture.merge_in_progress(), "and that is what it says");
    let _ = fs::remove_file(fixture.root.join(".git/index.lock"));
}

/// A merge killed after it began writing the tree but before it wrote
/// `MERGE_HEAD` leaves `HEAD` where it was and no merge to abort, so only the
/// status says the checkout changed. That is what the timeout's SIGKILL does to
/// a slow merge; a hook that SIGKILLs the git running it is the same state on
/// demand (measured: no `MERGE_HEAD`, `HEAD` unchanged, the merged file staged).
/// A failing hook alone cannot stand in for it: git writes `MERGE_HEAD` after
/// the hook refuses.
#[test]
pub(crate) fn a_landing_that_left_the_tree_changed_is_not_called_unchanged() {
    let fixture = LandFixture::new(&[], &[("feature.txt", "feature\n")]);
    fixture.hook("pre-merge-commit", "kill -9 $PPID");
    let before = fixture.head();

    let error = fixture.land().expect_err("the hook refuses");
    assert_eq!(fixture.head(), before);
    assert!(!fixture.merge_in_progress(), "the fixture's hook ran");
    assert!(
        !fixture.status().trim().is_empty(),
        "the merge's writes remain"
    );
    assert!(error.contains("取り消せませんでした"), "{error}");
    assert!(!error.contains("変更されていません"), "{error}");
}

/// Landing writes the project checkout's index and `HEAD`, so it is one of the
/// writers `git_worktree_busy` counts, and the actions and the push button ask
/// that one question rather than each naming its own key.
#[test]
pub(crate) fn landing_and_the_projects_other_git_writes_wait_for_each_other() {
    let project = Project {
        id: Uuid::new_v4(),
        path: std::env::temp_dir().join(format!("operon-test-land-busy-{}", Uuid::new_v4())),
        name: "busy".into(),
        added_at: 0,
    };
    let worktree = project.path.join("wt");
    let mut tasks = HashSet::new();
    tasks.insert(BackgroundKey::LandWorktree(project.id));
    assert!(OperonApp::git_worktree_busy(&tasks, project.id));

    let mut app = test_app(project.path.join("store.json"));
    for key in [
        BackgroundKey::GitMutation(project.id),
        BackgroundKey::CommitMessage(project.id),
        BackgroundKey::LandWorktree(project.id),
    ] {
        app.background_tasks = HashSet::from([key.clone()]);
        app.notice = None;
        app.land_worktree(&project, &worktree, "feature/land", false);
        assert_eq!(app.background_tasks, HashSet::from([key.clone()]));
        assert_eq!(
            app.notice.as_deref(),
            Some(tr("Git の操作が既に実行中です。")),
            "landing waits for {key:?}"
        );

        app.notice = None;
        app.push_project(&project);
        assert_eq!(app.background_tasks, HashSet::from([key.clone()]));
        assert_eq!(
            app.notice.as_deref(),
            Some(tr("Git の操作が既に実行中です。")),
            "push waits for {key:?}"
        );
    }

    let body = rust_function_body("ui_push_row").expect("the push row is drawn somewhere");
    assert!(
        body.contains("git_worktree_busy"),
        "the push button greys out on the same question its action asks"
    );
}

/// The merge writes the project checkout, so an agent working there is as much
/// in the way as one working in the worktree.
#[test]
pub(crate) fn landing_waits_for_a_session_in_the_main_checkout() {
    let project = Project {
        id: Uuid::new_v4(),
        path: std::env::temp_dir().join(format!("operon-test-land-agent-{}", Uuid::new_v4())),
        name: "agent".into(),
        added_at: 0,
    };
    let worktree = project.path.join("wt");
    let session = |status, worktree_path: Option<PathBuf>, project_id| {
        let mut session = test_session(Uuid::new_v4(), status);
        session.project_id = project_id;
        session.worktree_path = worktree_path;
        session
    };

    for (status, path, project_id, blocked) in [
        (SessionStatus::Active, None, project.id, true),
        (SessionStatus::Queued, None, project.id, true),
        (
            SessionStatus::Active,
            Some(worktree.clone()),
            project.id,
            true,
        ),
        (SessionStatus::Exited, None, project.id, false),
        (SessionStatus::Active, None, Uuid::new_v4(), false),
        (
            SessionStatus::Active,
            Some(project.path.join("another")),
            project.id,
            false,
        ),
    ] {
        let sessions = [session(status.clone(), path.clone(), project_id)];
        assert_eq!(
            landing_blocked_by_session(&sessions, project.id, &worktree),
            blocked,
            "{status:?} in {path:?}"
        );
    }

    let mut app = test_app(project.path.join("store.json"));
    app.store.sessions = vec![session(SessionStatus::Active, None, project.id)];
    app.land_worktree(&project, &worktree, "feature/land", false);
    assert!(!app
        .background_tasks
        .contains(&BackgroundKey::LandWorktree(project.id)));
    assert_eq!(
        app.notice.as_deref(),
        Some(tr(
            "この worktree またはメイン作業ツリーで動作中・待機中のセッションがあります。停止・完了・キャンセルしてからマージしてください。"
        ))
    );
}

#[test]
pub(crate) fn test_checkpoints_create_list_restore_diff() {
    let root = std::env::temp_dir().join(format!("operon-test-cp-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    let file_path = root.join("app.txt");
    fs::write(&file_path, "version 1\n").unwrap();
    for args in [
        vec!["init", "-b", "main"],
        vec!["config", "user.email", "test@example.invalid"],
        vec!["config", "user.name", "Operon test"],
        vec!["add", "app.txt"],
        vec!["commit", "-m", "v1"],
    ] {
        assert!(git_command(&root).args(args).status().unwrap().success());
    }

    let session_id = Uuid::new_v4();

    // Modify file and stage for checkpoint
    fs::write(&file_path, "version 2\n").unwrap();
    assert!(git_command(&root)
        .args(["add", "app.txt"])
        .status()
        .unwrap()
        .success());

    let cp1 = git_create_checkpoint(&root, session_id, 1, "Turn 1 edit").unwrap();
    assert_eq!(cp1.turn_index, 1);
    assert_eq!(cp1.summary, "Turn 1 edit");

    let list = git_list_checkpoints(&root, session_id).unwrap();
    assert_eq!(list.len(), 1);
    assert_eq!(list[0].commit, cp1.commit);

    // Modify further
    fs::write(&file_path, "version 3 - broken\n").unwrap();
    let diff = git_diff_checkpoint(&root, &cp1.commit).unwrap();
    assert!(
        diff.contains("version 3"),
        "Diff should show changes since checkpoint"
    );

    // Restore checkpoint
    git_restore_checkpoint(&root, &cp1.commit).unwrap();
    assert_eq!(fs::read_to_string(&file_path).unwrap(), "version 2\n");

    fs::remove_dir_all(root).unwrap();
}

