#[test]
pub(crate) fn test_adversarial_security_and_resilience_invariants() {
    let root = std::env::temp_dir().join(format!("operon-test-sec-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("README.md"), "mainline\n").unwrap();
    for args in [
        vec!["init", "-b", "main"],
        vec!["config", "user.email", "test@example.invalid"],
        vec!["config", "user.name", "Operon test"],
        vec!["add", "README.md"],
        vec!["commit", "-m", "init"],
    ] {
        assert!(git_command(&root).args(args).status().unwrap().success());
    }

    // 1. Test is_safe_ref_name
    assert!(is_safe_ref_name("feature/safe-branch"));
    assert!(!is_safe_ref_name("-s"));
    assert!(!is_safe_ref_name("--upload-pack"));
    assert!(!is_safe_ref_name("bad branch name"));
    assert!(!is_safe_ref_name("bad..branch"));
    assert!(!is_safe_ref_name(""));

    let linked = std::env::temp_dir().join(format!("operon-test-sec-wt-{}", Uuid::new_v4()));
    assert!(git_command(&root)
        .args([
            "worktree",
            "add",
            "-b",
            "feature/sec-test",
            linked.to_str().unwrap()
        ])
        .status()
        .unwrap()
        .success());

    fs::write(linked.join("feat.txt"), "feat\n").unwrap();
    assert!(git_command(&linked)
        .args(["add", "feat.txt"])
        .status()
        .unwrap()
        .success());
    assert!(git_command(&linked)
        .args(["commit", "-m", "feat commit"])
        .status()
        .unwrap()
        .success());

    // 2. Refuse land on unsafe branch name
    assert!(git_land_worktree(&root, &linked, "--bad-flag", false).is_err());

    // 3. Refuse land when main checkout is on another branch
    assert!(git_command(&root)
        .args(["checkout", "-b", "dev"])
        .status()
        .unwrap()
        .success());
    let err_branch = git_land_worktree(&root, &linked, "feature/sec-test", false);
    assert!(
        err_branch.is_err(),
        "Should refuse land when main is not on mainline branch"
    );
    assert!(git_command(&root)
        .args(["checkout", "main"])
        .status()
        .unwrap()
        .success());

    // 4. Test checkpoints with UNSTAGED working tree edits
    let session_id = Uuid::new_v4();
    fs::write(linked.join("unstaged.txt"), "unstaged content\n").unwrap();
    let cp = git_create_checkpoint(&linked, session_id, 1, "Unstaged checkpoint").unwrap();
    assert_eq!(cp.turn_index, 1);

    // Staging area in worktree should still be clean (not staged into user's index)
    let status = git_output(&linked, &["status", "--porcelain"]).unwrap();
    assert!(
        status.contains("?? unstaged.txt"),
        "User index must not be modified by checkpoint capture"
    );

    // Restore to verify unstaged edits were indeed captured in the checkpoint commit!
    fs::remove_file(linked.join("unstaged.txt")).unwrap();
    assert!(!linked.join("unstaged.txt").exists());
    git_restore_checkpoint(&linked, &cp.commit).unwrap();
    assert_eq!(
        fs::read_to_string(linked.join("unstaged.txt")).unwrap(),
        "unstaged content\n"
    );

    // 5. Test TOCTOU defense for run scripts
    let script_dir = linked.join(".operon");
    fs::create_dir_all(&script_dir).unwrap();
    let run_file = script_dir.join("run.sh");
    fs::write(&run_file, "echo 'original'\n").unwrap();

    let initial = match read_run_script(&linked) {
        SetupScriptRead::Found(s) => s,
        other => panic!("Expected Found, got {:?}", other),
    };

    assert!(matches!(
        decide_run_script_run(&linked, &initial.digest),
        SetupRunDecision::Run(_)
    ));

    fs::write(&run_file, "echo 'malicious replacement'\n").unwrap();
    match decide_run_script_run(&linked, &initial.digest) {
        SetupRunDecision::Changed(updated) => {
            assert_ne!(updated.digest, initial.digest);
            assert_eq!(updated.preview[0], "echo 'malicious replacement'");
        }
        other => panic!("Expected Changed, got {:?}", other),
    }

    fs::remove_file(&run_file).unwrap();
    assert!(matches!(
        decide_run_script_run(&linked, &initial.digest),
        SetupRunDecision::Unreadable
    ));

    // 6. Test open_in_external_editor on nonexistent path
    let non_existent = root.join("does_not_exist_dir_xyz");
    assert!(open_in_external_editor(&non_existent, ExternalEditor::VsCode).is_err());

    // Clean up
    let _ = git_command(&root)
        .args(["worktree", "remove", "--force", linked.to_str().unwrap()])
        .status();
    let _ = fs::remove_dir_all(&linked);
    let _ = fs::remove_dir_all(root);
}

