/// The text of one method, wherever in `src/` it is defined.
///
/// Finds the `fn <name>(` line and returns everything up to the closing brace
/// at the same indentation. Crude, and it does not need to be more: the
/// question asked of it is whether a particular call appears inside a
/// particular function, and a guard that named the file instead would go blind
/// on the next move — which is what entry 014 in `docs/sdlc/lessons.md` is
/// about.
/// The identity of a document rooted at its project — what every test that
/// existed before change 034 meant by a `(project, path)` pair.
/// Put a document in front the way the editor does: open in `open_documents`
/// *and* pointed at by `active_document`.
///
/// Three fixtures used to set only the second, so the application was asked
/// about a document it did not have open. That was harmless while the question
/// "may this document show a diff" was asked in the drawing code — which never
/// runs for a document that is not open — and stopped being harmless when the
/// refresh path started asking it too. A fixture in a state production cannot
/// reach proves whatever it likes.
fn show_document(app: &mut OperonApp, project: &Project, path: &str) {
    let id = project_document(project, path);
    app.open_documents.push(OpenDocument {
        project: id.project,
        root: id.root.clone(),
        path: id.path.clone(),
        branch: None,
        project_rooted: true,
        disk: String::new(),
        buffer: String::new(),
        read_only: None,
        save_error: None,
        external_change: false,
        image_data: None,
    });
    app.active_document = Some(id);
}

fn project_document(project: &Project, path: &str) -> DocumentId {
    DocumentId {
        project: project.id,
        // Canonical, because that is what `open_document_at` stores. A helper
        // that built the other spelling would name a document the application
        // does not have.
        root: project
            .path
            .canonicalize()
            .unwrap_or_else(|_| project.path.clone()),
        path: PathBuf::from(path),
    }
}

fn rust_function_body(name: &str) -> Option<String> {
    let needle = format!("fn {name}(");
    let mut stack = vec![PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src")];
    while let Some(current) = stack.pop() {
        for entry in fs::read_dir(&current).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            if path.extension().is_none_or(|extension| extension != "rs") {
                continue;
            }
            if path.file_name().is_some_and(|file| file == "tests.rs") {
                continue;
            }
            let source = fs::read_to_string(&path).unwrap();
            let Some(line) = source.lines().find(|line| line.contains(&needle)) else {
                continue;
            };
            let indent = line.len() - line.trim_start().len();
            let close = format!("{}}}", " ".repeat(indent));
            let from = source.find(line).unwrap();
            let body = &source[from..];
            let to = body.find(&format!("\n{close}")).map_or(body.len(), |at| at);
            return Some(body[..to].to_owned());
        }
    }
    None
}

/// A pane that can take a note carries the way to send one. The review pane is
/// drawn in two places — the Git tab and the editor's diff view — and a note
/// written in the second one, sendable only from the first, is a note somebody
/// writes and then cannot find.
#[test]
pub(crate) fn every_pane_that_takes_a_note_offers_a_way_to_send_it() {
    let mut panes = 0;
    let mut footers = 0;
    let mut stack = vec![PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src")];
    while let Some(current) = stack.pop() {
        for entry in fs::read_dir(&current).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            if path.extension().is_none_or(|extension| extension != "rs") {
                continue;
            }
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            // `diff.rs` defines the pane and `app.rs` defines the footer; this
            // file quotes both to test them. Only the call sites count.
            if name == "diff.rs" || name == "app.rs" || name == "tests.rs" {
                continue;
            }
            let source = fs::read_to_string(&path).unwrap();
            panes += source.matches("diff_pane(").count();
            footers += source.matches("ui_diff_comment_footer(").count();
        }
    }
    assert!(panes > 0, "レビューペインの呼び出し元が見つかりません");
    assert_eq!(
        footers, panes,
        "レビューペイン {panes} 箇所に対して送信フッターが {footers} 箇所しかありません"
    );
}

/// Left is behind and right is ahead. Reading those the wrong way round turns
/// "you are behind, pull first" into a push over somebody else's work, which is
/// the one unrecoverable thing this feature can do.
#[test]
pub(crate) fn reads_how_far_a_branch_is_from_its_upstream() {
    let remote = temporary_directory("upstream-remote");
    git_in(&remote, &["init", "--bare", "--initial-branch=main"]);
    let root = worktree_fixture_repository("upstream-local");
    git_in(
        &root,
        &["remote", "add", "origin", remote.to_str().unwrap()],
    );

    // No upstream at all.
    let state = git_upstream_state(&root).unwrap();
    assert_eq!(state, UpstreamState::default());
    assert!(state.upstream.is_none());

    git_in(&root, &["push", "--set-upstream", "origin", "main"]);
    let state = git_upstream_state(&root).unwrap();
    assert_eq!(state.upstream.as_deref(), Some("origin/main"));
    assert_eq!((state.ahead, state.behind), (0, 0));

    // One commit here that the remote does not have: ahead, not behind.
    fs::write(root.join("README.md"), "ahead\n").unwrap();
    git_in(&root, &["commit", "-am", "ahead"]);
    let state = git_upstream_state(&root).unwrap();
    assert_eq!((state.ahead, state.behind), (1, 0));

    // Now the other way: a second clone pushes, and this one is behind.
    let other = temporary_directory("upstream-other");
    git_in(&root, &["push"]);
    git_in(
        &other,
        &["clone", remote.to_str().unwrap(), other.to_str().unwrap()],
    );
    git_in(&other, &["config", "user.email", "test@example.invalid"]);
    git_in(&other, &["config", "user.name", "Operon test"]);
    fs::write(other.join("README.md"), "from elsewhere\n").unwrap();
    git_in(&other, &["commit", "-am", "elsewhere"]);
    git_in(&other, &["push"]);
    git_in(&root, &["fetch", "origin"]);
    let state = git_upstream_state(&root).unwrap();
    assert_eq!((state.ahead, state.behind), (0, 1));

    discard_worktree_fixture(&root);
    let _ = fs::remove_dir_all(remote);
    let _ = fs::remove_dir_all(other);
}

/// What is recorded is what the list showed. A file staged by hand and then
/// unticked must not ride along, which is why the index is reset first.
#[test]
pub(crate) fn stages_exactly_the_files_that_were_ticked() {
    let root = worktree_fixture_repository("stage-exactly");
    for name in ["wanted.txt", "unwanted.txt", "staged-by-hand.txt"] {
        fs::write(root.join(name), "x\n").unwrap();
    }
    // The case the reset exists for.
    git_in(&root, &["add", "staged-by-hand.txt"]);

    git_stage_exactly(&root, &["wanted.txt".to_owned()]).unwrap();
    let staged = git_in(&root, &["diff", "--cached", "--name-only"]);
    assert_eq!(staged, "wanted.txt");

    git_record_staged(&root, "just the wanted one").unwrap();
    let committed = git_in(&root, &["show", "--name-only", "--format=", "HEAD"]);
    assert_eq!(committed, "wanted.txt");
    // Both others are still sitting in the working tree, untouched.
    assert!(root.join("unwanted.txt").exists());
    assert!(root.join("staged-by-hand.txt").exists());
    let remaining = git_in(&root, &["status", "--porcelain"]);
    assert!(remaining.contains("unwanted.txt"), "{remaining}");
    assert!(remaining.contains("staged-by-hand.txt"), "{remaining}");

    discard_worktree_fixture(&root);
}

/// The message is one argument in a vector and never a shell string, so a
/// message that looks like a shell command is a message.
#[test]
pub(crate) fn commits_a_message_that_would_break_a_shell() {
    let root = worktree_fixture_repository("hostile-message");
    fs::write(root.join("file.txt"), "x\n").unwrap();
    git_stage_exactly(&root, &["file.txt".to_owned()]).unwrap();

    let proof = root.join("shell-ran.txt");
    let message = format!(
        "Add \"quoted\" work $(touch {}) `and backticks`\n\nA body with 'single quotes' too.",
        proof.display()
    );
    git_record_staged(&root, &message).unwrap();

    assert_eq!(git_in(&root, &["log", "-1", "--format=%B"]), message.trim());
    assert!(
        !proof.exists(),
        "コミットメッセージがシェルとして実行された"
    );

    discard_worktree_fixture(&root);
}

/// Pushing over a remote that moved is how somebody else's work disappears.
/// The refusal is in the function, not in the interface, so no future caller
/// can route around it.
#[test]
pub(crate) fn refuses_to_push_over_a_remote_that_moved() {
    let root = worktree_fixture_repository("push-refusal");
    let behind = UpstreamState {
        upstream: Some("origin/main".into()),
        ahead: 1,
        behind: 2,
    };
    let error = git_push(&root, &behind, "main").unwrap_err().to_string();
    assert!(error.contains("先に pull"), "{error}");

    discard_worktree_fixture(&root);
}

/// A branch nobody has pushed gets its upstream made for it, and nothing is
/// ever forced.
#[test]
pub(crate) fn pushes_a_new_branch_with_its_upstream_and_never_with_force() {
    let remote = temporary_directory("push-remote");
    git_in(&remote, &["init", "--bare", "--initial-branch=main"]);
    let root = worktree_fixture_repository("push-new-branch");
    git_in(
        &root,
        &["remote", "add", "origin", remote.to_str().unwrap()],
    );

    let state = git_upstream_state(&root).unwrap();
    assert!(state.upstream.is_none());
    git_push(&root, &state, "main").unwrap();

    let after = git_upstream_state(&root).unwrap();
    assert_eq!(after.upstream.as_deref(), Some("origin/main"));
    assert_eq!((after.ahead, after.behind), (0, 0));
    assert_eq!(
        git_in(&remote, &["rev-parse", "refs/heads/main"]),
        git_in(&root, &["rev-parse", "HEAD"])
    );

    discard_worktree_fixture(&root);
    let _ = fs::remove_dir_all(remote);
}

/// The one action in this application that can destroy work belonging to
/// somebody who is not at this keyboard. There is no force in any spelling, and
/// this is what keeps it that way — adding one accidentally is meant to be
/// impossible rather than merely discouraged.
#[test]
pub(crate) fn no_source_file_can_force_a_push() {
    let forbidden = [
        "--force",
        "--force-with-lease",
        "--force-if-includes",
        "push -f",
        "\"-f\"",
        "+refs/",
    ];
    let mut offenders = Vec::new();
    let mut stack = vec![PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src")];
    while let Some(current) = stack.pop() {
        for entry in fs::read_dir(&current).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            if path.extension().is_none_or(|extension| extension != "rs") {
                continue;
            }
            // This file names the strings in order to forbid them.
            if path.file_name().is_some_and(|file| file == "tests.rs") {
                continue;
            }
            let source = fs::read_to_string(&path).unwrap();
            for needle in forbidden {
                if source.contains(needle) {
                    offenders.push(format!("{}: {needle}", path.display()));
                }
            }
        }
    }
    assert!(
        offenders.is_empty(),
        "履歴を書き換えうる指定が入りました: {offenders:?}"
    );
}

/// Every agent Operon can launch can also draft a message, and every draft runs
/// in that CLI's own read-only mode. A drafting run that could edit a file
/// would be a button that changed the change it was describing.
#[test]
pub(crate) fn builds_a_read_only_draft_command_for_every_agent_operon_launches() {
    for agent in AGENTS {
        if *agent == "custom" {
            // A command somebody typed in. Operon does not know how to ask it
            // for one sentence and must not guess.
            assert!(commit_message_command(agent, "prompt").is_none());
            continue;
        }
        let (program, arguments) = commit_message_command(agent, "prompt")
            .unwrap_or_else(|| panic!("{agent} に下書きの実行方法がありません"));
        assert!(!program.is_empty());
        assert_eq!(
            arguments.last().map(String::as_str),
            Some("prompt"),
            "{agent} はプロンプトを最後の引数として渡していません"
        );
        let flags = arguments[..arguments.len() - 1].join(" ");
        let read_only = match *agent {
            "claude" => flags.contains("-p") && flags.contains("--permission-mode plan"),
            "codex" => flags.contains("exec") && flags.contains("-s read-only"),
            "gemini" => flags.contains("--print") && flags.contains("--sandbox"),
            other => panic!("{other} の読み取り専用の形が決まっていません"),
        };
        assert!(
            read_only,
            "{agent} の下書きが読み取り専用ではありません: {flags}"
        );
    }

    // The choice of CLI is the first present one, in this order.
    let mut tools = ToolStatus::default();
    assert_eq!(commit_message_agent(&tools), None);
    tools.antigravity = true;
    assert_eq!(commit_message_agent(&tools), Some("gemini"));
    tools.codex = true;
    assert_eq!(commit_message_agent(&tools), Some("codex"));
    tools.claude = true;
    assert_eq!(commit_message_agent(&tools), Some("claude"));
}

/// Every model does at least one of these at least sometimes, and a commit
/// message wearing a code fence is how somebody stops trusting the button.
#[test]
pub(crate) fn strips_the_fences_and_quotes_a_model_wraps_a_message_in() {
    let wanted =
        "Start a worktree from the mainline\n\nBecause the folder was on a feature branch.";
    for raw in [
        wanted.to_owned(),
        format!("```\n{wanted}\n```"),
        format!("```text\n{wanted}\n```"),
        format!("\"{wanted}\""),
        format!("\n\n  {wanted}  \n\n"),
    ] {
        assert_eq!(clean_generated_commit_message(&raw), wanted, "raw: {raw:?}");
    }
    // A fence around a message that itself contains a fenced block keeps the
    // inner one: only the outermost wrapper is a wrapper.
    let with_code = "Fix the parser\n\n```rust\nlet x = 1;\n```";
    assert_eq!(
        clean_generated_commit_message(&format!("```\n{with_code}\n```")),
        with_code
    );
    assert_eq!(clean_generated_commit_message("   "), "");
}

/// The exact shape `lsof -nP -iTCP -sTCP:LISTEN -F pcnd` prints, captured from
/// this machine before the parser was written rather than imagined for it.
const LSOF_LISTENERS: &str = "\
p787
crapportd
f11
d0xcb1db319852c271a
n*:53327
f14
d0x75574765c23c049f
n*:53327
f20
d0x4a17297e5885fb78
n*:53097
p4821
cnode
f23
d0x1111111111111111
n127.0.0.1:5173
f24
d0x2222222222222222
n[::1]:5173
p4999
cpostgres
f7
d0x3333333333333333
n0.0.0.0:5432
p5100
f9
d0x4444444444444444
n127.0.0.1:9999
";

#[test]
pub(crate) fn reads_the_pid_command_and_port_out_of_what_lsof_prints() {
    let ports = parse_lsof_listeners(LSOF_LISTENERS);
    let node = ports
        .iter()
        .find(|port| port.process == "node")
        .expect("node が読めていない");
    assert_eq!(node.pid, 4821);
    assert_eq!(node.port, 5173);
    assert_eq!(node.host, "127.0.0.1");

    // A command name belongs to the process block it was printed under and to
    // no other. `-F` omits a field it has no value for, so a block without a
    // `c` line is nameless — not named after whoever came before it.
    assert!(ports
        .iter()
        .filter(|port| port.pid == 787)
        .all(|port| port.process == "rapportd"));
    let nameless = ports
        .iter()
        .find(|port| port.pid == 5100)
        .expect("c 行のないブロックが読めていない");
    assert_eq!(nameless.process, "");
    assert_eq!(nameless.port, 9999);
    assert_eq!(
        ports
            .iter()
            .find(|port| port.port == 5432)
            .map(|port| port.process.as_str()),
        Some("postgres")
    );
}

/// A process binding both stacks prints its port twice. That is one listener:
/// the identity is the process and the port, not the socket.
#[test]
pub(crate) fn counts_one_listener_when_a_process_binds_both_stacks() {
    let ports = parse_lsof_listeners(LSOF_LISTENERS);
    assert_eq!(
        ports.iter().filter(|port| port.port == 5173).count(),
        1,
        "IPv4 と IPv6 が二重に数えられている: {ports:?}"
    );
    // 53327 is printed twice for one pid too, and once more for a different fd
    // on a different port — so deduplication must not eat the second port.
    assert_eq!(ports.iter().filter(|port| port.pid == 787).count(), 2);
}

/// `*` and `0.0.0.0` say what was bound. Neither is something a browser can
/// open, and the row exists to be clicked.
#[test]
pub(crate) fn turns_a_wildcard_bind_into_something_clickable() {
    let ports = parse_lsof_listeners(LSOF_LISTENERS);
    for port in &ports {
        assert!(
            !port.host.contains('*') && port.host != "0.0.0.0",
            "開けないホストが残っている: {port:?}"
        );
    }
    let wildcard = ports.iter().find(|port| port.port == 5432).unwrap();
    assert_eq!(wildcard.host, "localhost");
    assert_eq!(port_url(wildcard), "http://localhost:5432/");

    // Only the two ports a person means https by.
    let https = ListeningPort {
        pid: 1,
        process: "caddy".into(),
        port: 8443,
        host: "localhost".into(),
    };
    assert_eq!(port_url(&https), "https://localhost:8443/");
}

/// The deepest containing worktree wins. A project contains its own worktrees,
/// so a shallowest-match rule would give the project every port on the machine
/// that happened to be started underneath it.
#[test]
pub(crate) fn attributes_a_port_to_the_deepest_worktree_that_contains_it() {
    let project = PathBuf::from("/w/project");
    let inner = PathBuf::from("/w/project/worktrees/fix-login");
    let ports = vec![
        ListeningPort {
            pid: 1,
            process: "node".into(),
            port: 5173,
            host: "localhost".into(),
        },
        ListeningPort {
            pid: 2,
            process: "node".into(),
            port: 3000,
            host: "localhost".into(),
        },
    ];
    let directories = HashMap::from([
        (1, PathBuf::from("/w/project/worktrees/fix-login/web")),
        (2, PathBuf::from("/w/project/web")),
    ]);

    let attributed = attribute_ports(&ports, &directories, &[project.clone(), inner.clone()]);
    assert_eq!(attributed[0].1.as_ref(), Some(&inner));
    assert_eq!(attributed[1].1.as_ref(), Some(&project));
}

/// A port belonging to nothing Operon knows about stays unattributed rather
/// than being given to the nearest thing.
#[test]
pub(crate) fn leaves_a_port_unattributed_when_no_worktree_contains_it() {
    let ports = vec![ListeningPort {
        pid: 9,
        process: "postgres".into(),
        port: 5432,
        host: "localhost".into(),
    }];
    let directories = HashMap::from([(9, PathBuf::from("/usr/local/var/postgres"))]);
    let attributed = attribute_ports(&ports, &directories, &[PathBuf::from("/w/project")]);
    assert_eq!(attributed[0].1, None);

    // A process whose working directory could not be read is unattributed too,
    // rather than falling through to the first worktree in the list.
    let attributed = attribute_ports(&ports, &HashMap::new(), &[PathBuf::from("/w/project")]);
    assert_eq!(attributed[0].1, None);

    // A sibling whose path merely starts with the same characters is not
    // inside it. `starts_with` on a `Path` compares components, and this is the
    // test that says so on purpose.
    let attributed = attribute_ports(
        &ports,
        &HashMap::from([(9, PathBuf::from("/w/project-other/web"))]),
        &[PathBuf::from("/w/project")],
    );
    assert_eq!(attributed[0].1, None);
}

#[test]
pub(crate) fn reads_a_working_directory_for_every_process_lsof_named() {
    let directories = parse_lsof_working_directories(
        "p4821\nfcwd\nn/w/project/worktrees/fix-login/web\np4999\nfcwd\nn/usr/local/var/postgres\n",
    );
    assert_eq!(directories.len(), 2);
    assert_eq!(
        directories.get(&4821),
        Some(&PathBuf::from("/w/project/worktrees/fix-login/web"))
    );
    assert_eq!(
        directories.get(&4999),
        Some(&PathBuf::from("/usr/local/var/postgres"))
    );
}

/// Every way this can fail means the same thing to every caller: nothing is
/// known. It is information, not a task, and a permanent complaint about a
/// missing reading is worse than the missing reading.
#[test]
pub(crate) fn a_missing_lsof_is_a_reading_of_nothing_rather_than_an_error() {
    // A program that is not there, named rather than arranged: emptying `PATH`
    // for this test reached every other test running beside it and took out the
    // one that needs to find `tmux`.
    let reading = scan_listening_ports_with(
        "operon-there-is-no-such-program",
        &[PathBuf::from("/w/project")],
    );
    assert!(reading.is_empty());

    // And output that says nothing parses to nothing, rather than to one blank
    // entry that would be drawn as `:0`.
    assert!(parse_lsof_listeners("").is_empty());
    assert!(parse_lsof_listeners("p\nc\nn\n").is_empty());
    assert!(parse_lsof_working_directories("").is_empty());

    // The real program on this machine answers without panicking, whatever it
    // finds — the parser meets the live output at least once in the suite.
    let _ = scan_listening_ports(&[]);
}

fn terminal_test_lines(texts: &[&str]) -> Vec<LayoutJob> {
    texts
        .iter()
        .map(|text| {
            let mut job = LayoutJob::default();
            job.append(text, 0.0, egui::TextFormat::default());
            job
        })
        .collect()
}

/// The pane is monospace with an exact 1:2 CJK advance, which is what the
/// cursor and the preedit are already drawn on. A highlight positioned by
/// character count instead of by cell would drift right across a Japanese line.
#[test]
pub(crate) fn counts_a_cjk_character_as_two_terminal_columns() {
    assert_eq!(terminal_display_columns("abc"), 3);
    assert_eq!(terminal_display_columns("あ"), 2);
    assert_eq!(terminal_display_columns("テスト失敗"), 10);
    assert_eq!(terminal_display_columns("エラー: failed"), 6 + 8);
    assert_eq!(terminal_display_columns("한국어"), 6);
    assert_eq!(terminal_display_columns(""), 0);
}

/// A line can say the thing twice, and stepping through matches has to reach
/// both.
#[test]
pub(crate) fn finds_every_occurrence_including_several_on_one_line() {
    let lines = terminal_test_lines(&["failed once", "failed and failed again", "passed"]);
    let found = terminal_search_matches(&lines, "failed");
    assert_eq!(found.len(), 3);
    assert_eq!(found[0].line, 0);
    assert_eq!(found[1].line, 1);
    assert_eq!(found[2].line, 1);
    assert_eq!(found[1].column, 0);
    assert_eq!(found[2].column, "failed and ".len());
    // Occurrences do not overlap, so a query that could match inside itself
    // still advances.
    assert_eq!(
        terminal_search_matches(&terminal_test_lines(&["aaaa"]), "aa").len(),
        2
    );
}

#[test]
pub(crate) fn matches_without_regard_to_case() {
    let lines = terminal_test_lines(&["test result: FAILED", "Failed to connect"]);
    assert_eq!(terminal_search_matches(&lines, "failed").len(), 2);
    assert_eq!(terminal_search_matches(&lines, "FAILED").len(), 2);
    assert_eq!(terminal_search_matches(&lines, "FaIlEd").len(), 2);
}

/// The column is where the wash is painted, so it is measured in the same cells
/// the pane draws in.
#[test]
pub(crate) fn reports_the_column_a_match_starts_at_in_display_cells() {
    let lines = terminal_test_lines(&["エラー: FAILED here"]);
    let found = terminal_search_matches(&lines, "failed");
    assert_eq!(found.len(), 1);
    // 「エラー」 is three wide characters, then `: ` — six cells plus two.
    assert_eq!(found[0].column, 8);
    assert_eq!(found[0].columns, 6);

    let japanese = terminal_search_matches(&terminal_test_lines(&["前置き 失敗しました"]), "失敗");
    assert_eq!(japanese[0].column, 7);
    assert_eq!(japanese[0].columns, 4);
}

/// An empty query matches nothing rather than everything, which is what a
/// naive substring search would do and would wash the whole pane.
#[test]
pub(crate) fn finds_nothing_for_an_empty_query() {
    let lines = terminal_test_lines(&["something", "", "else"]);
    assert!(terminal_search_matches(&lines, "").is_empty());
    assert!(terminal_search_matches(&lines, "nothing here").is_empty());
    assert!(terminal_search_matches(&[], "anything").is_empty());
    // A query longer than the line cannot match it, and must not read past it.
    assert!(terminal_search_matches(&terminal_test_lines(&["ab"]), "abc").is_empty());
}

/// A one-character query against a full scrollback would otherwise build a
/// vector nobody can use, once per keystroke.
#[test]
pub(crate) fn stops_collecting_matches_at_its_ceiling() {
    let line = "a".repeat(100);
    let texts: Vec<&str> = (0..100).map(|_| line.as_str()).collect();
    let lines = terminal_test_lines(&texts);
    let found = terminal_search_matches(&lines, "a");
    assert_eq!(found.len(), TERMINAL_SEARCH_MAX_MATCHES);
}

/// The shape Claude Code pipes to a status-line command, with the two spellings
/// of the percentage that have been seen from it.
#[test]
pub(crate) fn reads_both_spellings_of_a_usage_window() {
    let payload = serde_json::json!({
        "total_duration_ms": 1234,
        "rate_limits": {
            "five_hour": { "used_percentage": 62.4, "resets_at": 1_757_000_000_u64 },
            "seven_day": { "utilization": 18, "resets_at": "1757600000" }
        }
    });
    let limits = parse_rate_limits(&payload).expect("読めていない");
    let five = limits.five_hour.unwrap();
    assert!((five.used_percent - 62.4).abs() < 0.01);
    assert_eq!(five.resets_at, Some(1_757_000_000));
    let seven = limits.seven_day.unwrap();
    assert!((seven.used_percent - 18.0).abs() < 0.01);
    // `resets_at` was a string in older versions and is epoch seconds today.
    assert_eq!(seven.resets_at, Some(1_757_600_000));
}

/// Only a subscriber session emits `rate_limits`, and only after its first
/// response. Its absence is ordinary and means "nothing said", never "nothing
/// left" — a payload without it must not publish a reading of zero.
#[test]
pub(crate) fn a_payload_without_limits_is_not_a_reading() {
    assert!(parse_rate_limits(&serde_json::json!({ "model": "sonnet" })).is_none());
    assert!(parse_rate_limits(&serde_json::json!({ "rate_limits": {} })).is_none());
    assert!(
        parse_rate_limits(&serde_json::json!({ "rate_limits": { "five_hour": {} } })).is_none()
    );
    // One window present and the other absent is a reading of the one.
    let one = parse_rate_limits(&serde_json::json!({
        "rate_limits": { "five_hour": { "used_percentage": 4 } }
    }))
    .unwrap();
    assert!(one.five_hour.is_some());
    assert!(one.seven_day.is_none());
    assert_eq!(one.five_hour.unwrap().resets_at, None);
}

/// A percentage outside its range is a CLI this app does not understand, and a
/// bar drawn past its end is worse than a bar drawn at its end.
#[test]
pub(crate) fn clamps_a_percentage_to_its_range() {
    let over = parse_rate_limits(&serde_json::json!({
        "rate_limits": { "five_hour": { "used_percentage": 140 }, "seven_day": { "used_percentage": -3 } }
    }))
    .unwrap();
    assert_eq!(over.five_hour.unwrap().used_percent, 100.0);
    assert_eq!(over.seven_day.unwrap().used_percent, 0.0);
}

/// A slot holding somebody else's command is never taken, and an empty slot
/// that Operon has filled before means the person emptied it deliberately.
/// Without the second fact every launch would put back what they just removed.
#[test]
pub(crate) fn never_takes_a_status_line_slot_that_belongs_to_someone_else() {
    let script = PathBuf::from("/data/agent-hooks/claude-statusline.sh");

    let mut fresh = serde_json::Map::new();
    assert_eq!(
        statusline_slot(&fresh, &script, false),
        StatusLineSlot::Free
    );
    assert!(apply_statusline(&mut fresh, &script, false, true));
    assert_eq!(statusline_slot(&fresh, &script, true), StatusLineSlot::Ours);
    // Writing the same thing twice changes nothing, so the file is not
    // rewritten on every launch.
    assert!(!apply_statusline(&mut fresh, &script, true, true));

    let mut theirs: serde_json::Map<String, serde_json::Value> = serde_json::from_value(
        serde_json::json!({ "statusLine": { "type": "command", "command": "~/bin/mine.sh" } }),
    )
    .unwrap();
    assert_eq!(
        statusline_slot(&theirs, &script, false),
        StatusLineSlot::Theirs
    );
    assert!(!apply_statusline(&mut theirs, &script, false, true));
    assert_eq!(
        theirs["statusLine"]["command"].as_str(),
        Some("~/bin/mine.sh"),
        "他人の設定を書き換えた"
    );
    // And removing ours never removes theirs.
    assert!(!apply_statusline(&mut theirs, &script, true, false));
    assert!(theirs.contains_key("statusLine"));

    // The person took ours out. It stays out.
    let mut emptied = serde_json::Map::new();
    assert_eq!(
        statusline_slot(&emptied, &script, true),
        StatusLineSlot::Theirs
    );
    assert!(!apply_statusline(&mut emptied, &script, true, true));
    assert!(emptied.is_empty());
}

/// Turning the reader off takes out ours and nothing else.
#[test]
pub(crate) fn removing_the_reader_leaves_every_other_setting_intact() {
    let script = PathBuf::from("/data/agent-hooks/claude-statusline.sh");
    let mut settings: serde_json::Map<String, serde_json::Value> = serde_json::from_value(
        serde_json::json!({
            "statusLine": { "type": "command", "command": "/data/agent-hooks/claude-statusline.sh" },
            "model": "opus",
            "hooks": { "Stop": [] }
        }),
    )
    .unwrap();
    assert!(apply_statusline(&mut settings, &script, true, false));
    assert!(!settings.contains_key("statusLine"));
    assert_eq!(settings["model"].as_str(), Some("opus"));
    assert!(settings.contains_key("hooks"));
}

/// The reader must print nothing: whatever it writes becomes the status line
/// inside the terminal, and this is a way of reading what the CLI already says
/// rather than a place to put a second one. `/bin/sh -n` also has to accept it.
#[test]
pub(crate) fn the_usage_reader_is_valid_shell_that_prints_nothing() {
    let script = statusline_script();
    let root = temporary_directory("statusline-script");
    let path = root.join("reader.sh");
    fs::write(&path, script.as_bytes()).unwrap();
    let parsed = Command::new("/bin/sh")
        .args(["-n", path.to_str().unwrap()])
        .output()
        .unwrap();
    assert!(
        parsed.status.success(),
        "シェルとして解釈できない: {}",
        String::from_utf8_lossy(&parsed.stderr)
    );
    assert!(
        !script.contains("printf '%s\\n' '{}'"),
        "ステータス行に何か書き出している"
    );

    // With no environment and no payload it exits quietly, which is what every
    // pane that is not an Operon session will do.
    let run = Command::new("/bin/sh")
        .arg(path.to_str().unwrap())
        .stdin(std::process::Stdio::null())
        .output()
        .unwrap();
    assert!(run.status.success());
    assert!(run.stdout.is_empty(), "何か出力した: {:?}", run.stdout);

    // A payload with no rate limits in it is dropped before anything else is
    // read, so an ordinary session posts nothing at all.
    let mut quiet = Command::new("/bin/sh");
    quiet.arg(path.to_str().unwrap());
    let run = run_with_stdin(&mut quiet, br#"{"model":"sonnet"}"#);
    assert!(run.status.success());
    assert!(run.stdout.is_empty());

    fs::remove_dir_all(root).unwrap();
}

fn run_with_stdin(command: &mut Command, input: &[u8]) -> std::process::Output {
    use std::io::Write;
    let mut child = command
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.as_mut().unwrap().write_all(input).unwrap();
    child.wait_with_output().unwrap()
}

/// The whole chain, through the command the installer actually wrote into
/// Claude's own settings file, under a path with a space in it.
///
/// This is the shape entry 013 in `docs/sdlc/lessons.md` produced: a fixture is
/// a claim about production, and every macOS data path contains a space. The
/// throttle in particular is shell arithmetic on a number pulled out of the
/// payload with parameter expansion — the kind of thing that is either exactly
/// right or silently does nothing, and only a real run can tell which.
#[test]
pub(crate) fn the_installed_usage_reader_posts_a_reading_end_to_end() {
    let root = temporary_directory("usage e2e");
    let home = root.join("home");
    let data_file = root.join("store-v2.json");
    fs::create_dir_all(&home).unwrap();
    let socket = hook_socket_path(&data_file);
    let (_listener, events) = HookListener::bind(&socket, None).unwrap();

    let tools = ToolStatus {
        git: true,
        tmux: true,
        codex: false,
        claude: true,
        antigravity: false,
        gh: false,
    };
    apply_hooks(
        &data_file,
        &home,
        &socket,
        &tools,
        true,
        &AgentAccounts::default(),
    );

    let session = managed_tmux_name(Uuid::new_v4());
    let environment = HookEnvironment {
        session: session.clone(),
        launch_token: "tok".to_owned(),
        endpoint: hook_endpoint_path(&data_file),
        socket: socket.clone(),
    }
    .variables();

    let settings: serde_json::Value =
        serde_json::from_slice(&fs::read(claude_settings_in(&claude_config_root(&home))).unwrap())
            .unwrap();
    let command = settings["statusLine"]["command"]
        .as_str()
        .unwrap()
        .to_owned();
    assert_eq!(settings["statusLine"]["type"].as_str(), Some("command"));

    let post = |payload: &str, stamp: &Path| {
        let mut child = Command::new("/bin/sh");
        child.arg(&command);
        for (key, value) in &environment {
            child.env(key, value);
        }
        // Somewhere this test owns, so a stale stamp from another run of the
        // suite cannot decide the answer.
        child.env("TMPDIR", stamp);
        child.stdin(Stdio::piped()).stdout(Stdio::piped());
        let mut running = child.spawn().unwrap();
        running
            .stdin
            .take()
            .unwrap()
            .write_all(payload.as_bytes())
            .unwrap();
        running.wait_with_output().unwrap()
    };

    let stamps = root.join("stamps");
    fs::create_dir_all(&stamps).unwrap();
    let first = post(
        r#"{"total_duration_ms":1000,"rate_limits":{"five_hour":{"used_percentage":62,"resets_at":1757000000},"seven_day":{"used_percentage":18}}}"#,
        &stamps,
    );
    assert!(first.status.success());
    // Nothing on stdout: whatever it printed would become the status line.
    assert!(first.stdout.is_empty(), "{:?}", first.stdout);

    let event = events
        .recv_timeout(Duration::from_secs(5))
        .expect("読みが届いていない");
    assert_eq!(event.event, STATUSLINE_EVENT);
    let limits = parse_rate_limits(&event.payload).expect("読めていない");
    assert_eq!(limits.five_hour.unwrap().used_percent, 62.0);
    assert_eq!(limits.seven_day.unwrap().used_percent, 18.0);

    // A second post one second later is inside the throttle and is dropped, so
    // a status line ticking three times a second is not three posts a second.
    let second = post(
        r#"{"total_duration_ms":2000,"rate_limits":{"five_hour":{"used_percentage":63}}}"#,
        &stamps,
    );
    assert!(second.status.success());
    assert!(
        events.recv_timeout(Duration::from_millis(600)).is_err(),
        "間隔をあけずに投稿している"
    );

    // Past the interval it posts again, with the new number.
    let third = post(
        &format!(
            r#"{{"total_duration_ms":{},"rate_limits":{{"five_hour":{{"used_percentage":71}}}}}}"#,
            1000 + STATUSLINE_MIN_POST_INTERVAL_MS + 1
        ),
        &stamps,
    );
    assert!(third.status.success());
    let event = events
        .recv_timeout(Duration::from_secs(5))
        .expect("間隔を過ぎても投稿していない");
    assert_eq!(
        parse_rate_limits(&event.payload)
            .unwrap()
            .five_hour
            .unwrap()
            .used_percent,
        71.0
    );

    fs::remove_dir_all(root).unwrap();
}

/// The line a Rust panic actually prints, which is the case this exists for.
#[test]
pub(crate) fn finds_a_path_and_its_line_in_a_stack_trace() {
    let targets = terminal_targets("thread 'tests::x' panicked at src/app.rs:120:8:");
    assert_eq!(targets.len(), 1);
    assert_eq!(
        targets[0].kind,
        TerminalTargetKind::Path {
            path: "src/app.rs".into(),
            line: Some(120)
        }
    );
    // The column is read and dropped, so the whole token is still underlined.
    assert_eq!(targets[0].columns, "src/app.rs:120:8".len());

    let without_line = terminal_targets("  Compiling operon (src/main.rs)");
    assert_eq!(
        without_line[0].kind,
        TerminalTargetKind::Path {
            path: "src/main.rs".into(),
            line: None
        }
    );
    // Line zero is not a line.
    let zero = terminal_targets("at src/app.rs:0");
    assert_eq!(
        zero[0].kind,
        TerminalTargetKind::Path {
            path: "src/app.rs".into(),
            line: None
        }
    );
}

/// A false positive underlines a word that is not a file and opens nothing when
/// clicked, which is worse than missing one.
#[test]
pub(crate) fn does_not_call_ordinary_words_paths() {
    for line in [
        "test result: ok. 400 passed",
        "Finished `release` profile",
        "warning: unused variable",
        "..",
        "the sentence ends here.",
        "version 1.2.3 released",
    ] {
        let paths: Vec<_> = terminal_targets(line)
            .into_iter()
            .filter(|target| matches!(target.kind, TerminalTargetKind::Path { .. }))
            .collect();
        assert!(paths.is_empty(), "{line:?} から {paths:?} を拾った");
    }
}

/// What a dev server prints, and what a sentence does to the end of it.
#[test]
pub(crate) fn finds_a_url_without_the_punctuation_after_it() {
    let targets = terminal_targets("  ➜  Local:   http://localhost:5173/");
    assert_eq!(
        targets[0].kind,
        TerminalTargetKind::Url("http://localhost:5173/".into())
    );

    let sentence = terminal_targets("see https://example.invalid/docs.");
    assert_eq!(
        sentence[0].kind,
        TerminalTargetKind::Url("https://example.invalid/docs".into())
    );

    let bracketed = terminal_targets("(https://example.invalid/a)");
    assert_eq!(
        bracketed[0].kind,
        TerminalTargetKind::Url("https://example.invalid/a".into())
    );

    // A scheme in the middle of a token is part of that token, not a link.
    assert!(terminal_targets("xhttp://nope").is_empty());
}

/// The column is where the underline is painted, so it is measured in the cells
/// the pane draws in — the same arithmetic the search highlight uses.
#[test]
pub(crate) fn reports_a_target_position_in_display_cells() {
    let targets = terminal_targets("エラー src/app.rs:1");
    assert_eq!(targets.len(), 1);
    // 「エラー」 is three wide characters, then a space.
    assert_eq!(targets[0].column, 7);
    assert_eq!(targets[0].columns, "src/app.rs:1".len());
}

/// A stack trace can name a file outside this session's folder, and a click
/// must not become a way of reading it.
#[test]
pub(crate) fn refuses_a_path_that_escapes_the_session_folder() {
    let root = temporary_directory("terminal-target");
    let inside = root.join("src");
    fs::create_dir_all(&inside).unwrap();
    fs::write(inside.join("app.rs"), "fn main() {}\n").unwrap();
    let outside = root
        .parent()
        .unwrap()
        .join(format!("operon-outside-{}.txt", Uuid::new_v4().simple()));
    fs::write(&outside, "secret\n").unwrap();

    assert_eq!(
        resolve_terminal_path(&root, "src/app.rs"),
        Some(inside.join("app.rs").canonicalize().unwrap())
    );
    // A relative escape, an absolute path elsewhere, and something that is not
    // there at all.
    assert_eq!(
        resolve_terminal_path(
            &root,
            &format!("../{}", outside.file_name().unwrap().to_string_lossy())
        ),
        None
    );
    assert_eq!(
        resolve_terminal_path(&root, outside.to_str().unwrap()),
        None
    );
    assert_eq!(resolve_terminal_path(&root, "src/missing.rs"), None);
    // A directory is not a file to open.
    assert_eq!(resolve_terminal_path(&root, "src"), None);

    let _ = fs::remove_file(outside);
    fs::remove_dir_all(root).unwrap();
}

/// Acceptance Criterion R1.1 & R1.3:
/// Command (⌘) + Click or Option (⌥) + Click on a terminal target triggers opening.
/// Plain clicks must only focus the terminal and NEVER open files.
/// Plain clicks on an unfocused terminal must NOT open links (remedying the prior defect).
#[test]
pub(crate) fn test_terminal_open_modifier_detection_and_focus_isolation() {
    use crate::screens::is_terminal_open_modifier;

    // 1. Plain click (no modifier keys held)
    let plain_modifiers = egui::Modifiers::default();
    assert!(
        !is_terminal_open_modifier(&plain_modifiers),
        "plain click without modifiers must NOT be considered an open modifier"
    );

    // 2. Command click (modifiers.command == true, standard macOS Cmd)
    let cmd_modifiers = egui::Modifiers {
        command: true,
        ..Default::default()
    };
    assert!(
        is_terminal_open_modifier(&cmd_modifiers),
        "modifiers.command must trigger open modifier"
    );

    // 3. Mac Command click (modifiers.mac_cmd == true, macOS specific Command key)
    let mac_cmd_modifiers = egui::Modifiers {
        mac_cmd: true,
        ..Default::default()
    };
    assert!(
        is_terminal_open_modifier(&mac_cmd_modifiers),
        "modifiers.mac_cmd must trigger open modifier"
    );

    // 4. Option click (modifiers.alt == true, macOS Option key)
    let alt_modifiers = egui::Modifiers {
        alt: true,
        ..Default::default()
    };
    assert!(
        is_terminal_open_modifier(&alt_modifiers),
        "modifiers.alt (Option) must trigger open modifier for backward compatibility"
    );

    // 5. Shift click (modifiers.shift == true)
    let shift_modifiers = egui::Modifiers {
        shift: true,
        ..Default::default()
    };
    assert!(
        !is_terminal_open_modifier(&shift_modifiers),
        "Shift alone must NOT trigger open modifier"
    );

    // 6. Defect regression assertion:
    // In previous versions: let opening = clicked && (modifiers.alt || !terminal_response.has_focus());
    // When has_focus was false, plain click opened links!
    // The corrected logic requires: clicked && is_terminal_open_modifier(&modifiers)
    let clicked = true;
    let has_focus = false;

    // Defect reproduction on old formula:
    let old_buggy_opening = clicked && (plain_modifiers.alt || !has_focus);
    assert!(
        old_buggy_opening,
        "demonstrating that old logic had the defect of opening on plain click when unfocused"
    );

    // Fixed formula:
    let fixed_opening = clicked && is_terminal_open_modifier(&plain_modifiers);
    assert!(
        !fixed_opening,
        "fixed logic must NOT open link on plain click, even if terminal is not focused"
    );
}

/// Acceptance Criterion R1.1 & R1.2:
/// ⌘+Clicking a file with a line number (e.g. `src/main.rs:42`) switches to `Page::Projects`,
/// selects `ProjectTab::Files`, sets `editor_jump_line = Some(42)`, and forces `EditorView::Edit`
/// so the cursor jumps to line 42 in the editor buffer.
#[test]
pub(crate) fn test_open_terminal_target_navigates_and_jumps_to_line() {
    let root = temporary_directory("target-nav-jump");
    let project_path = root.join("project");
    let src_dir = project_path.join("src");
    fs::create_dir_all(&src_dir).unwrap();
    let main_rs = src_dir.join("main.rs");

    // Create 50 lines so line 42 exists
    let mut file_content = String::new();
    for i in 1..=50 {
        file_content.push_str(&format!("// line {i}\n"));
    }
    fs::write(&main_rs, &file_content).unwrap();

    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: "test-project".into(),
        path: project_path.clone(),
        added_at: 0,
    };
    app.store.projects.push(project.clone());

    let mut session = test_session(Uuid::new_v4(), SessionStatus::Active);
    session.project_id = project.id;
    session.worktree_path = Some(project_path.clone());
    app.store.sessions.push(session.clone());
    app.selected_session = Some(session.id);
    app.page = Page::Sessions;

    // Simulate resolved path cache entry
    let canonical = main_rs.canonicalize().unwrap();
    app.resolved_paths
        .insert("src/main.rs".into(), Some(canonical));

    // Target with line number 42
    app.open_terminal_target(TerminalTargetKind::Path {
        path: "src/main.rs".into(),
        line: Some(42),
    });

    assert_eq!(
        app.page,
        Page::Projects,
        "clicking a terminal path must switch page to Page::Projects"
    );
    assert_eq!(
        app.project_tab,
        ProjectTab::Files,
        "clicking a terminal path must select ProjectTab::Files"
    );
    assert_eq!(
        app.selected_project,
        Some(project.id),
        "target navigation must select the active session project"
    );
    assert_eq!(
        app.editor_jump_line,
        Some(42),
        "target navigation with line must set editor_jump_line to Some(42)"
    );
    assert_eq!(
        app.editor_view,
        EditorView::Edit,
        "line jump navigation must set editor_view to EditorView::Edit"
    );
    assert!(
        app.active_document.is_some(),
        "navigating to file must open the document in active_document"
    );
    assert_eq!(
        app.active_document.as_ref().unwrap().path,
        PathBuf::from("src/main.rs")
    );
    assert!(
        app.notice.is_none(),
        "valid path opening must not leave any error notice banner"
    );

    fs::remove_dir_all(&root).ok();
}

