/// Verify resolve_terminal_session_path gives precedence to worktree over project root when both exist.
#[test]
pub(crate) fn test_resolve_terminal_session_path_precedence_and_fallback() {
    let root = temporary_directory("resolve-session-path");
    let project_path = root.join("project");
    let worktree_path = root.join("worktree");
    fs::create_dir_all(&project_path).unwrap();
    fs::create_dir_all(&worktree_path).unwrap();

    // 1. File exists in both -> worktree wins
    let wt_file = worktree_path.join("file.txt");
    let proj_file = project_path.join("file.txt");
    fs::write(&wt_file, "from worktree").unwrap();
    fs::write(&proj_file, "from project").unwrap();
    let resolved = resolve_terminal_session_path(Some(&worktree_path), &project_path, "file.txt");
    assert_eq!(resolved, Some(wt_file.canonicalize().unwrap()));

    // 2. File exists only in project -> project wins
    let only_proj = project_path.join("only_proj.txt");
    fs::write(&only_proj, "only project").unwrap();
    let resolved =
        resolve_terminal_session_path(Some(&worktree_path), &project_path, "only_proj.txt");
    assert_eq!(resolved, Some(only_proj.canonicalize().unwrap()));

    // 3. File in neither -> None
    let resolved =
        resolve_terminal_session_path(Some(&worktree_path), &project_path, "nonexistent.txt");
    assert_eq!(resolved, None);

    // 4. No worktree -> project checked directly
    let resolved = resolve_terminal_session_path(None, &project_path, "only_proj.txt");
    assert_eq!(resolved, Some(only_proj.canonicalize().unwrap()));

    fs::remove_dir_all(&root).ok();
}

