/// Acceptance Criterion R1.4 (Edge cases):
/// Nonexistent file, out of bounds path, and missing project set appropriate notices.
#[test]
pub(crate) fn test_open_terminal_target_external_error_handling() {
    let root = temporary_directory("target-ext-errors");
    let project_path = root.join("project");
    fs::create_dir_all(&project_path).unwrap();

    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: "test-project".into(),
        path: project_path.clone(),
        added_at: 0,
    };
    app.store.projects.push(project.clone());

    let mut session = test_session(Uuid::new_v4(), SessionStatus::Active);
    session.project_id = project.id;
    session.worktree_path = Some(project_path.clone());
    app.store.sessions.push(session.clone());
    app.selected_session = Some(session.id);
    app.page = Page::Sessions;

    // 1. Nonexistent file
    app.open_terminal_target_external(TerminalTargetKind::Path {
        path: "nonexistent.rs".into(),
        line: None,
    });
    assert_eq!(app.page, Page::Sessions);
    let notice = app.notice.take().unwrap();
    assert!(notice.contains("ファイルが見つかりません"));

    // 2. Out of boundary file
    let outside_file = root.join("outside.txt");
    fs::write(&outside_file, "secret").unwrap();
    app.resolved_paths.insert(
        "../outside.txt".into(),
        Some(outside_file.canonicalize().unwrap()),
    );
    app.open_terminal_target_external(TerminalTargetKind::Path {
        path: "../outside.txt".into(),
        line: None,
    });
    assert_eq!(app.page, Page::Sessions);
    let notice = app.notice.take().unwrap();
    assert!(notice.contains("はこのプロジェクトの外にあります。"));

    // 3. Missing project
    let orphan_session = test_session(Uuid::new_v4(), SessionStatus::Active);
    app.store.sessions.push(orphan_session.clone());
    app.selected_session = Some(orphan_session.id);
    app.open_terminal_target_external(TerminalTargetKind::Path {
        path: "anything.rs".into(),
        line: None,
    });
    assert_eq!(
        app.notice.take(),
        Some(tr("このセッションのプロジェクトが見つかりません。").into())
    );

    fs::remove_dir_all(&root).ok();
}

/// Acceptance Criteria R1.3 & Functional Behavior:
/// Regular click without Command (⌘) modifier focuses terminal and does not trigger file opening.
/// Option (⌥) click triggers internal editor opening.
/// Command (⌘) click triggers external default application opening.
#[test]
pub(crate) fn test_terminal_click_interaction_modifier_routing() {
    use crate::screens::{is_terminal_cmd_modifier, is_terminal_open_modifier};

    let root = temporary_directory("target-ext-routing");
    let project_path = root.join("project");
    fs::create_dir_all(&project_path).unwrap();
    let file = project_path.join("file.rs");
    fs::write(&file, "// test content\n").unwrap();
    let canonical = file.canonicalize().unwrap();

    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: "test-project".into(),
        path: project_path.clone(),
        added_at: 0,
    };
    app.store.projects.push(project.clone());

    let mut session = test_session(Uuid::new_v4(), SessionStatus::Active);
    session.project_id = project.id;
    session.worktree_path = Some(project_path.clone());
    app.store.sessions.push(session.clone());
    app.selected_session = Some(session.id);
    app.page = Page::Sessions;
    app.resolved_paths
        .insert("file.rs".into(), Some(canonical.clone()));

    let target = TerminalTargetKind::Path {
        path: "file.rs".into(),
        line: Some(10),
    };

    // Scenario A: Plain click (no modifier)
    let plain_modifiers = egui::Modifiers::default();
    let has_open = is_terminal_open_modifier(&plain_modifiers);
    assert!(!has_open, "plain click has no open modifier");
    // Under plain click, neither external nor internal open should be called:
    assert_eq!(app.page, Page::Sessions);
    assert!(app.active_document.is_none());
    assert!(app.notice.is_none());

    // Scenario B: Command click (macOS Command)
    let cmd_modifiers = egui::Modifiers {
        command: true,
        ..Default::default()
    };
    assert!(is_terminal_open_modifier(&cmd_modifiers));
    assert!(is_terminal_cmd_modifier(&cmd_modifiers));
    if is_terminal_cmd_modifier(&cmd_modifiers) {
        app.open_terminal_target_external(target.clone());
    } else {
        app.open_terminal_target(target.clone());
    }
    assert_eq!(
        app.page,
        Page::Sessions,
        "Command+click must trigger external open, staying on Page::Sessions"
    );
    assert!(
        app.active_document.is_none(),
        "Command+click must not open in internal editor"
    );
    assert_eq!(
        app.notice.take(),
        Some(format!("{}…", tr("ファイルを開く")))
    );

    // Scenario C: Option click (macOS Alt / Option)
    let alt_modifiers = egui::Modifiers {
        alt: true,
        ..Default::default()
    };
    assert!(is_terminal_open_modifier(&alt_modifiers));
    assert!(!is_terminal_cmd_modifier(&alt_modifiers));
    if is_terminal_cmd_modifier(&alt_modifiers) {
        app.open_terminal_target_external(target.clone());
    } else {
        app.open_terminal_target(target.clone());
    }
    assert_eq!(
        app.page,
        Page::Projects,
        "Option+click must trigger internal editor open, navigating to Page::Projects"
    );
    assert_eq!(app.project_tab, ProjectTab::Files);
    assert_eq!(app.editor_jump_line, Some(10));
    assert!(app.active_document.is_some());

    fs::remove_dir_all(&root).ok();
}

/// Acceptance Criterion R1:
/// Terminal path resolution and opening must be isolated per session,
/// preventing cache pollution across sessions/projects.
#[test]
pub(crate) fn test_open_terminal_target_session_switching_cache_isolation() {
    let root = temporary_directory("target-ext-session-isolation");
    let proj1_path = root.join("project1");
    let proj2_path = root.join("project2");
    fs::create_dir_all(proj1_path.join("src")).unwrap();
    fs::create_dir_all(proj2_path.join("src")).unwrap();

    let file1 = proj1_path.join("src/main.rs");
    let file2 = proj2_path.join("src/main.rs");
    fs::write(&file1, "// project 1\n").unwrap();
    fs::write(&file2, "// project 2\n").unwrap();
    let canonical1 = file1.canonicalize().unwrap();
    let canonical2 = file2.canonicalize().unwrap();

    let mut app = test_app(root.join("store.json"));
    let proj1 = Project {
        id: Uuid::new_v4(),
        name: "project-1".into(),
        path: proj1_path.clone(),
        added_at: 0,
    };
    let proj2 = Project {
        id: Uuid::new_v4(),
        name: "project-2".into(),
        path: proj2_path.clone(),
        added_at: 1,
    };
    app.store.projects.push(proj1.clone());
    app.store.projects.push(proj2.clone());

    let mut session1 = test_session(Uuid::new_v4(), SessionStatus::Active);
    session1.project_id = proj1.id;
    session1.worktree_path = None;
    app.store.sessions.push(session1.clone());

    let mut session2 = test_session(Uuid::new_v4(), SessionStatus::Active);
    session2.project_id = proj2.id;
    session2.worktree_path = None;
    app.store.sessions.push(session2.clone());

    // 1. In Session 1, resolve "src/main.rs"
    app.selected_session = Some(session1.id);
    app.unresolved_paths.push("src/main.rs".into());
    app.resolve_terminal_paths();
    assert_eq!(
        app.resolved_paths.get("src/main.rs").cloned().flatten(),
        Some(canonical1)
    );

    // 2. Switch to Session 2
    app.select_session(session2.id);

    // In Session 2, user Command+clicks "src/main.rs"
    app.open_terminal_target_external(TerminalTargetKind::Path {
        path: "src/main.rs".into(),
        line: None,
    });

    // It must NOT fail with "はこのプロジェクトの外にあります。"
    // It must succeed opening Session 2's file!
    assert_eq!(
        app.notice,
        Some(format!("{}…", tr("ファイルを開く"))),
        "external open must succeed for session 2"
    );
    assert_eq!(
        app.resolved_paths.get("src/main.rs").cloned().flatten(),
        Some(canonical2),
        "resolved_paths must be updated to session 2's canonical path"
    );

    fs::remove_dir_all(&root).ok();
}

/// Acceptance Criterion R1 & R2:
/// Multiple worktree sessions under the same project must not leak path resolution cache.
/// When switching between worktree sessions, paths must resolve to the active worktree root.
#[test]
pub(crate) fn test_open_terminal_target_worktree_switching_cache_isolation() {
    let root = temporary_directory("target-ext-wt-isolation");
    let project_path = root.join("project");
    let wt1_path = project_path.join(".worktrees").join("branch-1");
    let wt2_path = project_path.join(".worktrees").join("branch-2");
    fs::create_dir_all(wt1_path.join("src")).unwrap();
    fs::create_dir_all(wt2_path.join("src")).unwrap();

    let file_wt1 = wt1_path.join("src/lib.rs");
    let file_wt2 = wt2_path.join("src/lib.rs");
    fs::write(&file_wt1, "// wt1\n").unwrap();
    fs::write(&file_wt2, "// wt2\n").unwrap();
    let canonical_wt1 = file_wt1.canonicalize().unwrap();
    let canonical_wt2 = file_wt2.canonicalize().unwrap();

    // File only in wt2, not in wt1
    let extra_wt2 = wt2_path.join("src/extra.rs");
    fs::write(&extra_wt2, "// extra\n").unwrap();
    let canonical_extra = extra_wt2.canonicalize().unwrap();

    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: "shared-repo".into(),
        path: project_path.clone(),
        added_at: 0,
    };
    app.store.projects.push(project.clone());

    let mut session1 = test_session(Uuid::new_v4(), SessionStatus::Active);
    session1.project_id = project.id;
    session1.worktree_path = Some(wt1_path.clone());
    app.store.sessions.push(session1.clone());

    let mut session2 = test_session(Uuid::new_v4(), SessionStatus::Active);
    session2.project_id = project.id;
    session2.worktree_path = Some(wt2_path.clone());
    app.store.sessions.push(session2.clone());

    // 1. Session 1 caches src/lib.rs and checks extra.rs (which is absent in wt1 -> None)
    app.select_session(session1.id);
    app.unresolved_paths.push("src/lib.rs".into());
    app.unresolved_paths.push("src/extra.rs".into());
    app.resolve_terminal_paths();
    assert_eq!(
        app.resolved_paths.get("src/lib.rs").cloned().flatten(),
        Some(canonical_wt1)
    );
    assert_eq!(
        app.resolved_paths.get("src/extra.rs").cloned().flatten(),
        None,
        "extra.rs does not exist in wt1"
    );

    // 2. Switch to Session 2
    app.select_session(session2.id);

    // Verify cache is cleared on session switch
    assert!(
        app.resolved_paths.is_empty(),
        "resolved_paths cache must be cleared when switching sessions"
    );

    // In Session 2, resolve and Command+click src/lib.rs
    app.open_terminal_target_external(TerminalTargetKind::Path {
        path: "src/lib.rs".into(),
        line: None,
    });
    assert_eq!(
        app.notice,
        Some(format!("{}…", tr("ファイルを開く"))),
        "external open must succeed for session 2"
    );
    assert_eq!(
        app.resolved_paths.get("src/lib.rs").cloned().flatten(),
        Some(canonical_wt2.clone()),
        "Session 2 must resolve to wt2/src/lib.rs, NOT wt1/src/lib.rs"
    );

    // In Session 2, test resolving the file that was absent in Session 1
    app.unresolved_paths.push("src/extra.rs".into());
    app.resolve_terminal_paths();
    assert_eq!(
        app.resolved_paths.get("src/extra.rs").cloned().flatten(),
        Some(canonical_extra),
        "extra.rs must now resolve in Session 2 despite being absent in Session 1"
    );

    // In Session 2, Option+click opens in built-in editor under wt2 root
    app.open_terminal_target(TerminalTargetKind::Path {
        path: "src/lib.rs".into(),
        line: Some(42),
    });
    assert_eq!(app.page, Page::Projects);
    let active_doc = app.active_document.as_ref().unwrap();
    assert_eq!(
        active_doc.root,
        wt2_path.canonicalize().unwrap(),
        "internal editor document must be rooted in wt2, NOT wt1"
    );
    assert_eq!(app.editor_jump_line, Some(42));

    fs::remove_dir_all(&root).ok();
}

/// Acceptance Criterion R1.1 & R1.2:
/// When new terminal output arrives via `set_session_output`, negative resolution cache entries
/// (cached `None`) must be evicted so dynamically generated files can be re-probed and opened.
#[test]
pub(crate) fn test_set_session_output_evicts_negative_cache_for_dynamic_files() {
    let root = temporary_directory("target-ext-dynamic-eviction");
    let project_path = root.join("project");
    fs::create_dir_all(project_path.join("src")).unwrap();

    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: "dyn-project".into(),
        path: project_path.clone(),
        added_at: 0,
    };
    app.store.projects.push(project.clone());

    let mut session = test_session(Uuid::new_v4(), SessionStatus::Active);
    session.project_id = project.id;
    session.worktree_path = Some(project_path.clone());
    app.store.sessions.push(session.clone());

    app.select_session(session.id);

    // 1. Initial probe when file does NOT exist -> cached as None
    app.unresolved_paths.push("src/generated.rs".into());
    app.resolve_terminal_paths();
    assert_eq!(
        app.resolved_paths
            .get("src/generated.rs")
            .cloned()
            .flatten(),
        None,
        "initially missing file must be cached as None"
    );

    // 2. Now the file is dynamically created by an agent/build tool
    let file = project_path.join("src/generated.rs");
    fs::write(&file, "// generated content\n").unwrap();
    let canonical = file.canonicalize().unwrap();

    // 3. New output arrives from tmux -> set_session_output must evict negative (None) entries
    app.set_session_output(
        session.id,
        "Build finished: src/generated.rs\n".into(),
        None,
    );
    assert!(
        !app.resolved_paths.contains_key("src/generated.rs"),
        "negative cache entry for src/generated.rs must be evicted after set_session_output"
    );

    // 4. Next probe discovers the file
    app.unresolved_paths.push("src/generated.rs".into());
    app.resolve_terminal_paths();
    assert_eq!(
        app.resolved_paths
            .get("src/generated.rs")
            .cloned()
            .flatten(),
        Some(canonical.clone()),
        "probed file must now resolve successfully"
    );

    // 5. Command (⌘) + click opens it externally
    app.open_terminal_target_external(TerminalTargetKind::Path {
        path: "src/generated.rs".into(),
        line: None,
    });
    assert_eq!(
        app.notice,
        Some(format!("{}…", tr("ファイルを開く"))),
        "external open must succeed for newly generated file"
    );

    fs::remove_dir_all(&root).ok();
}

/// Acceptance Criterion R1 & R2:
/// Deleting a session record cleanly resets path resolution caches and terminal context menu.
#[test]
pub(crate) fn test_delete_session_cleans_terminal_path_cache_and_menu() {
    let root = temporary_directory("target-ext-delete-session");
    let project_path = root.join("project");
    fs::create_dir_all(&project_path).unwrap();

    let mut app = test_app(root.join("store.json"));
    let project = Project {
        id: Uuid::new_v4(),
        name: "proj".into(),
        path: project_path.clone(),
        added_at: 0,
    };
    app.store.projects.push(project.clone());

    let mut session = test_session(Uuid::new_v4(), SessionStatus::Exited);
    session.project_id = project.id;
    app.store.sessions.push(session.clone());

    app.select_session(session.id);
    app.resolved_paths
        .insert("foo.rs".into(), Some(project_path.join("foo.rs")));
    app.unresolved_paths.push("bar.rs".into());
    app.terminal_path_menu = Some((session.id, project_path.join("foo.rs")));

    assert_eq!(app.selected_session, Some(session.id));
    assert!(!app.resolved_paths.is_empty());
    assert!(app.terminal_path_menu.is_some());

    app.remove_session_record(session.id);

    assert_eq!(app.selected_session, None);
    assert!(app.resolved_paths.is_empty());
    assert!(app.unresolved_paths.is_empty());
    assert_eq!(app.resolved_paths_session, None);
    assert_eq!(app.terminal_path_menu, None);

    fs::remove_dir_all(&root).ok();
}

