/// Change 072. Obsolete or conflicting options in stored settings are sanitized.
#[test]
pub(crate) fn recent_agent_settings_sanitizes_invalid_options() {
    let mut claude_settings = AgentLaunchSettings {
        model: "my-model".to_owned(),
        mode: "non-existent-mode".to_owned(),
        effort: "super-deep".to_owned(),
        flags: vec![
            "unknown-flag".to_owned(),
            "skip-permissions".to_owned(),
            "skip-permissions".to_owned(),
        ],
        custom_command: "arbitrary-command".to_owned(),
    };
    sanitize_agent_launch_settings("claude", &mut claude_settings);

    // Invalid mode and effort should be cleared.
    assert!(claude_settings.mode.is_empty());
    assert!(claude_settings.effort.is_empty());
    // Model is free-form so preserved.
    assert_eq!(claude_settings.model, "my-model");
    // Duplicate flag deduplicated and unknown flag pruned.
    assert_eq!(claude_settings.flags, vec!["skip-permissions".to_owned()]);
    // Custom command cleared for standard agent.
    assert!(claude_settings.custom_command.is_empty());

    // Flag conflicting with mode:
    let mut codex_settings = AgentLaunchSettings {
        model: String::new(),
        mode: "read-only".to_owned(),
        effort: String::new(),
        // approve-for-me conflicts with mode in codex
        flags: vec!["approve-for-me".to_owned(), "search".to_owned()],
        custom_command: String::new(),
    };
    sanitize_agent_launch_settings("codex", &mut codex_settings);
    assert_eq!(codex_settings.mode, "read-only");
    assert_eq!(codex_settings.flags, vec!["search".to_owned()]);
}

