/// RAII test harness for session file tree integration tests.
/// Automatically cleans up scratch directories on drop.
#[cfg(test)]
pub(crate) struct SessionTreeTestFixture {
    pub(crate) root: PathBuf,
    pub(crate) project_path: PathBuf,
    pub(crate) worktree_path: PathBuf,
    pub(crate) project: Project,
    pub(crate) normal_session: Session,
    pub(crate) worktree_session: Session,
    pub(crate) app: OperonApp,
}

#[cfg(test)]
impl SessionTreeTestFixture {
    pub(crate) fn new(label: &str) -> Self {
        let root = temporary_directory(label);
        let project_path = root.join("project");
        let worktree_path = root.join("worktrees").join("feature-branch");

        fs::create_dir_all(project_path.join("src")).unwrap();
        fs::create_dir_all(worktree_path.join("src")).unwrap();

        fs::write(project_path.join("src/main.rs"), "// main in project\n").unwrap();
        fs::write(project_path.join("project_only.txt"), "project\n").unwrap();
        fs::write(worktree_path.join("src/main.rs"), "// main in worktree\n").unwrap();
        fs::write(worktree_path.join("worktree_only.txt"), "worktree\n").unwrap();

        let mut app = test_app(root.join("store.json"));

        let project = Project {
            id: Uuid::new_v4(),
            name: "test-project".into(),
            path: project_path.clone(),
            added_at: 0,
        };
        app.store.projects.push(project.clone());

        let mut normal_session = test_session(Uuid::new_v4(), SessionStatus::Active);
        normal_session.project_id = project.id;
        normal_session.worktree_path = None;
        app.store.sessions.push(normal_session.clone());

        let mut worktree_session = test_session(Uuid::new_v4(), SessionStatus::Active);
        worktree_session.project_id = project.id;
        worktree_session.worktree_path = Some(worktree_path.clone());
        worktree_session.branch = Some("feature-branch".to_owned());
        app.store.sessions.push(worktree_session.clone());

        app.selected_session = Some(normal_session.id);

        // Pre-populate scans so headless frames render synchronously
        app.file_cache
            .insert(project.id, list_files(&project_path, FILE_TREE_LIMIT));
        app.session_file_cache.insert(
            worktree_path.clone(),
            list_files(&worktree_path, FILE_TREE_LIMIT),
        );

        // Populate a sample prompt turn for timeline tests
        app.session_prompt_turns.insert(
            normal_session.id,
            vec![PromptTurn {
                turn: 1,
                prompt: "Initial prompt for test".into(),
                timestamp: Instant::now(),
                line: 0,
                completed: true,
            }],
        );
        app.session_prompt_turns.insert(
            worktree_session.id,
            vec![PromptTurn {
                turn: 1,
                prompt: "Worktree prompt for test".into(),
                timestamp: Instant::now(),
                line: 0,
                completed: true,
            }],
        );

        Self {
            root,
            project_path,
            worktree_path,
            project,
            normal_session,
            worktree_session,
            app,
        }
    }
}

#[cfg(test)]
impl Drop for SessionTreeTestFixture {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

#[cfg(test)]
fn collect_text_shapes(shape: &egui::epaint::Shape, out: &mut Vec<String>) {
    match shape {
        egui::epaint::Shape::Text(text) => out.push(text.galley.text().to_owned()),
        egui::epaint::Shape::Vec(children) => {
            for child in children {
                collect_text_shapes(child, out);
            }
        }
        _ => {}
    }
}

/// Headless frame renderer that runs two layout passes to resolve sizes and returns text galleys.
#[cfg(test)]
pub(crate) fn render_terminal_panel_shapes(
    app: &mut OperonApp,
    session: &Session,
    width: f32,
    height: f32,
) -> Vec<String> {
    let context = egui::Context::default();
    let screen = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(width, height),
        )),
        ..Default::default()
    };
    // Pass 1: register widget IDs and layout sizing
    let _ = context.run(screen.clone(), |ctx| {
        egui::CentralPanel::default()
            .frame(egui::Frame::NONE)
            .show(ctx, |ui| {
                app.ui_terminal_panel(ui, session);
            });
    });
    // Pass 2: resolve immediate-mode layout and extract output shapes
    let output = context.run(screen, |ctx| {
        egui::CentralPanel::default()
            .frame(egui::Frame::NONE)
            .show(ctx, |ui| {
                app.ui_terminal_panel(ui, session);
            });
    });
    let mut texts = Vec::new();
    for shape in output.shapes {
        collect_text_shapes(&shape.shape, &mut texts);
    }
    texts
}

/// F8: Default state and the fold / reopen mechanics of the side panel.
#[test]
pub(crate) fn test_session_file_tree_default_and_toggle_state() {
    let mut fixture = SessionTreeTestFixture::new("m2-toggle-default");

    // 1. The panel starts open, on its files tab.
    assert!(fixture.app.show_session_inspector);
    assert_eq!(fixture.app.session_inspector_tab, InspectorTab::Files);

    // 2. At 1200px the files tab draws the tree, and the header names the project.
    let shapes =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes.iter().any(|s| s.contains("project_only.txt")));
    assert!(shapes.iter().any(|s| s.contains("test-project")));
    // While it is open, the header has no reopen button.
    assert!(!shapes.iter().any(|s| s.contains(ICON_FOLDER_OPEN)));

    // 3. Folded: the tree is gone even at 1200px, and the header offers it back.
    fixture.app.show_session_inspector = false;
    let shapes_off =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(!shapes_off.iter().any(|s| s.contains("project_only.txt")));
    assert!(shapes_off.iter().any(|s| s.contains(ICON_FOLDER_OPEN)));

    // 4. Reopened: the tree comes back.
    fixture.app.show_session_inspector = true;
    let shapes_on =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_on.iter().any(|s| s.contains("project_only.txt")));

    // 5. The conversation tab shows the turns instead of the tree.
    fixture.app.session_inspector_tab = InspectorTab::Conversation;
    let shapes_turns =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_turns
        .iter()
        .any(|s| s.contains("Initial prompt for test")));
    assert!(!shapes_turns.iter().any(|s| s.contains("project_only.txt")));
}

/// F7: Responsive width threshold: the panel needs 640px, and is one panel at
/// every width above it.
#[test]
pub(crate) fn test_session_file_tree_responsive_width_thresholds() {
    let mut fixture = SessionTreeTestFixture::new("m2-responsive-widths");
    assert!(fixture.app.show_session_inspector);
    let panel_drawn = |shapes: &[String]| shapes.iter().any(|s| s.contains("会話 1"));

    for (width, drawn) in [
        (350.0, false),
        (600.0, false),
        (639.0, false),
        (640.0, true),
        (800.0, true),
        (960.0, true),
        (1200.0, true),
    ] {
        let shapes =
            render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, width, 600.0);
        assert_eq!(panel_drawn(&shapes), drawn, "panel at {width}px");
        assert_eq!(
            shapes.iter().any(|s| s.contains("project_only.txt")),
            drawn,
            "files tab at {width}px"
        );
    }

    // Resizing across frames: 1200 -> 600 -> 800 -> 1200.
    for (width, drawn) in [
        (1200.0, true),
        (600.0, false),
        (800.0, true),
        (1200.0, true),
    ] {
        let shapes =
            render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, width, 600.0);
        assert_eq!(
            panel_drawn(&shapes),
            drawn,
            "panel at {width}px in sequence"
        );
    }
}

/// F9 & F10: Filesystem scoping & scan cache isolation between project root and worktrees.
#[test]
pub(crate) fn test_session_file_tree_scoping_non_worktree_vs_worktree() {
    let mut fixture = SessionTreeTestFixture::new("m2-scoping-caches");

    // 1. Normal session (no worktree): roots to project.path
    let normal_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(normal_shapes.iter().any(|s| s.contains("project_only.txt")));
    assert!(normal_shapes.iter().any(|s| s.contains("test-project")));
    assert!(!normal_shapes
        .iter()
        .any(|s| s.contains("worktree_only.txt")));

    // 2. Worktree session: roots to session.worktree_path
    let worktree_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.worktree_session, 1200.0, 800.0);
    assert!(worktree_shapes
        .iter()
        .any(|s| s.contains("worktree_only.txt")));
    assert!(worktree_shapes.iter().any(|s| s.contains("feature-branch")));
    assert!(!worktree_shapes
        .iter()
        .any(|s| s.contains("project_only.txt")));

    // 3. Cache isolation: both caches hold their respective trees without collision
    assert!(fixture.app.file_cache.contains_key(&fixture.project.id));
    assert!(fixture
        .app
        .session_file_cache
        .contains_key(&fixture.worktree_path));

    let project_scan = fixture.app.file_cache.get(&fixture.project.id).unwrap();
    assert!(project_scan
        .paths
        .iter()
        .any(|p| p.to_string_lossy().contains("project_only.txt")));
    assert!(!project_scan
        .paths
        .iter()
        .any(|p| p.to_string_lossy().contains("worktree_only.txt")));

    let worktree_scan = fixture
        .app
        .session_file_cache
        .get(&fixture.worktree_path)
        .unwrap();
    assert!(worktree_scan
        .paths
        .iter()
        .any(|p| p.to_string_lossy().contains("worktree_only.txt")));
    assert!(!worktree_scan
        .paths
        .iter()
        .any(|p| p.to_string_lossy().contains("project_only.txt")));

    // 4. Repeated alternate rendering maintains clean separation
    for _ in 0..3 {
        let norm =
            render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
        assert!(norm.iter().any(|s| s.contains("project_only.txt")));
        assert!(!norm.iter().any(|s| s.contains("worktree_only.txt")));

        let wt = render_terminal_panel_shapes(
            &mut fixture.app,
            &fixture.worktree_session,
            1200.0,
            800.0,
        );
        assert!(wt.iter().any(|s| s.contains("worktree_only.txt")));
        assert!(!wt.iter().any(|s| s.contains("project_only.txt")));
    }
}

/// F11: In-place directory expand/collapse tracking via expanded_directories.
#[test]
pub(crate) fn test_session_file_tree_expand_collapse_state() {
    let mut fixture = SessionTreeTestFixture::new("m2-expand-collapse");

    // Create deeply nested hierarchy: src/nested/sub/deep.rs
    let nested_dir = fixture.project_path.join("src").join("nested").join("sub");
    fs::create_dir_all(&nested_dir).unwrap();
    fs::write(nested_dir.join("deep.rs"), "// deep file\n").unwrap();

    // Re-scan project into cache and invalidate tree caches
    fixture.app.file_cache.insert(
        fixture.project.id,
        list_files(&fixture.project_path, FILE_TREE_LIMIT),
    );
    fixture.app.session_file_tree_cache = None;
    fixture.app.file_tree_cache = None;

    // 1. Initial frame: expanded_directories is empty
    assert!(fixture.app.expanded_directories.is_empty());
    let shapes_closed =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_closed.iter().any(|s| s.contains("src")));
    assert!(!shapes_closed.iter().any(|s| s.contains("nested")));
    assert!(!shapes_closed.iter().any(|s| s.contains("sub")));
    assert!(!shapes_closed.iter().any(|s| s.contains("deep.rs")));

    // 2. Expand "src"
    fixture
        .app
        .expanded_directories
        .insert((fixture.project.id, PathBuf::from("src")));
    let shapes_src =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_src.iter().any(|s| s.contains("src")));
    assert!(shapes_src.iter().any(|s| s.contains("nested")));
    assert!(!shapes_src.iter().any(|s| s.contains("sub")));
    assert!(!shapes_src.iter().any(|s| s.contains("deep.rs")));

    // 3. Expand "src/nested"
    fixture
        .app
        .expanded_directories
        .insert((fixture.project.id, PathBuf::from("src/nested")));
    let shapes_nested =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_nested.iter().any(|s| s.contains("sub")));
    assert!(!shapes_nested.iter().any(|s| s.contains("deep.rs")));

    // 4. Expand "src/nested/sub"
    fixture
        .app
        .expanded_directories
        .insert((fixture.project.id, PathBuf::from("src/nested/sub")));
    let shapes_sub =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_sub.iter().any(|s| s.contains("deep.rs")));

    // 5. Collapse "src": its children become hidden
    fixture
        .app
        .expanded_directories
        .remove(&(fixture.project.id, PathBuf::from("src")));
    let shapes_reclosed =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_reclosed.iter().any(|s| s.contains("src")));
    assert!(!shapes_reclosed.iter().any(|s| s.contains("nested")));
    assert!(!shapes_reclosed.iter().any(|s| s.contains("sub")));
    assert!(!shapes_reclosed.iter().any(|s| s.contains("deep.rs")));

    // 6. Re-expand "src": children reappear because child keys were preserved
    fixture
        .app
        .expanded_directories
        .insert((fixture.project.id, PathBuf::from("src")));
    let shapes_reopened =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(shapes_reopened.iter().any(|s| s.contains("src")));
    assert!(shapes_reopened.iter().any(|s| s.contains("nested")));
    assert!(shapes_reopened.iter().any(|s| s.contains("sub")));
    assert!(shapes_reopened.iter().any(|s| s.contains("deep.rs")));

    // 7. Verify shared expansion state with Page::Projects
    fixture.app.page = Page::Projects;
    fixture.app.project_tab = ProjectTab::Files;
    assert!(fixture
        .app
        .expanded_directories
        .contains(&(fixture.project.id, PathBuf::from("src"))));
    assert!(fixture
        .app
        .expanded_directories
        .contains(&(fixture.project.id, PathBuf::from("src/nested"))));
    assert!(fixture
        .app
        .expanded_directories
        .contains(&(fixture.project.id, PathBuf::from("src/nested/sub"))));
}

/// F12: File click action navigates to built-in editor without line jump.
#[test]
pub(crate) fn test_session_file_tree_click_navigates_to_editor() {
    let mut fixture = SessionTreeTestFixture::new("m2-click-editor-open");

    // 1. Normal project file open
    fixture.app.page = Page::Sessions;
    fixture.app.selected_session = Some(fixture.normal_session.id);
    fixture.app.editor_jump_line = Some(999); // Verify it is cleared to None

    fixture.app.navigate_to_file(
        &fixture.project,
        fixture.project_path.clone(),
        PathBuf::from("src/main.rs"),
        None,
    );

    assert_eq!(fixture.app.page, Page::Projects);
    assert_eq!(fixture.app.project_tab, ProjectTab::Files);
    assert_eq!(fixture.app.selected_project, Some(fixture.project.id));
    assert_eq!(fixture.app.editor_jump_line, None);
    assert!(fixture.app.active_document.is_some());

    let doc_root = fixture.app.active_document.as_ref().unwrap().root.clone();
    let doc_path = fixture.app.active_document.as_ref().unwrap().path.clone();
    let doc_project = fixture.app.active_document.as_ref().unwrap().project;
    assert_eq!(doc_project, fixture.project.id);
    assert_eq!(doc_path, PathBuf::from("src/main.rs"));
    assert_eq!(doc_root, fixture.project_path.canonicalize().unwrap());

    // 2. Worktree file open
    fixture.app.page = Page::Sessions;
    fixture.app.selected_session = Some(fixture.worktree_session.id);

    fixture.app.navigate_to_file(
        &fixture.project,
        fixture.worktree_path.clone(),
        PathBuf::from("worktree_only.txt"),
        None,
    );

    assert_eq!(fixture.app.page, Page::Projects);
    assert_eq!(fixture.app.project_tab, ProjectTab::Files);
    assert_eq!(fixture.app.selected_project, Some(fixture.project.id));
    assert_eq!(fixture.app.editor_jump_line, None);
    assert!(fixture.app.active_document.is_some());

    let wt_doc_root = fixture.app.active_document.as_ref().unwrap().root.clone();
    let wt_doc_path = fixture.app.active_document.as_ref().unwrap().path.clone();
    let wt_doc_project = fixture.app.active_document.as_ref().unwrap().project;
    assert_eq!(wt_doc_project, fixture.project.id);
    assert_eq!(wt_doc_path, PathBuf::from("worktree_only.txt"));
    assert_eq!(wt_doc_root, fixture.worktree_path.canonicalize().unwrap());

    // 3. Document indexing separation: the two documents have different roots
    assert_ne!(doc_root, wt_doc_root);
    assert_eq!(fixture.app.open_documents.len(), 2);
}

/// Resilience & edge cases: empty directories, unregistered projects, and scan requests.
#[test]
pub(crate) fn test_session_file_tree_empty_and_error_handling() {
    let mut fixture = SessionTreeTestFixture::new("m2-resilience");

    // 1. Empty project directory
    let empty_dir = fixture.root.join("empty-project");
    fs::create_dir_all(&empty_dir).unwrap();
    let empty_project = Project {
        id: Uuid::new_v4(),
        name: "empty-project".into(),
        path: empty_dir,
        added_at: 0,
    };
    fixture.app.store.projects.push(empty_project.clone());

    let mut empty_session = test_session(Uuid::new_v4(), SessionStatus::Active);
    empty_session.project_id = empty_project.id;
    fixture.app.store.sessions.push(empty_session.clone());

    fixture.app.file_cache.insert(
        empty_project.id,
        FileScanSnapshot {
            paths: Vec::new(),
            truncated: false,
            unreadable_directories: 0,
        },
    );

    let empty_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &empty_session, 1200.0, 800.0);
    assert!(empty_shapes
        .iter()
        .any(|s| s.contains("読み取り可能なファイルはありません。")));

    // 2. Unregistered project in session
    let mut orphan_session = test_session(Uuid::new_v4(), SessionStatus::Active);
    orphan_session.project_id = Uuid::new_v4(); // Not in store.projects
    fixture.app.store.sessions.push(orphan_session.clone());

    let orphan_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &orphan_session, 1200.0, 800.0);
    assert!(orphan_shapes
        .iter()
        .any(|s| s.contains("登録されていないプロジェクト")));
    // File tree is safely suppressed without panicking
    assert!(!orphan_shapes.iter().any(|s| s.contains("project_only.txt")));

    // 3. Request session files triggers background scan task
    let test_path = fixture.worktree_path.clone();
    fixture.app.request_session_files(&test_path);
    assert!(fixture
        .app
        .background_tasks
        .contains(&BackgroundKey::WorktreeFiles(test_path)));
}

/// Tier 4: Real-world developer workload scenarios (S2 & S3).
#[test]
pub(crate) fn test_session_file_tree_real_world_workload_scenarios() {
    let mut fixture = SessionTreeTestFixture::new("m2-tier4-workloads");

    // Scenario S2: Developer browsing worktree files, expanding folders, opening file in editor
    fixture.app.page = Page::Sessions;
    fixture.app.selected_session = Some(fixture.worktree_session.id);

    // Initial view: worktree tree is visible at 1200px
    let s2_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.worktree_session, 1200.0, 800.0);
    assert!(s2_shapes.iter().any(|s| s.contains("worktree_only.txt")));
    assert!(s2_shapes.iter().any(|s| s.contains("src")));

    // Expand "src" in worktree
    fixture
        .app
        .expanded_directories
        .insert((fixture.project.id, PathBuf::from("src")));
    let s2_expanded =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.worktree_session, 1200.0, 800.0);
    assert!(s2_expanded.iter().any(|s| s.contains("main.rs")));

    // Click "src/main.rs" to open in editor
    fixture.app.navigate_to_file(
        &fixture.project,
        fixture.worktree_path.clone(),
        PathBuf::from("src/main.rs"),
        None,
    );
    assert_eq!(fixture.app.page, Page::Projects);
    assert_eq!(fixture.app.project_tab, ProjectTab::Files);
    assert_eq!(fixture.app.editor_jump_line, None);
    assert_eq!(
        fixture.app.active_document.as_ref().unwrap().root,
        fixture.worktree_path.canonicalize().unwrap()
    );

    // Return to sessions view: expanded directory remains expanded
    fixture.app.page = Page::Sessions;
    let s2_return =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.worktree_session, 1200.0, 800.0);
    assert!(s2_return.iter().any(|s| s.contains("main.rs")));

    // Scenario S3: the one side panel, resizing down and back, then folded and reopened
    fixture.app.selected_session = Some(fixture.normal_session.id);

    // 1200px: terminal and the panel on its files tab
    let s3_wide =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(s3_wide.iter().any(|s| s.contains("project_only.txt")));
    assert!(s3_wide.iter().any(|s| s.contains("会話 1")));

    // Resize to 800px: the panel stays
    let s3_med =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 800.0, 800.0);
    assert!(s3_med.iter().any(|s| s.contains("project_only.txt")));

    // Resize to 600px: the panel yields, terminal occupies full width
    let s3_narrow =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 600.0, 800.0);
    assert!(!s3_narrow.iter().any(|s| s.contains("project_only.txt")));
    assert!(!s3_narrow.iter().any(|s| s.contains("会話 1")));

    // Folded at 800px: nothing beside the terminal
    fixture.app.show_session_inspector = false;
    let s3_folded =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 800.0, 800.0);
    assert!(!s3_folded.iter().any(|s| s.contains("project_only.txt")));
    assert!(!s3_folded.iter().any(|s| s.contains("会話 1")));

    // Reopened at 800px: the files tab is back
    fixture.app.show_session_inspector = true;
    let s3_open =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 800.0, 800.0);
    assert!(s3_open.iter().any(|s| s.contains("project_only.txt")));
}

/// Empirical Stress Test: Cache separation when switching to an unscanned worktree session.
#[test]
pub(crate) fn test_session_file_tree_cache_leak_on_unscanned_session_switch() {
    let mut fixture = SessionTreeTestFixture::new("m2-cache-leak");

    // 1. Render normal session first to populate session_file_tree_cache
    let normal_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
    assert!(normal_shapes.iter().any(|s| s.contains("project_only.txt")));

    // Verify session_file_tree_cache is now Some((project_path, _))
    assert!(fixture.app.session_file_tree_cache.is_some());

    // 2. Create a new worktree session that has NOT been scanned yet (session_file_cache has no entry)
    let unscanned_wt_path = fixture.root.join("worktrees").join("unscanned-branch");
    fs::create_dir_all(&unscanned_wt_path).unwrap();
    fs::write(unscanned_wt_path.join("unscanned_only.txt"), "unscanned\n").unwrap();

    let mut unscanned_session = test_session(Uuid::new_v4(), SessionStatus::Active);
    unscanned_session.project_id = fixture.project.id;
    unscanned_session.worktree_path = Some(unscanned_wt_path.clone());
    unscanned_session.branch = Some("unscanned-branch".to_owned());
    fixture.app.store.sessions.push(unscanned_session.clone());

    // Make sure session_file_cache DOES NOT contain unscanned_wt_path
    assert!(!fixture
        .app
        .session_file_cache
        .contains_key(&unscanned_wt_path));

    // 3. Render the unscanned session
    let unscanned_shapes =
        render_terminal_panel_shapes(&mut fixture.app, &unscanned_session, 1200.0, 800.0);

    // It should show loading text
    assert!(unscanned_shapes
        .iter()
        .any(|s| s.contains("プロジェクトを読み込んでいます…")));

    // CRITICAL: It MUST NOT leak the previous session's files ("project_only.txt")!
    assert!(
        !unscanned_shapes
            .iter()
            .any(|s| s.contains("project_only.txt")),
        "LEAK DETECTED: unscanned session file tree rendered stale files from previous session!"
    );
}

/// Adversarial Stress Test: Rapid multi-session switching across scanned and unscanned roots.
#[test]
pub(crate) fn test_session_file_tree_adversarial_rapid_switching_stress() {
    let mut fixture = SessionTreeTestFixture::new("m2-adversarial-stress");

    // Create 3 additional worktree directories
    let wt_scanned_path = fixture.root.join("worktrees").join("wt-scanned");
    let wt_unscanned_1 = fixture.root.join("worktrees").join("wt-unscanned-1");
    let wt_unscanned_2 = fixture.root.join("worktrees").join("wt-unscanned-2");

    fs::create_dir_all(&wt_scanned_path).unwrap();
    fs::create_dir_all(&wt_unscanned_1).unwrap();
    fs::create_dir_all(&wt_unscanned_2).unwrap();

    fs::write(wt_scanned_path.join("wt_scanned_unique.txt"), "scanned\n").unwrap();
    fs::write(
        wt_unscanned_1.join("wt_unscanned_1_unique.txt"),
        "unscanned 1\n",
    )
    .unwrap();
    fs::write(
        wt_unscanned_2.join("wt_unscanned_2_unique.txt"),
        "unscanned 2\n",
    )
    .unwrap();

    // Session for wt_scanned (pre-populated cache)
    let mut s_wt_scanned = test_session(Uuid::new_v4(), SessionStatus::Active);
    s_wt_scanned.project_id = fixture.project.id;
    s_wt_scanned.worktree_path = Some(wt_scanned_path.clone());
    fixture.app.store.sessions.push(s_wt_scanned.clone());
    fixture.app.session_file_cache.insert(
        wt_scanned_path.clone(),
        list_files(&wt_scanned_path, FILE_TREE_LIMIT),
    );

    // Session for wt_unscanned_1 (no cache)
    let mut s_wt_unscanned_1 = test_session(Uuid::new_v4(), SessionStatus::Active);
    s_wt_unscanned_1.project_id = fixture.project.id;
    s_wt_unscanned_1.worktree_path = Some(wt_unscanned_1.clone());
    fixture.app.store.sessions.push(s_wt_unscanned_1.clone());

    // Session for wt_unscanned_2 (no cache)
    let mut s_wt_unscanned_2 = test_session(Uuid::new_v4(), SessionStatus::Active);
    s_wt_unscanned_2.project_id = fixture.project.id;
    s_wt_unscanned_2.worktree_path = Some(wt_unscanned_2.clone());
    fixture.app.store.sessions.push(s_wt_unscanned_2.clone());

    // Rapid switching loop (50 iterations) alternating across:
    // normal_session (scanned) -> s_wt_unscanned_1 (unscanned) -> s_wt_scanned (scanned) -> s_wt_unscanned_2 (unscanned)
    for cycle in 0..50 {
        // 1. Normal session (scanned)
        let shapes_norm =
            render_terminal_panel_shapes(&mut fixture.app, &fixture.normal_session, 1200.0, 800.0);
        assert!(
            shapes_norm.iter().any(|s| s.contains("project_only.txt")),
            "cycle {cycle}: project_only.txt missing"
        );
        assert!(
            !shapes_norm
                .iter()
                .any(|s| s.contains("wt_scanned_unique.txt")),
            "cycle {cycle}: leak from wt_scanned to normal"
        );
        assert!(
            !shapes_norm
                .iter()
                .any(|s| s.contains("wt_unscanned_1_unique.txt")),
            "cycle {cycle}: leak from wt_unscanned_1 to normal"
        );
        assert!(
            !shapes_norm
                .iter()
                .any(|s| s.contains("wt_unscanned_2_unique.txt")),
            "cycle {cycle}: leak from wt_unscanned_2 to normal"
        );

        // 2. Unscanned session 1 (unscanned)
        let shapes_u1 =
            render_terminal_panel_shapes(&mut fixture.app, &s_wt_unscanned_1, 1200.0, 800.0);
        assert!(
            !shapes_u1.iter().any(|s| s.contains("project_only.txt")),
            "cycle {cycle}: leak from normal to unscanned 1"
        );
        assert!(
            !shapes_u1
                .iter()
                .any(|s| s.contains("wt_scanned_unique.txt")),
            "cycle {cycle}: leak from wt_scanned to unscanned 1"
        );
        if cycle <= 25 {
            assert!(
                !shapes_u1
                    .iter()
                    .any(|s| s.contains("wt_unscanned_1_unique.txt")),
                "cycle {cycle}: unscanned session should not render files before scan"
            );
        } else {
            assert!(
                shapes_u1
                    .iter()
                    .any(|s| s.contains("wt_unscanned_1_unique.txt")),
                "cycle {cycle}: scanned session should render files after scan"
            );
        }
        assert!(
            !shapes_u1
                .iter()
                .any(|s| s.contains("wt_unscanned_2_unique.txt")),
            "cycle {cycle}: leak from unscanned 2 to unscanned 1"
        );

        // 3. Scanned worktree session
        let shapes_wt =
            render_terminal_panel_shapes(&mut fixture.app, &s_wt_scanned, 1200.0, 800.0);
        assert!(
            shapes_wt
                .iter()
                .any(|s| s.contains("wt_scanned_unique.txt")),
            "cycle {cycle}: wt_scanned_unique.txt missing"
        );
        assert!(
            !shapes_wt.iter().any(|s| s.contains("project_only.txt")),
            "cycle {cycle}: leak from normal to wt_scanned"
        );
        assert!(
            !shapes_wt
                .iter()
                .any(|s| s.contains("wt_unscanned_1_unique.txt")),
            "cycle {cycle}: leak from unscanned 1 to wt_scanned"
        );

        // 4. Unscanned session 2 (unscanned)
        let shapes_u2 =
            render_terminal_panel_shapes(&mut fixture.app, &s_wt_unscanned_2, 1200.0, 800.0);
        assert!(
            !shapes_u2.iter().any(|s| s.contains("project_only.txt")),
            "cycle {cycle}: leak from normal to unscanned 2"
        );
        assert!(
            !shapes_u2
                .iter()
                .any(|s| s.contains("wt_scanned_unique.txt")),
            "cycle {cycle}: leak from wt_scanned to unscanned 2"
        );
        assert!(
            !shapes_u2
                .iter()
                .any(|s| s.contains("wt_unscanned_2_unique.txt")),
            "cycle {cycle}: unscanned session should not render files before scan"
        );

        // 5. In the middle of stress (cycle 25), complete scan for s_wt_unscanned_1
        if cycle == 25 {
            fixture.app.session_file_cache.insert(
                wt_unscanned_1.clone(),
                list_files(&wt_unscanned_1, FILE_TREE_LIMIT),
            );
            fixture.app.session_file_tree_cache = None;
        }

        if cycle > 25 {
            // Now s_wt_unscanned_1 IS scanned and should render its own files
            let shapes_u1_now =
                render_terminal_panel_shapes(&mut fixture.app, &s_wt_unscanned_1, 1200.0, 800.0);
            assert!(
                shapes_u1_now
                    .iter()
                    .any(|s| s.contains("wt_unscanned_1_unique.txt")),
                "cycle {cycle}: wt_unscanned_1_unique.txt missing after scan complete"
            );
            assert!(
                !shapes_u1_now.iter().any(|s| s.contains("project_only.txt")),
                "cycle {cycle}: leak from normal to now-scanned 1"
            );
            assert!(
                !shapes_u1_now
                    .iter()
                    .any(|s| s.contains("wt_scanned_unique.txt")),
                "cycle {cycle}: leak from wt_scanned to now-scanned 1"
            );
        }
    }
}

/// Change 076: Test image file loading for PNG, JPEG, and size limit enforcement.
#[test]
pub(crate) fn test_read_file_for_editing_image_outcome() {
    let root = std::env::temp_dir().join(format!("operon-test-img-{}", Uuid::new_v4()));
    fs::create_dir_all(&root).unwrap();

    // 1. Valid 2x3 PNG image
    let mut png_img = image::RgbaImage::new(2, 3);
    png_img.put_pixel(0, 0, image::Rgba([255, 0, 0, 255]));
    let mut png_bytes = Vec::new();
    image::DynamicImage::ImageRgba8(png_img)
        .write_to(
            &mut std::io::Cursor::new(&mut png_bytes),
            image::ImageFormat::Png,
        )
        .unwrap();
    fs::write(root.join("test.png"), &png_bytes).unwrap();

    let outcome_png = read_file_for_editing(&root, Path::new("test.png")).unwrap();
    match outcome_png {
        FileOpenOutcome::Image {
            bytes,
            width,
            height,
        } => {
            assert_eq!(width, 2);
            assert_eq!(height, 3);
            assert_eq!(bytes, png_bytes);
        }
        other => panic!("expected FileOpenOutcome::Image for valid PNG, got {other:?}"),
    }

    // 2. Valid 4x5 JPEG image
    let mut jpg_img = image::RgbaImage::new(4, 5);
    jpg_img.put_pixel(0, 0, image::Rgba([0, 255, 0, 255]));
    let mut jpg_bytes = Vec::new();
    image::DynamicImage::ImageRgba8(jpg_img)
        .write_to(
            &mut std::io::Cursor::new(&mut jpg_bytes),
            image::ImageFormat::Jpeg,
        )
        .unwrap();
    fs::write(root.join("test.jpg"), &jpg_bytes).unwrap();

    let outcome_jpg = read_file_for_editing(&root, Path::new("test.jpg")).unwrap();
    match outcome_jpg {
        FileOpenOutcome::Image {
            bytes,
            width,
            height,
        } => {
            assert_eq!(width, 4);
            assert_eq!(height, 5);
            assert_eq!(bytes, jpg_bytes);
        }
        other => panic!("expected FileOpenOutcome::Image for valid JPEG, got {other:?}"),
    }

    // 3. Oversized image exceeding EDITOR_IMAGE_MAX_BYTES
    let huge_file = root.join("huge.png");
    // Write just enough to exceed EDITOR_IMAGE_MAX_BYTES without allocating massive memory in test
    let file = fs::File::create(&huge_file).unwrap();
    file.set_len((EDITOR_IMAGE_MAX_BYTES + 1) as u64).unwrap();
    let outcome_huge = read_file_for_editing(&root, Path::new("huge.png")).unwrap();
    match outcome_huge {
        FileOpenOutcome::Unopenable(reason) => {
            assert!(
                reason.contains("MiB"),
                "expected MiB limit message, got {reason}"
            );
        }
        other => panic!("expected FileOpenOutcome::Unopenable for huge image, got {other:?}"),
    }

    fs::remove_dir_all(root).unwrap();
}

/// Change 076: Test dynamic fallback resolution in open_terminal_target when file
/// was generated after initial scan or was not yet in resolved_paths cache.
#[test]
pub(crate) fn test_open_terminal_target_dynamic_fallback_resolution() {
    let mut fixture = SessionTreeTestFixture::new("m2-dynamic-fallback-test");
    fixture.app.page = Page::Sessions;
    fixture.app.selected_session = Some(fixture.normal_session.id);

    // Initial state: "newly_generated.rs" is NOT in resolved_paths (or mapped to None)
    fixture
        .app
        .resolved_paths
        .insert("newly_generated.rs".into(), None);

    // Now CLI creates the file on disk
    let generated_file = fixture.project_path.join("newly_generated.rs");
    fs::write(&generated_file, "fn generated() {}\n").unwrap();

    // Command+click triggers open_terminal_target
    fixture.app.open_terminal_target(TerminalTargetKind::Path {
        path: "newly_generated.rs".into(),
        line: None,
    });

    // Verify dynamic fallback successfully resolved the path and navigated to editor
    assert_eq!(fixture.app.page, Page::Projects);
    assert_eq!(fixture.app.project_tab, ProjectTab::Files);
    assert_eq!(fixture.app.selected_project, Some(fixture.project.id));
    assert!(fixture.app.active_document.is_some());
    let active = fixture.app.active_document.as_ref().unwrap();
    assert_eq!(active.path, PathBuf::from("newly_generated.rs"));
    assert_eq!(
        fixture.app.resolved_paths.get("newly_generated.rs"),
        Some(&Some(generated_file.canonicalize().unwrap()))
    );
}

