/// Change 093: a tab's count is what its cache holds for this project, and
/// nothing when the cache is empty, failed, or belongs to another project.
#[test]
pub(crate) fn tab_counts_come_from_the_caches() {
    let (mut app, project, root) = launch_screen_fixture("tab-counts");
    seed_tab_caches(&mut app, &project, &root);
    assert_eq!(app.project_tab_count(ProjectTab::Git, project.id), Some(3));
    assert_eq!(
        app.project_tab_count(ProjectTab::Worktrees, project.id),
        Some(2)
    );
    assert_eq!(
        app.project_tab_count(ProjectTab::PullRequests, project.id),
        Some(1)
    );
    for tab in [
        ProjectTab::Overview,
        ProjectTab::Files,
        ProjectTab::AgentSettings,
    ] {
        assert_eq!(app.project_tab_count(tab, project.id), None, "{tab:?}");
    }
    let other = Uuid::new_v4();
    for tab in ProjectTab::all() {
        assert_eq!(
            app.project_tab_count(tab, other),
            None,
            "{tab:?} of another project"
        );
    }
    app.git_changes_cache
        .insert(project.id, Err("not a git repository".into()));
    assert_eq!(
        app.project_tab_count(ProjectTab::Git, project.id),
        None,
        "an error is not zero"
    );
    fs::remove_dir_all(&root).ok();
}

