/// Change 093: 変更's number is the accent colour when something is
/// uncommitted, and only then; a tab without a count is just its label.
#[test]
pub(crate) fn only_a_nonzero_change_count_is_emphasised() {
    let palette = Store::default().theme.palette();
    let figure_colour = |count: Option<usize>, emphasise: bool| {
        let context = egui::Context::default();
        // The app's sizes, where Body and Button differ; egui's defaults are
        // equal and would hide a tab drawn at the wrong one.
        apply_interface_metrics(&context);
        let button = egui::TextStyle::Button.resolve(&context.style()).size;
        let drawn = context.run(Default::default(), |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| {
                tab_item_with_count(ui, palette, "変更", count, emphasise, false);
            });
        });
        type Found = Option<(String, Vec<egui::Color32>, Vec<f32>)>;
        let mut found = None;
        fn visit(shape: &egui::epaint::Shape, found: &mut Found) {
            match shape {
                egui::epaint::Shape::Text(text) if text.galley.text().starts_with("変更") => {
                    let sections = &text.galley.job.sections;
                    *found = Some((
                        text.galley.text().to_owned(),
                        sections
                            .iter()
                            .map(|section| section.format.color)
                            .collect(),
                        sections
                            .iter()
                            .map(|section| section.format.font_id.size)
                            .collect(),
                    ));
                }
                egui::epaint::Shape::Vec(children) => {
                    for child in children {
                        visit(child, found);
                    }
                }
                _ => {}
            }
        }
        for clipped in &drawn.shapes {
            visit(&clipped.shape, &mut found);
        }
        let (text, colours, sizes) = found.expect("the tab is drawn");
        // Every tab in the row is the button size, counted or not.
        assert!(
            sizes.iter().all(|size| *size == button),
            "{text:?} is drawn at the button size {button}, not {sizes:?}"
        );
        (text, colours)
    };

    let (text, colours) = figure_colour(Some(3), true);
    assert_eq!(text, "変更 3");
    assert_eq!(colours.last(), Some(&palette.accent), "3 changes: accent");
    assert_ne!(colours.first(), Some(&palette.accent), "the label is not");

    let (text, colours) = figure_colour(Some(0), true);
    assert_eq!(text, "変更 0");
    assert!(
        !colours.contains(&palette.accent),
        "no changes: nothing asks for attention"
    );

    let (text, colours) = figure_colour(Some(3), false);
    assert_eq!(text, "変更 3");
    assert!(!colours.contains(&palette.accent), "not emphasised: plain");

    let (text, _) = figure_colour(None, true);
    assert_eq!(text, "変更", "no count: the bare label");
}

