/// Every `evals/NNN-*.md`, as (file name, text). The README is not an eval.
fn eval_documents() -> Vec<(String, String)> {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let mut documents: Vec<(String, String)> = fs::read_dir(root.join("evals"))
        .unwrap()
        .flatten()
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .filter(|name| name.ends_with(".md") && name != "README.md")
        .map(|name| {
            let text = fs::read_to_string(root.join("evals").join(&name)).unwrap();
            (name, text)
        })
        .collect();
    documents.sort();
    documents
}

/// The non-blank lines of the first fenced block under `## <heading>`.
fn eval_section_lines(text: &str, heading: &str) -> Vec<String> {
    let Some((_, rest)) = text.split_once(&format!("## {heading}\n")) else {
        return Vec::new();
    };
    rest.lines()
        .skip_while(|line| !line.trim_start().starts_with("```"))
        .skip(1)
        .take_while(|line| !line.trim_start().starts_with("```"))
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(str::to_owned)
        .collect()
}

#[test]
/// Change 103: the held-out split is what tells a hillclimb that fitted the
/// steering to the evals from one that improved it. An eval with no split is in
/// neither set, and a split with nothing in it holds nothing out.
pub(crate) fn every_eval_declares_a_split_and_both_splits_are_used() {
    let mut problems = Vec::new();
    let (mut train, mut test) = (0, 0);
    for (name, text) in eval_documents() {
        match text
            .lines()
            .find_map(|line| line.strip_prefix("split: "))
            .map(str::trim)
        {
            Some("train") => train += 1,
            Some("test") => test += 1,
            Some(other) => problems.push(format!("{name}: split `{other}` は train か test です")),
            None => problems.push(format!("{name}: front matter に split がありません")),
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
    assert!(
        train > 0 && test > 0,
        "train が {train} 件、test が {test} 件です。両方に eval が要ります"
    );
}

#[test]
/// Change 103: pasting a failed eval's prompt into the steering raises the score
/// and teaches nothing that reaches a person's next request — the overfitting the
/// hillclimb procedure in evals/README.md forbids. This is that rule as a check.
pub(crate) fn no_eval_prompt_is_pasted_into_the_steering() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let mut documents: Vec<PathBuf> = ["CLAUDE.md", "AGENTS.md", "REVIEW.md"]
        .iter()
        .map(|name| root.join(name))
        .collect();
    let mut pending = vec![root.join(".claude/rules"), root.join(".claude/skills")];
    while let Some(directory) = pending.pop() {
        for entry in fs::read_dir(&directory).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                pending.push(path);
            } else {
                documents.push(path);
            }
        }
    }
    let steering: Vec<(PathBuf, String)> = documents
        .into_iter()
        .filter_map(|path| fs::read_to_string(&path).ok().map(|text| (path, text)))
        .collect();
    assert!(
        steering.len() > 3,
        "steering の文書が読めていません: {}",
        steering.len()
    );

    let mut pasted = Vec::new();
    let mut prompts = 0;
    for (name, text) in eval_documents() {
        for line in eval_section_lines(&text, "Prompt") {
            prompts += 1;
            for (path, body) in &steering {
                if body.contains(&line) {
                    pasted.push(format!(
                        "{name} の prompt「{line}」が {} にあります",
                        path.strip_prefix(&root).unwrap_or(path).display()
                    ));
                }
            }
        }
    }
    assert!(prompts > 0, "eval の prompt が一行も読めていません");
    assert!(pasted.is_empty(), "{}", pasted.join("\n"));
}

/// Stand-in for an agent CLI in the runner tests. A keyword in the prompt picks
/// the behaviour; every call records its arguments, the eval files it can see,
/// and `git status`, before it writes anything of its own.
const EVAL_RUNNER_STUB_AGENT: &str = r#"#!/bin/bash
prompt=""
previous=""
for argument in "$@"; do
  if [ "$previous" = "-p" ]; then prompt="$argument"; fi
  previous="$argument"
done
status=$(git status --porcelain)
cat evals/[0-9]*.md > seen-evals.txt 2>/dev/null
printf '%s' "$status" > seen-status.txt
printf '%s\n' "$@" > seen-arguments.txt
git branch --show-current > seen-branch.txt
case "$prompt" in
  *CRASH*) exit 1 ;;
  *PEEK*)
    printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"git show HEAD:evals/001-work.md"}}]}}'
    echo done > answer.txt ;;
  *DO-WORK*) echo done > answer.txt ;;
esac
printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"duration_ms":5,"num_turns":1,"total_cost_usd":0.25}'
"#;

/// One fixture eval: (file stem, split, prompt, check).
type FixtureEval<'a> = (&'a str, &'a str, &'a str, &'a str);

fn fixture_eval_text((stem, split, prompt, check): FixtureEval) -> String {
    let id = &stem[..3];
    format!(
        "---\nid: {id}\ntitle: eval {stem}\nsplit: {split}\nseeded-by: lesson SECRET-SEED\nguards: SECRET-GUARD\n---\n\n## Setup\n\n```sh\n: SECRET-SETUP\n```\n\n## Prompt\n\n```text\n{prompt}\n```\n\n## Check\n\n```sh\n: SECRET-CHECK\n{check}\n```\n"
    )
}

/// A scratch repository holding a copy of `scripts/run-evals.sh` and `evals`,
/// committed, with the stub agent beside them and not committed. A copy, because
/// the script finds its repository from its own path.
fn eval_runner_fixture(label: &str, evals: &[FixtureEval]) -> PathBuf {
    let root = temporary_directory(label);
    fs::create_dir_all(root.join("scripts")).unwrap();
    fs::create_dir_all(root.join("evals")).unwrap();
    let source = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("scripts/run-evals.sh");
    fs::copy(source, root.join("scripts/run-evals.sh")).unwrap();
    for eval in evals {
        fs::write(
            root.join("evals").join(format!("{}.md", eval.0)),
            fixture_eval_text(*eval),
        )
        .unwrap();
    }
    // Named, so no protected branch exists in the fixture to collide with.
    git_in(&root, &["init", "-q", "-b", "fixture"]);
    git_in(&root, &["config", "user.email", "test@example.invalid"]);
    git_in(&root, &["config", "user.name", "Operon test"]);
    git_in(&root, &["add", "-A"]);
    git_in(&root, &["commit", "-qm", "fixture"]);
    let stub = root.join("stub-agent.sh");
    fs::write(&stub, EVAL_RUNNER_STUB_AGENT).unwrap();
    fs::set_permissions(&stub, fs::Permissions::from_mode(0o755)).unwrap();
    root
}

/// Runs the copied runner with `agent` as `EVAL_AGENT`; exit code and all output.
fn run_eval_runner(root: &Path, agent: &Path, arguments: &[&str]) -> (i32, String) {
    let mut command = Command::new("/bin/bash");
    command
        .arg(root.join("scripts/run-evals.sh"))
        .args(arguments)
        .current_dir(root)
        .env("EVAL_AGENT", agent)
        .env("EVAL_TIMEOUT", "60");
    forget_inherited_repository(&mut command);
    let output = command.output().unwrap();
    let mut printed = String::from_utf8_lossy(&output.stdout).into_owned();
    printed.push_str(&String::from_utf8_lossy(&output.stderr));
    (output.status.code().unwrap_or(-1), printed)
}

/// The 95% Wilson interval the runner prints, computed here independently.
fn wilson_line(passed: u32, judged: u32) -> String {
    let (p, n, z) = (
        f64::from(passed) / f64::from(judged),
        f64::from(judged),
        1.96_f64,
    );
    let denominator = 1.0 + z * z / n;
    let centre = (p + z * z / (2.0 * n)) / denominator;
    let half = z * (p * (1.0 - p) / n + z * z / (4.0 * n * n)).sqrt() / denominator;
    format!(
        "evals: {passed}/{judged} passed ({:.1}%, 95% CI {:.1}-{:.1}%)",
        100.0 * p,
        100.0 * (centre - half).max(0.0),
        100.0 * (centre + half).min(1.0)
    )
}

fn eval_results_directory(printed: &str) -> PathBuf {
    let summary = printed
        .lines()
        .find_map(|line| line.strip_prefix("results: "))
        .unwrap_or_else(|| panic!("results の行がありません:\n{printed}"));
    PathBuf::from(summary).parent().unwrap().to_path_buf()
}

/// The worktree `--keep` left, read from the runner's own report of it.
fn kept_eval_worktree(printed: &str) -> PathBuf {
    let kept = printed
        .lines()
        .find_map(|line| line.trim().strip_prefix("worktree kept at "))
        .unwrap_or_else(|| panic!("worktree kept at の行がありません:\n{printed}"));
    PathBuf::from(kept)
}

/// A kept worktree sits in its own temporary directory outside the fixture.
fn discard_kept_eval_worktree(worktree: &Path) {
    if let Some(parent) = worktree.parent() {
        fs::remove_dir_all(parent).ok();
    }
}

#[test]
/// Change 103: one run per eval is one sample. With repeats, a run that died
/// outside the steering (`infra`) and a check that changed its mind
/// (`unstable`) are counted apart from the rate, and the rate carries its
/// interval.
pub(crate) fn the_eval_runner_judges_every_run_and_keeps_infra_and_unstable_out_of_the_rate() {
    let root = eval_runner_fixture(
        "eval-runner-outcomes",
        &[
            ("001-work", "train", "DO-WORK please", "test -f answer.txt"),
            ("002-idle", "train", "DO-NOTHING please", "test -f answer.txt"),
            ("003-crash", "test", "CRASH please", "test -f answer.txt"),
            ("004-peek", "train", "PEEK please", "test -f answer.txt"),
            (
                "005-flip",
                "test",
                "DO-WORK please",
                "n=$(cat counter 2>/dev/null || echo 0); echo $((n + 1)) > counter; [ $((n % 2)) -eq 0 ]",
            ),
        ],
    );
    let (code, printed) = run_eval_runner(
        &root,
        &root.join("stub-agent.sh"),
        &["--runs", "2", "--recheck"],
    );
    assert_eq!(
        code, 1,
        "失敗した run があるのに exit 1 ではありません:\n{printed}"
    );
    for expected in [
        "eval 001   2/2 passed\n",
        "eval 002   0/2 passed\n",
        "eval 003   0/0 passed  (2 infra)\n",
        "eval 004   2/2 passed\n",
        "eval 005   0/0 passed  (2 unstable)\n",
        &wilson_line(4, 6),
        "infra 2, unstable 2, peeked 2\n",
        "warning: eval 002 failed every judged run",
    ] {
        assert!(
            printed.contains(expected),
            "`{expected}` がありません:\n{printed}"
        );
    }
    assert!(
        !printed.contains("no headroom"),
        "二回ずつの run で headroom の警告が出ています:\n{printed}"
    );

    let results = eval_results_directory(&printed);
    let table = fs::read_to_string(results.join("results.tsv")).unwrap();
    let rows: Vec<Vec<&str>> = table
        .lines()
        .skip(1)
        .map(|line| line.split('\t').collect())
        .collect();
    assert_eq!(rows.len(), 10, "run ごとに一行のはずです:\n{table}");
    assert!(rows
        .iter()
        .any(|row| row[..4] == ["004", "1", "pass", "yes"] && row[4] == "0.25"));
    assert!(rows.iter().any(|row| row[..3] == ["003", "2", "infra"]));
    let summary = fs::read_to_string(results.join("summary.md")).unwrap();
    assert!(summary.contains("[transcript](001/1/transcript.jsonl)"));
    assert!(summary.contains("[check](002/2/check.log)"));
    assert!(results.join("001/1/transcript.jsonl").is_file());
    assert!(results.join("002/2/check.log").is_file());
    assert!(results.join("005/1/check-2.log").is_file());

    // A run that started and died is still a run that did not pass.
    let (code, printed) = run_eval_runner(&root, &root.join("stub-agent.sh"), &["--only", "003"]);
    assert_eq!(
        code, 1,
        "infra だけの選択が exit 1 になりません:\n{printed}"
    );
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 103: an agent that can read the check is not being measured. While it
/// works, each eval file is its id, title, split and prompt — no setup, no check,
/// and no `guards:` naming the test the check leans on — and `git status` does
/// not show the rewrite. The real file is back before the check runs.
pub(crate) fn the_eval_runner_hides_the_check_while_the_agent_works() {
    let eval = ("001-work", "train", "DO-WORK please", "test -f answer.txt");
    let root = eval_runner_fixture("eval-runner-hiding", &[eval]);
    let (code, printed) = run_eval_runner(&root, &root.join("stub-agent.sh"), &["--keep"]);
    assert_eq!(code, 0, "{printed}");
    let worktree = kept_eval_worktree(&printed);
    assert!(
        !worktree.starts_with(&root),
        "worktree がリポジトリの中にあります。本体の evals と CLAUDE.md が ../ から届きます: {}",
        worktree.display()
    );
    let seen = fs::read_to_string(worktree.join("seen-evals.txt")).unwrap();
    assert_eq!(
        seen,
        "---\nid: 001\ntitle: eval 001-work\nsplit: train\n---\n\n## Prompt\n\n```text\nDO-WORK please\n```\n\n## Check\n\n```sh\n# Hidden by scripts/run-evals.sh while an agent runs.\nexit 0\n```\n"
    );
    assert_eq!(
        fs::read_to_string(worktree.join("seen-status.txt")).unwrap(),
        "",
        "隠した書き換えが git status に見えています"
    );
    assert_eq!(
        fs::read_to_string(worktree.join("evals/001-work.md")).unwrap(),
        fixture_eval_text(eval),
        "check の前に eval が元に戻っていません"
    );
    assert_eq!(
        git_in(
            &worktree,
            &["status", "--porcelain", "--untracked-files=no"]
        ),
        ""
    );
    assert!(
        !git_in(&worktree, &["ls-files", "-v", "evals"])
            .lines()
            .any(|line| line.starts_with('S')),
        "skip-worktree が残っています"
    );
    discard_kept_eval_worktree(&worktree);
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 104: the agent under test runs with this repository's hooks, and the
/// worktree-policy guard fails closed on a branch it cannot name. A detached
/// eval worktree therefore refused every edit, and every eval that edits a file
/// failed for a reason that had nothing to do with the steering. The worktree
/// the agent works in has to be on a named branch the policy does not protect.
/// The policy is read, not restated, so a widened policy turns this red.
pub(crate) fn the_eval_worktree_is_on_a_branch_the_worktree_policy_lets_the_agent_edit() {
    let policy: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(".claude/config/worktree-policy.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_ne!(
        policy["enforce_worktree_all_branches"],
        serde_json::Value::Bool(true),
        "全 branch が保護されると、eval の worktree では agent が何も編集できません"
    );
    let protected: Vec<&str> = policy["protected_branches"]
        .as_array()
        .expect("protected_branches が配列ではありません")
        .iter()
        .filter_map(serde_json::Value::as_str)
        .collect();

    let root = eval_runner_fixture(
        "eval-runner-branch",
        &[("001-work", "train", "DO-WORK please", "test -f answer.txt")],
    );
    let (code, printed) = run_eval_runner(&root, &root.join("stub-agent.sh"), &["--keep"]);
    assert_eq!(code, 0, "{printed}");
    let worktree = kept_eval_worktree(&printed);
    let branch = fs::read_to_string(worktree.join("seen-branch.txt")).unwrap();
    let branch = branch.trim();
    discard_kept_eval_worktree(&worktree);
    assert!(
        !branch.is_empty(),
        "eval の worktree が detached HEAD です。worktree-policy が branch を判定できず、編集をすべて拒否します"
    );
    assert!(
        !protected.contains(&branch),
        "eval の worktree が保護された branch `{branch}` にあります"
    );

    // A kept run leaves its branch for inspection; an ordinary run does not.
    let (code, printed) = run_eval_runner(&root, &root.join("stub-agent.sh"), &[]);
    assert_eq!(code, 0, "{printed}");
    let left: Vec<String> = git_in(&root, &["branch", "--list", "eval/*"])
        .lines()
        .map(|line| line.trim().to_owned())
        .collect();
    assert_eq!(left.len(), 1, "--keep の分だけ残るはずです: {left:?}");
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 103: a hide that did not take is not a run. Here setup holds the
/// worktree's index lock, so the checks cannot be hidden; the agent must not
/// start with the answer in view, and the run is `infra`, not a verdict.
pub(crate) fn the_eval_runner_does_not_run_the_agent_when_the_check_cannot_be_hidden() {
    let root = eval_runner_fixture(
        "eval-runner-hide-fails",
        &[("001-work", "train", "DO-WORK please", "test -f answer.txt")],
    );
    let locked = fixture_eval_text((
        "002-locked",
        "train",
        "DO-WORK please",
        "test -f answer.txt",
    ))
    .replace(
        ": SECRET-SETUP",
        "touch \"$(git rev-parse --git-dir)/index.lock\"",
    );
    fs::write(root.join("evals/002-locked.md"), locked).unwrap();
    git_in(&root, &["add", "-A", "evals"]);
    git_in(&root, &["commit", "-qm", "locked eval"]);

    let (code, printed) = run_eval_runner(
        &root,
        &root.join("stub-agent.sh"),
        &["--only", "002", "--keep"],
    );
    assert_eq!(code, 1, "{printed}");
    assert!(printed.contains("could not hide the checks"), "{printed}");
    assert!(
        printed.contains("eval 002   0/0 passed  (1 infra)"),
        "{printed}"
    );
    let worktree = kept_eval_worktree(&printed);
    assert!(
        !worktree.join("seen-evals.txt").exists(),
        "check を隠せなかったのに agent が走りました"
    );
    discard_kept_eval_worktree(&worktree);
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 103: the same suite on a weaker and a stronger configuration is how a
/// suite whose score does not rise with capability shows itself.
pub(crate) fn the_eval_runner_passes_the_model_and_effort_through() {
    let root = eval_runner_fixture(
        "eval-runner-arguments",
        &[("001-work", "train", "DO-WORK please", "test -f answer.txt")],
    );
    let stub = root.join("stub-agent.sh");

    let (code, printed) = run_eval_runner(
        &root,
        &stub,
        &["--keep", "--model", "model-x", "--effort", "effort-y"],
    );
    assert_eq!(code, 0, "{printed}");
    let worktree = kept_eval_worktree(&printed);
    let given = fs::read_to_string(worktree.join("seen-arguments.txt")).unwrap();
    discard_kept_eval_worktree(&worktree);
    assert!(given.contains("--model\nmodel-x\n"), "{given}");
    assert!(given.contains("--effort\neffort-y\n"), "{given}");
    assert!(given.starts_with("-p\nDO-WORK please\n"), "{given}");

    let (code, printed) = run_eval_runner(&root, &stub, &["--keep"]);
    assert_eq!(code, 0, "{printed}");
    let worktree = kept_eval_worktree(&printed);
    let plain = fs::read_to_string(worktree.join("seen-arguments.txt")).unwrap();
    discard_kept_eval_worktree(&worktree);
    assert!(
        !plain.contains("--model") && !plain.contains("--effort"),
        "{plain}"
    );
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 103: a suite that passes nearly everything cannot show a gain, and the
/// summary says so rather than reporting a perfect score as good news.
pub(crate) fn the_eval_runner_warns_when_the_suite_has_no_headroom() {
    let root = eval_runner_fixture(
        "eval-runner-headroom",
        &[("001-work", "train", "DO-WORK please", "test -f answer.txt")],
    );
    let (code, printed) = run_eval_runner(&root, &root.join("stub-agent.sh"), &["--runs", "3"]);
    assert_eq!(code, 0, "{printed}");
    assert!(printed.contains(&wilson_line(3, 3)), "{printed}");
    assert!(printed.contains("no headroom"), "{printed}");
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 103: `--split` is how a hillclimb reads only its training evals, and
/// `--list` is where a person sees which is which.
pub(crate) fn the_eval_runner_selects_by_split_and_lists_it() {
    let root = eval_runner_fixture(
        "eval-runner-split",
        &[
            ("001-work", "train", "DO-WORK please", "test -f answer.txt"),
            ("002-work", "test", "DO-WORK please", "test -f answer.txt"),
        ],
    );
    let stub = root.join("stub-agent.sh");
    let (code, listed) = run_eval_runner(&root, &stub, &["--list"]);
    assert_eq!(code, 0, "{listed}");
    assert!(listed.contains("001    train  eval 001-work"), "{listed}");
    assert!(listed.contains("002    test   eval 002-work"), "{listed}");

    let (code, printed) = run_eval_runner(&root, &stub, &["--split", "test"]);
    assert_eq!(code, 0, "{printed}");
    assert!(printed.contains("=== eval 002 "), "{printed}");
    assert!(!printed.contains("=== eval 001 "), "{printed}");

    let (code, printed) = run_eval_runner(&root, &stub, &["--split", "holdout"]);
    assert_eq!(code, 2, "{printed}");
    fs::remove_dir_all(&root).ok();
}

#[test]
/// Change 103: exit 3 means nothing could start, which CI reads differently
/// from a failure — no agent, or a selection that matched nothing.
pub(crate) fn the_eval_runner_exits_3_when_nothing_can_start() {
    let root = eval_runner_fixture(
        "eval-runner-nothing",
        &[("001-work", "train", "DO-WORK please", "test -f answer.txt")],
    );
    let stub = root.join("stub-agent.sh");
    let (code, printed) = run_eval_runner(&root, &stub, &["--only", "999"]);
    assert_eq!(code, 3, "{printed}");
    let (code, printed) = run_eval_runner(&root, &root.join("no-such-agent"), &[]);
    assert_eq!(code, 3, "{printed}");
    assert!(printed.contains("no eval could run"), "{printed}");
    fs::remove_dir_all(&root).ok();
}
